/// Spawn guards for the live exit-mapping cell below: `Child::drop`
/// neither kills nor reaps, so every owned fixture child is wrapped
/// and drops kill and reap. Module-level (unlike the file's usual
/// fn-local guards) so the drop contract below tests them directly.
struct ExitMappingChildGuard(std::process::Child);

impl Drop for ExitMappingChildGuard {
    fn drop(&mut self) {
        let _ = self.0.kill();
        let _ = self.0.wait();
    }
}

struct ExitMappingChildrenGuard(Vec<std::process::Child>);

impl Drop for ExitMappingChildrenGuard {
    fn drop(&mut self) {
        for child in &mut self.0 {
            let _ = child.kill();
            let _ = child.wait();
        }
    }
}

/// The live cell below spawns a root holder plus three short-lived
/// children; `Child::drop` neither kills nor reaps, so every owned
/// child is wrapped in a guard whose drop kills and reaps. A panic
/// between spawn and reap (settle, the spawn window, drain, the
/// deadline) must still converge: no leaked holder, no lost cgroup.
#[test]
fn exit_mapping_spawn_guards_reap_dropped_children() {
    fn live(pid: u32) -> bool {
        std::path::Path::new(&format!("/proc/{pid}")).exists()
    }
    // Holder shape: dropping the single guard kills and reaps.
    let holder_pid = {
        let guard = ExitMappingChildGuard(
            std::process::Command::new("sleep")
                .arg("30")
                .spawn()
                .expect("spawn sleep"),
        );
        let pid = guard.0.id();
        assert!(live(pid), "the fixture child must be alive before the drop");
        drop(guard);
        pid
    };
    assert!(
        !live(holder_pid),
        "dropping the guard must reap the child, pid {holder_pid} is still live"
    );
    // Spawn-window shape: drained children are reaped explicitly,
    // whatever a panic leaves behind dies with the guard.
    let batch_pids = {
        let mut batch = ExitMappingChildrenGuard(
            (0..2)
                .map(|_| {
                    std::process::Command::new("sleep")
                        .arg("30")
                        .spawn()
                        .expect("spawn sleep")
                })
                .collect(),
        );
        let pids: Vec<u32> = batch.0.iter().map(|child| child.id()).collect();
        assert!(
            pids.iter().all(|pid| live(*pid)),
            "both batch children must be alive before the drop"
        );
        for mut child in batch.0.drain(..1) {
            child.kill().expect("reap the drained child");
            child.wait().expect("wait for the drained child");
        }
        drop(batch);
        pids
    };
    assert!(
        batch_pids.iter().all(|pid| !live(*pid)),
        "dropping the guard must reap the batch, still live: {batch_pids:?}"
    );
}

/// Reap helper for the live exit-mapping cell's spawn window: reaps
/// each owned child in role order through `reap`. Each child leaves
/// the guard only when its own reap starts, so a panic mid-reap
/// leaves the remainder guarded: the guard's drop still kills and
/// reaps them. (A `Vec::drain` would detach the whole batch up
/// front, and its drop would discard the unreaped remainder with no
/// kill or wait.)
fn reap_owned_children(
    owned: &mut ExitMappingChildrenGuard,
    roles: &[&str],
    mut reap: impl FnMut(std::process::Child, &str),
) {
    assert_eq!(
        owned.0.len(),
        roles.len(),
        "one role per owned child: {} children, {} roles",
        owned.0.len(),
        roles.len()
    );
    for role in roles {
        reap(owned.0.remove(0), role);
    }
}

/// A panic mid-reap must not leak the children the loop never
/// reached: whatever the reap loop has not consumed stays in the
/// guard and dies with it.
#[test]
fn exit_mapping_children_guard_reaps_remainder_after_mid_reap_panic() {
    fn live(pid: u32) -> bool {
        std::path::Path::new(&format!("/proc/{pid}")).exists()
    }
    let pids = {
        let mut batch = ExitMappingChildrenGuard(
            (0..3)
                .map(|_| {
                    std::process::Command::new("sleep")
                        .arg("30")
                        .spawn()
                        .expect("spawn sleep")
                })
                .collect(),
        );
        let pids: Vec<u32> = batch.0.iter().map(|child| child.id()).collect();
        assert!(
            pids.iter().all(|pid| live(*pid)),
            "all batch children must be alive before the reap"
        );
        // Mirror the spawn window: each child is reaped, then a
        // mid-loop panic unwinds through the reap helper.
        let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            reap_owned_children(
                &mut batch,
                &["first", "second", "third"],
                |mut child, role| {
                    child.kill().expect("reap the reached child");
                    child.wait().expect("wait for the reached child");
                    if role == "second" {
                        panic!("simulated mid-reap panic");
                    }
                },
            );
        }));
        assert!(outcome.is_err(), "the simulated panic must unwind");
        drop(batch);
        pids
    };
    let leaked: Vec<u32> = pids.iter().copied().filter(|pid| live(*pid)).collect();
    assert!(
        leaked.is_empty(),
        "the guard must reap the unreaped remainder, still live: {leaked:?}"
    );
}

/// Parse this process's starting cgroup from `/proc/self/cgroup`
/// (cgroup v2 `0::/relative/path`) into the absolute cgroupfs
/// directory, so test guards move back to where the test started
/// instead of escaping to the root. Unparsable input falls back to
/// the root rather than refusing teardown.
fn self_origin_cgroup(cgroup_file: &str) -> std::path::PathBuf {
    const ROOT: &str = "/sys/fs/cgroup";
    let relative = cgroup_file
        .lines()
        .find_map(|line| line.strip_prefix("0::"))
        .map(|path| path.trim().trim_start_matches('/'))
        .unwrap_or("");
    if relative.is_empty() {
        std::path::PathBuf::from(ROOT)
    } else {
        std::path::PathBuf::from(ROOT).join(relative)
    }
}

/// True when `members` (a `cgroup.procs` listing) still contains
/// `pid`: the teardown kill-skip decision.
fn cgroup_still_holds(members: &str, pid: u32) -> bool {
    members
        .lines()
        .filter_map(|line| line.trim().parse::<u32>().ok())
        .any(|member| member == pid)
}

/// True when `cmdline` (a `/proc/cmdline` snapshot) carries a virtme
/// argument: virtme-ng boots every guest with `virtme_*`/`virtme.*`
/// parameters (`virtme_hostname=`, `virtme_console=`, ...), so any
/// such argument proves a virtme-ng guest.
fn cmdline_is_virtme_guest(cmdline: &str) -> bool {
    cmdline
        .split_whitespace()
        .any(|arg| arg.starts_with("virtme"))
}

/// Whether this test itself runs inside a virtme-ng guest (an
/// unreadable command line reads as host: fail onto the TMPDIR path).
fn running_in_virtme_guest() -> bool {
    std::fs::read_to_string("/proc/cmdline").is_ok_and(|cmdline| cmdline_is_virtme_guest(&cmdline))
}

/// The cgroup guards move the test back to the cgroup it started in
/// (parsed from `/proc/self/cgroup`), never to the root: a test
/// running under a CI or lane cgroup must not escape it for the rest
/// of the run.
#[test]
fn exit_mapping_cgroup_origin_restores_the_nested_starting_cgroup() {
    // Shaped like a real systemd user slice (cgroup v2): the origin
    // is nested, never the root.
    let nested = self_origin_cgroup("0::/user.slice/user-1000.slice/session-c2.scope\n");
    assert_eq!(
        nested,
        std::path::PathBuf::from("/sys/fs/cgroup/user.slice/user-1000.slice/session-c2.scope")
    );
    // Already at the root: the origin is the root.
    let root = self_origin_cgroup("0::/\n");
    assert_eq!(root, std::path::PathBuf::from("/sys/fs/cgroup"));
    // Unparsable input (v1 controller lines, garbage) falls back to
    // the root rather than refusing teardown.
    let v1_only = self_origin_cgroup("2:cpu,cpuacct:/foo\n");
    assert_eq!(v1_only, std::path::PathBuf::from("/sys/fs/cgroup"));
    let garbage = self_origin_cgroup("not a cgroup file\n");
    assert_eq!(garbage, std::path::PathBuf::from("/sys/fs/cgroup"));
}

/// Teardown never kills while this process is still inside the owned
/// cgroup: a failed move-out must not SIGKILL the test binary.
#[test]
fn exit_mapping_cgroup_kill_is_skipped_while_self_is_still_inside() {
    assert!(cgroup_still_holds("123\n456\n", 123));
    assert!(cgroup_still_holds("  456  \n123\n", 123));
    assert!(!cgroup_still_holds("456\n789\n", 123));
    assert!(!cgroup_still_holds("", 123));
    assert!(!cgroup_still_holds("garbage\n456\n", 123));
}

/// Whether `(uid, gid)` can search every ancestor directory of
/// `path` (itself included): the owner needs `u+x`, a group member
/// `g+x`, anyone else `o+x`. Mirrors the check the live exit-mapping
/// cell needs before invoking the discover helper, which drops to an
/// unprivileged identity before opening `--module`.
fn helper_can_traverse_as(path: &std::path::Path, uid: u32, gid: u32) -> bool {
    use std::os::unix::fs::MetadataExt as _;
    let mut current: Option<&std::path::Path> = Some(path);
    while let Some(dir) = current {
        let Ok(meta) = std::fs::symlink_metadata(dir) else {
            return false;
        };
        if !meta.is_dir() && dir != path {
            return false;
        }
        let mode = meta.mode();
        let searchable = if meta.uid() == uid {
            mode & 0o100 != 0
        } else if meta.gid() == gid {
            mode & 0o010 != 0
        } else {
            mode & 0o001 != 0
        };
        if !searchable {
            return false;
        }
        current = dir.parent();
    }
    true
}

/// The identity the discover helper runs provider code as: root drops
/// to `SUDO_UID`/`SUDO_GID` (nobody when unset), anyone else stays.
fn helper_drop_target() -> (u32, u32) {
    // SAFETY: geteuid/getegid only read this process's identities.
    let (euid, egid) = unsafe { (libc::geteuid(), libc::getegid()) };
    if euid != 0 {
        return (euid, egid);
    }
    let id = |name: &str| {
        std::env::var(name)
            .ok()
            .and_then(|text| text.parse().ok())
            .filter(|value| *value != 0 && *value != u32::MAX)
            .unwrap_or(65_534)
    };
    (id("SUDO_UID"), id("SUDO_GID"))
}

/// The traversal pin fires on a private chain: a 0700 ancestor owned
/// by someone else stops the dropped helper, like the campaign TMPDIR.
#[test]
fn exit_mapping_helper_traversal_rejects_private_ancestor() {
    let dir = tempfile::Builder::new()
        .prefix("exit-mapping-traverse-")
        .tempdir_in("/var/tmp")
        .expect("FHS /var/tmp must accept the probe dir");
    let inner = dir.path().join("inner");
    std::fs::create_dir(&inner).expect("inner");
    std::fs::set_permissions(
        dir.path(),
        std::os::unix::fs::PermissionsExt::from_mode(0o700),
    )
    .expect("private ancestor");
    std::fs::set_permissions(&inner, std::os::unix::fs::PermissionsExt::from_mode(0o777))
        .expect("open leaf");
    assert!(!helper_can_traverse_as(&inner, u32::MAX - 1, u32::MAX - 1));
    // The owner itself still traverses its own private chain.
    use std::os::unix::fs::MetadataExt as _;
    let meta = std::fs::metadata(dir.path()).expect("ancestor metadata");
    assert!(helper_can_traverse_as(&inner, meta.uid(), meta.gid()));
}

/// The traversal pin passes a world-searchable chain with an open
/// leaf, the shape the live cell builds its fixtures on.
#[test]
fn exit_mapping_helper_traversal_accepts_world_chain() {
    let dir = tempfile::Builder::new()
        .prefix("exit-mapping-traverse-")
        .tempdir_in("/var/tmp")
        .expect("FHS /var/tmp must accept the probe dir");
    std::fs::set_permissions(
        dir.path(),
        std::os::unix::fs::PermissionsExt::from_mode(0o755),
    )
    .expect("0755");
    let inner = dir.path().join("inner");
    std::fs::create_dir(&inner).expect("inner");
    std::fs::set_permissions(&inner, std::os::unix::fs::PermissionsExt::from_mode(0o1777))
        .expect("1777 leaf");
    assert!(helper_can_traverse_as(&inner, u32::MAX - 1, u32::MAX - 1));
}

/// W8B-66: the virtme-guest predicate fires on the parameters
/// virtme-ng unconditionally sets (`virtme_hostname=`,
/// `virtme_console=`, bare `virtme.*` flags), never on host command
/// lines or on a mere `virtme` mention inside an argument value.
#[test]
fn exit_mapping_virtme_guest_predicate_matches_only_virtme_args() {
    assert!(cmdline_is_virtme_guest(
        "virtme_hostname=virtme-ng TERM=xterm console=hvc0 virtme_console=hvc0 \
         virtme_user=root earlyprintk=serial nokaslr audit=off"
    ));
    assert!(cmdline_is_virtme_guest(
        "BOOT_IMAGE=/boot/vmlinuz root=/dev/vda1 ro virtme.sound"
    ));
    assert!(!cmdline_is_virtme_guest(
        "BOOT_IMAGE=/vmlinuz-6.12.0 root=/dev/sda3 ro quiet splash"
    ));
    assert!(!cmdline_is_virtme_guest(""));
    assert!(!cmdline_is_virtme_guest("init=/sbin/init foo=virtme"));
}

/// Privileged live cell (6.14 Option A): a real extensive capture
/// classifies three owned short-lived children, and the unarmed twin
/// records byte-identical kind 6.
///
/// Armed: the single-threaded mapper (dlopen cycles over the watched
/// fixture provider, then exit before any admission) reads `mapped`;
/// the plain child (exits without mapping) and the threaded mapper
/// (a live second thread spans its dlopen cycles, so every mapping
/// event globalizes) read `unknown`, never `mapped`. Twin: the same
/// three children under a default capture record kind-6 exits with
/// zeroed payload words and no split.
///
/// Cgroup-scoped by determinism, not by product need (the same call
/// the pressure cells make): under system scope ambient processes
/// share the 256 view slots, so the holder's admission — and with it
/// the fixture's watch — is host-churn luck. The owned cgroup holds
/// exactly this test's processes, so the end state (three gaps,
/// mapped 1, unknown 2) is forced on every host; the engine paths
/// are scope-independent. Per-child exit shapes are asserted exactly
/// from the drained records, which also prove kind 7 is never live
/// loss.
///
/// A holder loops dlopen/dlclose over the fixture after the session
/// starts: its EXEC lands in scope, so admission plans slots for it
/// and the session watches the file before the short-lived children
/// map it. The fixture builds its tables at run time, so a manifest
/// prepared by the discover helper (its own process, never this
/// observer) resolves them; without it the scan skips the provider
/// and no slot — hence no watch — ever exists. Children
/// spawn after the watch gate and die before the next tick, so they
/// are deterministically unmatched (never enumerated alive, never
/// admitted). No ticks run inside the spawn window, so the session's
/// own scans cannot inflate mm_users at map time; the mapper's five
/// dlopen/dlclose cycles (slots are sticky) retire the residual
/// transient-mmget flake. Runs as root with host BTF and gcc; registers
/// in `scripts/run-privileged-lib-tests.sh`.
#[ignore = "privileged: live BPF exit-mapping split over owned short-lived children; run as root with --ignored --test-threads=1 under the privileged lane"]
#[test]
fn exit_mappings_live_cgroup_split_and_default_twin() {
    use std::process::{Command, Stdio};

    const WHAT: &str = "exit-mappings-live";
    // SAFETY: geteuid only reads this process's effective user identity.
    assert_eq!(
        unsafe { libc::geteuid() },
        0,
        "{WHAT}: run as root under the privileged lane"
    );
    assert!(
        std::path::Path::new("/sys/kernel/btf/vmlinux").exists(),
        "{WHAT}: the live lane needs host vmlinux BTF"
    );
    assert!(
        Command::new("gcc")
            .arg("--version")
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status()
            .is_ok_and(|status| status.success()),
        "{WHAT}: gcc must be installed"
    );

    struct OwnedCgroup {
        path: std::path::PathBuf,
        origin: std::path::PathBuf,
    }

    impl OwnedCgroup {
        fn create(tag: &str, what: &str) -> Self {
            let path = std::path::PathBuf::from(format!(
                "/sys/fs/cgroup/p11scope-{tag}-{}",
                std::process::id()
            ));
            match std::fs::create_dir(&path) {
                Ok(()) => {}
                Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
                    std::fs::remove_dir(&path).unwrap_or_else(|error| {
                        panic!(
                            "{what}: stale cgroup {} is live, refusing: {error}",
                            path.display()
                        )
                    });
                    std::fs::create_dir(&path).unwrap_or_else(|error| {
                        panic!("{what}: creating cgroup {} failed: {error}", path.display())
                    });
                }
                Err(error) => panic!("{what}: creating cgroup {} failed: {error}", path.display()),
            }
            assert!(
                path.join("cgroup.procs").is_file(),
                "{what}: {} is not a live cgroup (no cgroup.procs)",
                path.display()
            );
            // Recorded before any move: the guards restore the test
            // to this cgroup, never to the root.
            let origin = std::fs::read_to_string("/proc/self/cgroup")
                .map(|text| self_origin_cgroup(&text))
                .unwrap_or_else(|error| {
                    panic!("{what}: reading /proc/self/cgroup failed: {error}")
                });
            Self { path, origin }
        }

        fn move_in(&self, pid: u32, what: &str) {
            std::fs::write(self.path.join("cgroup.procs"), pid.to_string()).unwrap_or_else(
                |error| {
                    panic!(
                        "{what}: moving {pid} into {} failed: {error}",
                        self.path.display()
                    )
                },
            );
        }

        fn members(&self, what: &str) -> std::collections::BTreeSet<u32> {
            let text =
                std::fs::read_to_string(self.path.join("cgroup.procs")).unwrap_or_else(|error| {
                    panic!("{what}: reading {} failed: {error}", self.path.display())
                });
            text.lines()
                .filter_map(|line| line.trim().parse::<u32>().ok())
                .collect()
        }

        fn remove(&self, what: &str) {
            std::fs::remove_dir(&self.path).unwrap_or_else(|error| {
                panic!(
                    "{what}: removing cgroup {} failed: {error}",
                    self.path.display()
                )
            });
        }
    }

    impl Drop for OwnedCgroup {
        fn drop(&mut self) {
            // Failure paths converge with the success path (`remove`
            // after every owned process is reaped): a panic between
            // spawn and reap must not leak the cgroup. The child
            // guards drop first and already killed and reaped owned
            // fixtures; move the test itself back to the cgroup it
            // started in (never the root, which would escape a CI or
            // lane cgroup for the rest of the run) so the kill below
            // can never SIGKILL this binary mid-unwind, then kill
            // strays and retry removal while members drain. The kill
            // is skipped while this process is still inside: a failed
            // move-out must not kill the test itself.
            if !self.path.exists() {
                return;
            }
            let this = std::process::id();
            let _ = std::fs::write(self.origin.join("cgroup.procs"), this.to_string());
            let inside = std::fs::read_to_string(self.path.join("cgroup.procs"))
                .is_ok_and(|members| cgroup_still_holds(&members, this));
            if !inside {
                let _ = std::fs::write(self.path.join("cgroup.kill"), "1");
            }
            for _ in 0..20 {
                if std::fs::remove_dir(&self.path).is_ok() {
                    return;
                }
                std::thread::sleep(std::time::Duration::from_millis(50));
            }
            let _ = std::fs::remove_dir(&self.path);
        }
    }

    struct MoveOutGuard {
        pid: u32,
        origin: std::path::PathBuf,
        armed: bool,
    }

    impl MoveOutGuard {
        fn arm(pid: u32, origin: std::path::PathBuf) -> Self {
            Self {
                pid,
                origin,
                armed: true,
            }
        }

        fn disarm(&mut self) {
            self.armed = false;
        }

        fn move_out(&mut self, what: &str) {
            std::fs::write(self.origin.join("cgroup.procs"), self.pid.to_string())
                .unwrap_or_else(|error| panic!("{what}: moving {} out failed: {error}", self.pid));
            self.disarm();
        }
    }

    impl Drop for MoveOutGuard {
        fn drop(&mut self) {
            if self.armed {
                let _ = std::fs::write(self.origin.join("cgroup.procs"), self.pid.to_string());
            }
        }
    }

    fn gcc_fixture(output: &std::path::Path, extra: &[&str], source: &std::path::Path, what: &str) {
        let status = std::process::Command::new("gcc")
            .args(["-std=c11", "-O2", "-Wall", "-Wextra", "-Werror"])
            .args(extra)
            .arg("-o")
            .arg(output)
            .arg(source)
            .status()
            .unwrap_or_else(|error| {
                panic!("{what}: gcc {} failed to spawn: {error}", output.display())
            });
        assert!(
            status.success(),
            "{what}: gcc {} exited {status}",
            output.display()
        );
    }

    // Fixtures compile before capture: no forks inside the window.
    // W8B-66: inside a virtme-ng guest the fixtures live on guest
    // tmpfs (/tmp is guest-local there), never under a host TMPDIR
    // naming the shared 9p tree, whose remapped ownership and device
    // identity the observer's checks rightly refuse.
    //
    // The discover helper drops to an unprivileged identity before
    // opening --module, so the fixture dir must sit under a
    // world-searchable base: the campaign TMPDIR is 0700 root, which
    // the dropped helper cannot traverse. /var/tmp is FHS disk-backed
    // 1777 on every campaign host.
    let dir = if running_in_virtme_guest() {
        tempfile::Builder::new()
            .prefix("exit-mappings-live-")
            .tempdir_in("/tmp")
            .expect("guest tmpfs must accept the fixture dir")
    } else {
        tempfile::Builder::new()
            .prefix("exit-mappings-live-")
            .tempdir_in("/var/tmp")
            .expect("FHS /var/tmp must accept the fixture dir")
    };
    // The discover helper drops privileges before executing provider
    // code and writing -o, so its output dir must stay writable to
    // the dropped user; the sticky bit keeps the helper's own
    // safe-output check green. Test-local only; removed with the dir.
    std::fs::set_permissions(
        dir.path(),
        std::os::unix::fs::PermissionsExt::from_mode(0o1777),
    )
    .expect("fixture dir must accept the helper output");
    let (drop_uid, drop_gid) = helper_drop_target();
    assert!(
        helper_can_traverse_as(dir.path(), drop_uid, drop_gid),
        "{WHAT}: fixture dir {} is not traversable by the discover helper identity {drop_uid}:{drop_gid}",
        dir.path().display()
    );
    let manifest = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let provider = dir.path().join("provider.so");
    gcc_fixture(
        &provider,
        &["-shared", "-fPIC", "-DMATRIX_INTERFACES=1"],
        &manifest.join("crates/discover/tests/fixture/version_matrix.c"),
        WHAT,
    );
    let live = manifest.join("tests/fixtures/exit-mapping");
    let mapper = dir.path().join("mapper");
    gcc_fixture(&mapper, &["-ldl"], &live.join("mapper.c"), WHAT);
    let plain = dir.path().join("plain");
    gcc_fixture(&plain, &[], &live.join("plain.c"), WHAT);
    let threaded = dir.path().join("threaded");
    gcc_fixture(
        &threaded,
        &["-ldl", "-pthread"],
        &live.join("threaded.c"),
        WHAT,
    );
    let holder = dir.path().join("holder");
    gcc_fixture(&holder, &["-ldl"], &live.join("holder.c"), WHAT);
    // The fixture builds its function tables at run time, outside the
    // memory scan's reach, so the designed manifest flow prepares
    // them: the helper executes provider code in its own process
    // (never in this observer). `P11SCOPE_DISCOVER_BIN` names it
    // explicitly (the privileged-inputs layout stages it under bin/,
    // not beside lib-tests); otherwise the lane builds the helper
    // beside this test binary.
    let discover = {
        if let Ok(path) = std::env::var("P11SCOPE_DISCOVER_BIN") {
            let explicit = std::path::PathBuf::from(&path);
            assert!(
                explicit.is_file(),
                "{WHAT}: P11SCOPE_DISCOVER_BIN={path} is missing"
            );
            explicit
        } else {
            let deps = std::env::current_exe().expect("test binary path");
            let sibling = deps.parent().expect("deps dir").join("p11scope-discover");
            let cargo = deps
                .parent()
                .expect("deps dir")
                .parent()
                .expect("profile dir")
                .join("p11scope-discover");
            [sibling, cargo]
                .into_iter()
                .find(|candidate| candidate.is_file())
                .unwrap_or_else(|| {
                    panic!(
                        "{WHAT}: no discover helper: set P11SCOPE_DISCOVER_BIN or build it beside this test binary (`cargo build -p p11scope-discover`)"
                    )
                })
        }
    };
    let manifest_path = dir.path().join("manifest.json");
    let status = Command::new(&discover)
        .arg("--module")
        .arg(&provider)
        .arg("-o")
        .arg(&manifest_path)
        .status()
        .unwrap_or_else(|error| panic!("{WHAT}: discover helper failed to spawn: {error}"));
    assert!(
        status.success() && manifest_path.is_file(),
        "{WHAT}: discover helper exited {status}"
    );
    let fixtures = LiveFixtures {
        provider,
        manifest: manifest_path,
        mapper,
        plain,
        threaded,
        holder,
    };

    struct LiveExits {
        gaps: u64,
        split: Option<(u64, u64)>,
        records: Vec<DiscoveryRecord>,
        pids: [u32; 3],
    }

    struct LiveFixtures {
        provider: std::path::PathBuf,
        manifest: std::path::PathBuf,
        mapper: std::path::PathBuf,
        plain: std::path::PathBuf,
        threaded: std::path::PathBuf,
        holder: std::path::PathBuf,
    }

    fn spawn_holder(
        what: &str,
        holder: &std::path::Path,
        provider: &std::path::Path,
    ) -> std::process::Child {
        let mut child = std::process::Command::new(holder)
            .arg(provider)
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .expect("spawn holder");
        {
            use std::io::BufRead as _;
            let mut ready = String::new();
            std::io::BufReader::new(child.stdout.take().expect("holder stdout"))
                .read_line(&mut ready)
                .expect("holder readiness");
            assert!(
                ready.starts_with("READY pid="),
                "{what}: holder must map first"
            );
        }
        child
    }

    fn run_capture(
        what: &str,
        tag: &str,
        fixtures: &LiveFixtures,
        armed: bool,
    ) -> (LiveExits, Vec<crate::discovery::scan::Skipped>) {
        let cgroup = OwnedCgroup::create(tag, what);
        let args = crate::cli::CaptureArgs {
            track_short_lived: armed,
            verbose: false,
            quiet: false,
            kind: crate::cli::Kind::Profile,
            modules: vec![fixtures.provider.clone()],
            exclude_modules: vec![],
            manifests: vec![fixtures.manifest.clone()],
            prearm_modules: vec![],
            forwarding_modules: Vec::new(),
            hooks: crate::discovery::hooks::HookRegistry::builtin(),
            scope: crate::cli::ScopeArg::Cgroup(cgroup.path.clone()),
            metrics: false,
            counter_mode: None,
            select_endpoint: None,
            duration: None,
            out: None,
            max_events: None,
            max_scan_pids: None,
            ring_bytes: None,
            drain_interval: None,
            unsafe_requested: false,
            allow_confined_uretprobe: false,
            attach_backend: crate::attach::BackendSelection::default(),
        };
        let scope = crate::scope::capture_cgroup(&cgroup.path)
            .unwrap_or_else(|error| panic!("{what}: cgroup scope failed: {error:#}"));
        let mut engine = Engine::discover(&args, &scope, None).expect("live discovery");
        if armed {
            engine.arm_extensive(true, CapturePolicy::Allowlisted, None);
        }
        let mut session = engine
            .start_session(
                crate::attach::CapturePolicy::Allowlisted,
                None,
                crate::attach::BackendSelection::default(),
            )
            .unwrap_or_else(|error| panic!("{what}: start_session failed: {error:#}"));
        if armed {
            assert!(
                session.instance_tracking().refused().is_none(),
                "{what}: the armed cell needs live instance hooks: {:?}",
                session.instance_tracking().refused()
            );
        }
        // Born inside the scope: the test moves itself in, spawns the
        // holder there, then moves itself back out. No tick runs
        // until the settle loop, so enumeration never observes the
        // test itself.
        let this = std::process::id();
        let assert_moved_out = |cgroup: &OwnedCgroup, this: u32, what: &str| {
            assert!(
                !cgroup.members(what).contains(&this),
                "{what}: the test must move back out of the owned cgroup"
            );
            let origin_members = std::fs::read_to_string(cgroup.origin.join("cgroup.procs"))
                .unwrap_or_else(|error| {
                    panic!("{what}: reading the origin cgroup failed: {error}")
                });
            assert!(
                cgroup_still_holds(&origin_members, this),
                "{what}: the test must move back to its origin cgroup {}",
                cgroup.origin.display()
            );
        };
        cgroup.move_in(this, what);
        let mut move_out = MoveOutGuard::arm(this, cgroup.origin.clone());
        assert!(
            cgroup.members(what).contains(&this),
            "{what}: the test must spawn from inside the cgroup"
        );
        let mut holder_child =
            ExitMappingChildGuard(spawn_holder(what, &fixtures.holder, &fixtures.provider));
        move_out.move_out(what);
        assert_moved_out(&cgroup, this, what);
        // Settle: tick the production cadence until a slot carries
        // a watch for exactly the fixture file. Only then can a
        // short-lived mapping name a slot.
        use std::os::unix::fs::MetadataExt as _;
        let fixture_meta = std::fs::metadata(&fixtures.provider).expect("stat fixture");
        let settle_deadline = std::time::Instant::now() + std::time::Duration::from_secs(120);
        loop {
            engine
                .drain_discovery_shallow(&mut session, false)
                .unwrap_or_else(|error| panic!("{what}: settle drain failed: {error:#}"));
            engine
                .service_backlog_quantum(&mut session)
                .unwrap_or_else(|error| panic!("{what}: settle service failed: {error:#}"));
            let watched = engine.plan.slots.iter().any(|slot| {
                session
                    .instance_tracking()
                    .watched(slot.object)
                    .is_some_and(|watched| {
                        watched.identity.dev == fixture_meta.dev()
                            && watched.identity.ino == fixture_meta.ino()
                    })
            });
            if watched {
                break;
            }
            assert!(
                std::time::Instant::now() < settle_deadline,
                "{what}: fixture unwatched after 120s: views={} slots={} members={:?}",
                engine.views.len(),
                engine.plan.slots.len(),
                cgroup.members(what)
            );
            std::thread::sleep(std::time::Duration::from_millis(100));
        }
        // The window: born in scope, reaped before the next tick, so
        // all three stay deterministically unmatched.
        cgroup.move_in(this, what);
        let mut move_out = MoveOutGuard::arm(this, cgroup.origin.clone());
        let mapper_child = std::process::Command::new(&fixtures.mapper)
            .arg(&fixtures.provider)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .expect("spawn mapper");
        let mapper_pid = mapper_child.id();
        let plain_child = std::process::Command::new(&fixtures.plain)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .expect("spawn plain child");
        let plain_pid = plain_child.id();
        let threaded_child = std::process::Command::new(&fixtures.threaded)
            .arg(&fixtures.provider)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .expect("spawn threaded mapper");
        let threaded_pid = threaded_child.id();
        // Guarded: each child leaves the guard only when its own
        // reap starts, so a panic mid-reap still kills and reaps
        // whatever the loop below has not consumed yet.
        let mut owned_children =
            ExitMappingChildrenGuard(vec![mapper_child, plain_child, threaded_child]);
        reap_owned_children(
            &mut owned_children,
            &["mapper", "plain", "threaded"],
            |child, role| {
                let output = child.wait_with_output().expect("reap owned child");
                assert!(
                    output.status.success(),
                    "{what}: owned {role} child exited {}: {}",
                    output.status,
                    String::from_utf8_lossy(&output.stderr)
                );
            },
        );
        move_out.move_out(what);
        assert_moved_out(&cgroup, this, what);
        let owned = [mapper_pid, plain_pid, threaded_pid];
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(90);
        let mut exits = Vec::new();
        loop {
            let (records, malformed, _empty) = engine
                .collect_frame_discovery(&mut session)
                .unwrap_or_else(|error| panic!("{what}: drain failed: {error:#}"));
            for record in &records {
                if matches!(
                    record.kind,
                    DISCOVERY_KIND_LEADER_EXIT | DISCOVERY_KIND_LEADER_EXIT_MAPPINGS
                ) && owned.contains(&((record.pid_tgid >> 32) as u32))
                {
                    exits.push(*record);
                }
            }
            engine
                .with_live_frame(|live| {
                    live.apply_discovery_batch(&mut session, records, malformed)
                })
                .unwrap_or_else(|error| panic!("{what}: apply failed: {error:#}"));
            let settled = owned.iter().all(|pid| {
                engine
                    .unmatched_leader_exit_events
                    .iter()
                    .any(|(exit_pid, _)| exit_pid == pid)
            });
            if settled {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "{what}: owned exits unsettled after 90s: ledger has {:?}",
                engine.unmatched_leader_exit_events
            );
            std::thread::sleep(std::time::Duration::from_millis(50));
        }
        // The window is closed: reap the holder before reading the
        // outcome (its exit is never drained, so it cannot move the
        // counts either way), then remove the cgroup.
        holder_child.0.kill().expect("reap holder");
        holder_child.0.wait().expect("wait holder");
        let skips = engine.counters.object_skips.clone();
        let outcome = (
            LiveExits {
                gaps: engine.pid_descendant_gaps(),
                split: engine
                    .gap_exit_mappings()
                    .map(|split| (split.mapped, split.unknown)),
                records: exits,
                pids: owned,
            },
            skips,
        );
        cgroup.remove(what);
        outcome
    }

    let slots = p11scope_ebpf_common::instance::RECORD_SLOTS;
    let exit_for = |run: &LiveExits, pid: u32| {
        run.records
            .iter()
            .find(|record| (record.pid_tgid >> 32) as u32 == pid)
            .copied()
            .unwrap_or_else(|| panic!("{WHAT}: no exit record for owned pid {pid}"))
    };

    let (armed_run, armed_skips) = run_capture(WHAT, "exitmap-armed", &fixtures, true);
    let mapper_exit = exit_for(&armed_run, armed_run.pids[0]);
    assert_eq!(
        mapper_exit.kind, DISCOVERY_KIND_LEADER_EXIT_MAPPINGS,
        "{WHAT}: the mapper exit must be kind 7"
    );
    assert!(
        mapper_exit.pointers[..slots].iter().any(|cell| *cell != 0),
        "{WHAT}: the mapper must name a watched slot"
    );
    assert_eq!(
        mapper_exit.status_flags, 0,
        "{WHAT}: the mapper summary carries no refusal"
    );
    for (pid, role) in [
        (armed_run.pids[1], "plain"),
        (armed_run.pids[2], "threaded"),
    ] {
        let exit = exit_for(&armed_run, pid);
        assert_eq!(
            exit.kind, DISCOVERY_KIND_LEADER_EXIT_MAPPINGS,
            "{WHAT}: the {role} exit must be kind 7"
        );
        assert!(
            exit.pointers[..slots].iter().all(|cell| *cell == 0),
            "{WHAT}: the {role} exit must name no slot"
        );
    }
    // Four gaps, exactly: the holder's admission plus the three
    // owned exits (admissions carry no split entry).
    assert_eq!(
        armed_run.gaps, 4,
        "{WHAT}: gaps must be the holder admission plus the three owned exits"
    );
    assert_eq!(
        armed_run.split,
        Some((1, 2)),
        "{WHAT}: the armed split must read mapped 1, unknown 2"
    );
    assert!(
        armed_skips
            .iter()
            .all(|skip| !skip.reason.contains("unknown discovery kind")),
        "{WHAT}: kind 7 must never be live loss: {armed_skips:?}"
    );

    let (twin_run, _) = run_capture(WHAT, "exitmap-twin", &fixtures, false);
    for pid in twin_run.pids {
        let exit = exit_for(&twin_run, pid);
        assert_eq!(
            exit.kind, DISCOVERY_KIND_LEADER_EXIT,
            "{WHAT}: the default twin must record kind 6"
        );
        assert_eq!(
            exit.status_flags, 0,
            "{WHAT}: default kind 6 carries no status"
        );
        assert_eq!(exit.case_id, 0, "{WHAT}: default kind 6 carries no case");
        assert_eq!(
            exit.binding_id, 0,
            "{WHAT}: default kind 6 carries no binding"
        );
        assert_eq!(
            exit.announced_count, 0,
            "{WHAT}: default kind 6 announces nothing"
        );
        assert_eq!(
            exit.send_signal_rc, 0,
            "{WHAT}: default kind 6 carries no signal result"
        );
        assert!(
            exit.pointers.iter().all(|cell| *cell == 0),
            "{WHAT}: default kind 6 carries a zeroed payload"
        );
    }
    assert_eq!(
        twin_run.gaps, 4,
        "{WHAT}: twin gaps must be the holder admission plus the three owned exits"
    );
    assert_eq!(twin_run.split, None, "{WHAT}: the twin publishes no split");
}

/// The exec-timing table is bounded: past the stash bound the
/// smallest PID evicts first, deterministically.
#[test]
fn exit_mappings_exec_table_evicts_smallest_pid_when_full() {
    use crate::discovery::elf_needed::HINT_MAX_EXE_STASH_ENTRIES;
    let mut state = ExitMappingState::default();
    state.set_enabled(true);
    for pid in 0..=HINT_MAX_EXE_STASH_ENTRIES as u32 {
        state.note_exec(pid, u64::from(pid));
    }
    assert_eq!(state.execs.len(), HINT_MAX_EXE_STASH_ENTRIES);
    assert!(!state.execs.contains_key(&0));
    assert!(
        state
            .execs
            .contains_key(&(HINT_MAX_EXE_STASH_ENTRIES as u32))
    );
}

#[test]
fn system_scope_admits_new_generations_and_counts_unmatched_exits() {
    let first = ProcessView::open(ProcessViewId(41), std::process::id()).unwrap();
    let pid = first.pid();
    let admitted = first.admitted_ns();
    let mut engine = Engine::empty();
    engine.scope = Scope::System;
    engine.views.push(first);
    engine.seed_initial_cgroup_views();
    assert_eq!(engine.pid_descendant_gaps(), 0);

    // A newly admitted generation counts exactly once, as in cgroup scope.
    let second = ProcessView::open(ProcessViewId(42), pid).unwrap();
    engine.views.push(second);
    engine.record_cgroup_view_admissions([ProcessViewId(42)]);
    assert_eq!(engine.pid_descendant_gaps(), 1);

    // An exit that matches no admitted generation counts once however often
    // it is replayed; admission needs no cgroup check in system scope.
    let mut short_lived: DiscoveryRecord = unsafe { std::mem::zeroed() };
    short_lived.kind = DISCOVERY_KIND_LEADER_EXIT;
    short_lived.pid_tgid = u64::from(pid.saturating_add(1)) << 32;
    short_lived.hook_ts_ns = admitted;
    let mut pending = PendingViewRetirements::new();
    engine.dispatch_lifecycle_record(&mut ScriptedSession::default(), &short_lived, &mut pending);
    engine.dispatch_lifecycle_record(&mut ScriptedSession::default(), &short_lived, &mut pending);
    assert_eq!(engine.pid_descendant_gaps(), 2);
}

#[test]
fn system_scope_ledger_overflow_latches_partial_with_system_subject() {
    let mut engine = Engine::empty();
    engine.scope = Scope::System;
    let mut pending = PendingViewRetirements::new();
    for index in 0..=MAX_SCAN_PIDS {
        let mut exit: DiscoveryRecord = unsafe { std::mem::zeroed() };
        exit.kind = DISCOVERY_KIND_LEADER_EXIT;
        exit.pid_tgid = (index as u64 + 1) << 32;
        exit.hook_ts_ns = index as u64 + 1;
        engine.dispatch_lifecycle_record(&mut ScriptedSession::default(), &exit, &mut pending);
    }
    let after_overflow = engine.pid_descendant_gaps();
    let mut further: DiscoveryRecord = unsafe { std::mem::zeroed() };
    further.kind = DISCOVERY_KIND_LEADER_EXIT;
    further.pid_tgid = (MAX_SCAN_PIDS as u64 + 2) << 32;
    further.hook_ts_ns = MAX_SCAN_PIDS as u64 + 2;
    engine.dispatch_lifecycle_record(&mut ScriptedSession::default(), &further, &mut pending);
    assert_eq!(after_overflow, MAX_SCAN_PIDS as u64 + 1);
    assert_eq!(engine.pid_descendant_gaps(), after_overflow);
    assert!(engine.cgroup_ingress_overflow);
    assert_eq!(
        engine
            .counters
            .object_skips
            .iter()
            .filter(|skip| skip.subject == "system ingress tracking")
            .count(),
        1
    );
}

#[test]
fn leader_exit_loss_closes_only_the_owned_selection_view() {
    let view = ProcessView::open(ProcessViewId(25), std::process::id()).unwrap();
    let mut engine = Engine::empty();
    engine.views.push(view);
    let generation = NonZeroU64::new(1).unwrap();
    engine.selection_bindings.insert(
        1,
        SelectionBindingFact {
            id: 1,
            context: LoaderContextId::from_case_id(1),
            view: ProcessViewId(25),
            object: PinnedObjectId(1),
            file_offset: 0,
            hook_id: 0,
            abi: HookAbi::Interface,
            attached: true,
            retired: false,
            provider: plan::ModuleId(0),
            observed: false,
            coverage: SelectionCoverageState::OwnedOpen(generation),
        },
    );
    engine.pending_leader_exit_views.insert(ProcessViewId(25));
    engine.request_refresh(std::process::id(), None);
    let mut pending_views = PendingViewRetirements::new();
    let mut additions_allowed = true;
    let mut closure = PauseClosure::new(true);
    let assessments = engine.pending_leader_exit_views.clone();
    engine.settle_leader_exit_assessments(
        &assessments,
        &mut pending_views,
        &mut additions_allowed,
        &mut closure,
    );
    assert_eq!(engine.task_uprobe_link_losses, 1);
    assert!(!additions_allowed);
    assert!(!closure.required_complete());
    assert!(
        pending_views.is_empty(),
        "link loss does not retire the live view"
    );
    assert!(
        engine
            .views
            .iter()
            .any(|candidate| candidate.id() == ProcessViewId(25)),
        "the live ProcessView remains available for later whole-group exit evidence"
    );
    assert_eq!(
        engine.selection_bindings[&1].coverage,
        SelectionCoverageState::OwnedClosed(generation)
    );
    assert!(
        !engine.refresh_requested.contains_key(&std::process::id()),
        "link loss does not re-arm the same live view"
    );
}

#[test]
fn leader_exit_batch_n_queues_and_batch_n_plus_1_settles() {
    let view = ProcessView::open(ProcessViewId(27), std::process::id()).unwrap();
    let mut record: DiscoveryRecord = unsafe { std::mem::zeroed() };
    record.kind = DISCOVERY_KIND_LEADER_EXIT;
    record.pid_tgid = u64::from(view.pid()) << 32;
    record.hook_ts_ns = view.admitted_ns();
    let mut engine = Engine::empty();
    engine.views.push(view);
    let mut session = ScriptedSession::default();

    let first = apply_ordinary_batch(&mut engine, &mut session, vec![record]).unwrap();
    assert!(first.required_complete, "batch N has no settled loss yet");
    assert_eq!(engine.task_uprobe_link_losses, 0);
    assert!(
        engine
            .pending_leader_exit_views
            .contains(&ProcessViewId(27))
    );

    let second = apply_ordinary_batch(&mut engine, &mut session, Vec::new()).unwrap();
    assert!(
        !second.required_complete,
        "batch N+1 publishes the link loss"
    );
    assert_eq!(engine.task_uprobe_link_losses, 1);
    assert!(engine.pending_leader_exit_views.is_empty());
    assert!(
        engine
            .views
            .iter()
            .any(|candidate| candidate.id() == ProcessViewId(27))
    );
}

/// HI-1: a refresh set naming a view retired after the set was built
/// (stale loader context) skips that view and discloses PARTIAL
/// instead of panicking the whole capture.
#[test]
fn inventory_scan_skips_views_retired_before_their_refresh() {
    let view = ProcessView::open(ProcessViewId(0), std::process::id()).unwrap();
    let mut engine = lifecycle_discovered(vec![view]);
    let views = BTreeSet::from([ProcessViewId(0), ProcessViewId(7)]);
    let mut tick_now = crate::attach::monotonic_ns;
    let (scans, _, _, skipped) = engine.scan_inventory_views(&views, "test refresh", &mut tick_now);
    let scanned: Vec<u32> = scans.iter().map(|(view, _, _)| view.0).collect();
    assert!(
        scanned.iter().all(|id| *id == 0),
        "only the retained view is scanned: {scanned:?}"
    );
    assert!(
        skipped
            .iter()
            .any(|skip| skip.reason.contains("no longer retained")),
        "the retired view is a disclosed skip: {skipped:?}"
    );
    assert!(
        engine.counters.object_skips.iter().any(|skip| {
            skip.subject.contains("process view 7") && skip.reason.contains("no longer retained")
        }),
        "the retired view forces PARTIAL: {:?}",
        engine.counters.object_skips
    );
}

#[test]
fn mixed_refresh_batch_does_not_settle_new_leader_until_next_outer_batch() {
    let view = ProcessView::open(ProcessViewId(30), std::process::id()).unwrap();
    let mut leader: DiscoveryRecord = unsafe { std::mem::zeroed() };
    leader.kind = DISCOVERY_KIND_LEADER_EXIT;
    leader.pid_tgid = u64::from(view.pid()) << 32;
    leader.hook_ts_ns = view.admitted_ns();
    let mut exec = leader;
    exec.kind = DISCOVERY_KIND_EXEC;
    let mut engine = Engine::empty();
    engine.views.push(view);
    let mut session = ScriptedSession::default();

    apply_ordinary_batch(&mut engine, &mut session, vec![leader, exec])
        .expect("mixed refresh batch remains processable");
    assert_eq!(engine.task_uprobe_link_losses, 0);
    assert!(
        engine
            .pending_leader_exit_views
            .contains(&ProcessViewId(30))
    );

    apply_ordinary_batch(&mut engine, &mut session, Vec::new())
        .expect("the next outer batch settles the retained assessment");
    assert_eq!(engine.task_uprobe_link_losses, 1);
    assert!(engine.pending_leader_exit_views.is_empty());
}

