#[test]
fn retirement_cause_merge_never_downgrades_real_loss() {
    assert_eq!(
        RetirementCause::ExecRefresh.merge(RetirementCause::ExpectedRemoval),
        RetirementCause::ExpectedRemoval
    );
    assert_eq!(
        RetirementCause::ExpectedRemoval.merge(RetirementCause::GenerationLost),
        RetirementCause::GenerationLost
    );
    assert_eq!(
        RetirementCause::GenerationLost.merge(RetirementCause::ExecRefresh),
        RetirementCause::GenerationLost
    );
}

#[test]
fn batch_exit_dominates_exec_before_dead_pin_promotion() {
    let record = |kind, pid, hook_ts_ns| {
        let mut record: DiscoveryRecord = unsafe { std::mem::zeroed() };
        record.kind = kind;
        record.pid_tgid = u64::from(pid) << 32;
        record.hook_ts_ns = hook_ts_ns;
        record
    };
    let mut child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let view = ProcessView::open(ProcessViewId(18), child.id()).unwrap();
    let hook_ts_ns = view.admitted_ns();
    let mut engine = Engine::empty();
    engine.views.push(view);
    child.kill().unwrap();
    child.wait().unwrap();
    let mut pending = PendingViewRetirements::new();

    for record in [
        record(DISCOVERY_KIND_EXEC, child.id(), hook_ts_ns),
        record(DISCOVERY_KIND_LEADER_EXIT, child.id(), hook_ts_ns),
    ] {
        engine.dispatch_lifecycle_record(&mut ScriptedSession::default(), &record, &mut pending);
    }
    engine.promote_stale_execs(&mut pending);

    assert_eq!(
        pending.get(&ProcessViewId(18)),
        Some(&RetirementCause::ExpectedRemoval)
    );
    assert!(!engine.refresh_requested.contains_key(&child.id()));
    assert!(
        engine
            .counters
            .object_skips
            .iter()
            .all(|skip| skip.subject != "live discovery generation")
    );

    // An exec with no exit *record* still gets its matching exit from the
    // stronger authority: the retained original pin. Task 9.2 defect B —
    // the exit record is still in the ring while the pidfd is already
    // readable, and calling that proven exit a lost generation failed
    // `p11scope run` on every short-lived child.
    let mut child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let view = ProcessView::open(ProcessViewId(19), child.id()).unwrap();
    let exec = record(DISCOVERY_KIND_EXEC, child.id(), view.admitted_ns());
    let mut engine = Engine::empty();
    engine.views.push(view);
    child.kill().unwrap();
    child.wait().unwrap();
    let mut pending = PendingViewRetirements::new();
    engine.dispatch_lifecycle_record(&mut ScriptedSession::default(), &exec, &mut pending);
    engine.promote_stale_execs(&mut pending);
    assert_eq!(
        pending.get(&ProcessViewId(19)),
        Some(&RetirementCause::ExpectedRemoval),
        "a pin that proves the original exited names the leader-exit transition"
    );
    assert!(
        engine
            .counters
            .object_skips
            .iter()
            .all(|skip| skip.subject != "live discovery generation"),
        "a proven exit is not a loss"
    );

    // E17 midfinal correction: a stale report for a generation that is
    // still running is declined — the pin re-reads Current, so there is no
    // positive evidence of change to record as loss. The deferral is marked
    // and the next pass re-checks.
    let mut child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let view = ProcessView::open(ProcessViewId(20), child.id()).unwrap();
    let mut engine = Engine::empty();
    engine.views.push(view);
    let mut pending = PendingViewRetirements::new();
    engine.queue_stale_views(&[ProcessViewId(20)].into_iter().collect(), &mut pending);
    child.kill().unwrap();
    child.wait().unwrap();
    assert!(
        pending.is_empty(),
        "a contradicted report queues nothing: {pending:?}"
    );
    assert!(
        engine
            .counters
            .object_skips
            .iter()
            .any(|skip| skip.subject == "live discovery generation"
                && skip.reason.contains("contradicted or unprovable")),
        "the deferral is marked PARTIAL: {:?}",
        engine.counters.object_skips
    );
}

/// Task 9.2 defect B, through the real batch route. A named target that
/// exits while live discovery is working on it is an expected removal —
/// the retained pin proves it — and the capture ends the ordinary way.
/// Only the `LEADER_EXIT` record used to say so, and it is still in the
/// ring when the pidfd is already readable, so `p11scope run` on a
/// short-lived child failed with a false `the named process generation
/// changed during live discovery` and discarded the whole capture.
#[test]
fn a_named_target_that_provably_exited_ends_the_capture_rather_than_failing_it() {
    let mut record: DiscoveryRecord = unsafe { std::mem::zeroed() };
    let mut child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let view = ProcessView::open(ProcessViewId(0), child.id()).unwrap();
    record.kind = DISCOVERY_KIND_EXEC;
    record.pid_tgid = u64::from(child.id()) << 32;
    record.hook_ts_ns = view.admitted_ns();
    let mut engine = Engine::empty();
    engine.scope = Scope::Pid(child.id());
    engine.views.push(view);
    child.kill().unwrap();
    child.wait().unwrap();

    let mut session = ScriptedSession::default();
    apply_ordinary_batch(&mut engine, &mut session, vec![record])
        .expect("a named target's provable exit is not a live-discovery failure");

    assert!(
        engine.expected_target_exit(),
        "the capture ends the ordinary way: {:?}",
        engine.counters.object_skips
    );
    assert!(engine.views.is_empty());
    assert!(
        engine
            .counters
            .object_skips
            .iter()
            .all(|skip| skip.subject != "live discovery generation"),
        "a proven exit is not a lost generation: {:?}",
        engine.counters.object_skips
    );
}

/// run-short: the quiesce batch after a short-lived `run` child exits.
/// The named target's expected removal settled (exit proven, arm set)
/// while its attached loader context was still draining, so the latch
/// has not run. The empty view set is the expected end, not a vanished
/// generation: the batch succeeds, and the latch completes once the
/// loader context drains.
#[test]
fn armed_expected_exit_without_views_is_not_a_lost_generation() {
    let (mut engine, context) = Engine::retiring_loader_context(std::process::id());
    let view = ProcessViewId(0);
    // Settle the ExpectedRemoval the way process_discovery_records does:
    // the view is gone and its intent consumed, the arm records the
    // proven exit — but the loader ids are still draining.
    engine.views.clear();
    engine.release_view_id(view);
    engine.retirement_intents.clear();
    engine.scan_inputs.remove(&view);
    engine.expected_target_exit_pending = Some(view);
    assert!(!engine.expected_target_exit());
    assert!(
        !engine.loader_registry.ids_for_view(view).is_empty(),
        "the latch must still be blocked for this repro"
    );
    let mut session = ScriptedSession::default();
    engine
        .apply_quiesced_discovery(&mut session, Vec::new(), 0)
        .expect("a settled named exit is the expected end, not a lost generation");
    assert!(
        !engine.expected_target_exit(),
        "the latch still waits on the loader ids"
    );
    engine
        .loader_registry
        .tombstone(context)
        .expect("tombstoning the drained loader context");
    engine
        .loader_registry
        .remove(context)
        .expect("draining the loader context");
    engine
        .apply_quiesced_discovery(&mut session, Vec::new(), 0)
        .expect("the draining batch succeeds");
    assert!(
        engine.expected_target_exit(),
        "the latch completes once drainage finishes"
    );
    assert!(engine.views.is_empty());
}

/// `profile --pid` without `--duration` ends after its target exits even
/// when a retirement cleanup stays queued: once the armed wait runs past
/// the no-progress bound, the latch trips with a named PARTIAL reason and
/// keeps everything collected so far.
#[test]
fn stuck_cleanup_after_target_exit_ends_with_named_partial() {
    let (mut engine, _context) = Engine::retiring_loader_context(std::process::id());
    let view = ProcessViewId(0);
    // Settle the ExpectedRemoval the way process_discovery_records does:
    // the view is gone and its intent consumed, the arm records the
    // proven exit — but the loader ids stay queued past the bound.
    engine.views.clear();
    engine.release_view_id(view);
    engine.retirement_intents.clear();
    engine.scan_inputs.remove(&view);
    engine.arm_expected_target_exit(view);
    assert_eq!(
        engine.expected_target_exit_pending,
        Some(view),
        "the arm records the proven exit behind the Pid-scope gate"
    );
    assert!(
        engine.expected_target_exit_since.is_some(),
        "the arm stamps the no-progress clock"
    );
    engine.expected_target_exit_since = Some(
        std::time::Instant::now()
            - EXPECTED_TARGET_EXIT_NO_PROGRESS_TIMEOUT
            - std::time::Duration::from_secs(1),
    );
    assert!(!engine.expected_target_exit());
    assert!(
        !engine.loader_registry.ids_for_view(view).is_empty(),
        "the latch must still be blocked for this repro"
    );
    let skips_before = engine.counters.object_skips.clone();
    let mut session = ScriptedSession::default();
    engine
        .apply_quiesced_discovery(&mut session, Vec::new(), 0)
        .expect("the trip tick succeeds");
    assert!(
        engine.expected_target_exit(),
        "the profile pass ends once the bound expires: {:?}",
        engine.counters.object_skips
    );
    // The trip adds exactly one named PARTIAL reason and drops nothing.
    assert_eq!(
        engine.counters.object_skips.len(),
        skips_before.len() + 1,
        "one trip reason, nothing dropped or invented: {:?}",
        engine.counters.object_skips
    );
    assert_eq!(
        engine.counters.object_skips[..skips_before.len()],
        skips_before[..],
        "collected skips are kept: {:?}",
        engine.counters.object_skips
    );
    let trip = engine
        .counters
        .object_skips
        .last()
        .expect("the trip reason");
    assert_eq!(trip.subject, "live discovery transaction");
    assert!(
        trip.reason.contains("cleanup was still pending"),
        "the reason names the pending cleanup: {:?}",
        trip.reason
    );
    assert!(
        trip.reason
            .contains("the capture ends with the calls collected so far"),
        "the reason keeps the collected calls: {:?}",
        trip.reason
    );
    // The trip disarms the wait it ends.
    assert!(
        engine.expected_target_exit_pending.is_none(),
        "the trip disarms the wait"
    );
    // The trip projects through the generic skip pipeline to text/JSON.
    let public = render::capture_skipped_out(trip);
    assert_eq!(
        (public.name.as_str(), public.reason.as_str()),
        ("discovery subject", "discovery unavailable"),
        "the trip projects through the generic skip pipeline"
    );
    // Ending the wait neither drains nor forgets the queued cleanup.
    assert!(
        !engine.loader_registry.ids_for_view(view).is_empty(),
        "the queued cleanup is untouched by the trip"
    );
}

/// Twin: a cleanup that keeps draining past the 6 s horizon finishes
/// COMPLETE. Every draining tick resets the no-progress clock, so the
/// bound only trips on a stall with no progress at all — never on a
/// slow drain that is still moving.
#[test]
fn cleanup_that_keeps_progress_past_the_bound_finishes_complete() {
    use p11scope_manifest::elf::SymbolFact;

    let (mut engine, first) = Engine::retiring_loader_context(std::process::id());
    let view = ProcessViewId(0);
    // A second attached loader context on the same view: two drain steps,
    // so one tick can make progress while the wait stays blocked.
    let prepared = engine
        .loader_registry
        .preflight(LoaderContextSpec {
            view,
            loader: PinnedObjectId(10),
            mapping: None,
            hook: SymbolFact {
                virtual_address: 0x2200,
                file_offset: 0x2200,
            },
            state_address: None,
        })
        .expect("a preflighted second loader context");
    let second = engine
        .loader_registry
        .prepare(prepared)
        .expect("a prepared second loader context");
    engine
        .loader_registry
        .mark_attached(second)
        .expect("an attached second loader context");
    assert_eq!(
        engine.loader_registry.ids_for_view(view).len(),
        2,
        "two queued loader ids block the latch"
    );
    engine.views.clear();
    engine.release_view_id(view);
    engine.retirement_intents.clear();
    engine.scan_inputs.remove(&view);
    engine.arm_expected_target_exit(view);
    assert_eq!(engine.expected_target_exit_pending, Some(view));
    let mut session = ScriptedSession::default();
    // A full bound window passes, then one loader id clears: progress
    // resets the clock instead of tripping, and the wait stays armed.
    engine.expected_target_exit_since = Some(
        std::time::Instant::now()
            - EXPECTED_TARGET_EXIT_NO_PROGRESS_TIMEOUT
            - std::time::Duration::from_secs(1),
    );
    engine
        .loader_registry
        .tombstone(first)
        .expect("tombstoning the first drained loader context");
    engine
        .loader_registry
        .remove(first)
        .expect("draining the first loader context");
    engine
        .apply_quiesced_discovery(&mut session, Vec::new(), 0)
        .expect("a progressing drain keeps the pass open");
    assert!(
        !engine.expected_target_exit(),
        "a draining tick past the horizon does not trip the bound"
    );
    assert!(
        engine.expected_target_exit_pending.is_some(),
        "the wait stays armed while the drain is still blocked"
    );
    assert!(
        engine
            .expected_target_exit_since
            .expect("the clock stays armed while the wait is pending")
            .elapsed()
            < EXPECTED_TARGET_EXIT_NO_PROGRESS_TIMEOUT,
        "the draining tick reset the no-progress clock"
    );
    // A second full window passes and the last id clears: the ordinary
    // all-clear latches with no trip reason.
    engine.expected_target_exit_since = Some(
        std::time::Instant::now()
            - EXPECTED_TARGET_EXIT_NO_PROGRESS_TIMEOUT
            - std::time::Duration::from_secs(1),
    );
    engine
        .loader_registry
        .tombstone(second)
        .expect("tombstoning the last drained loader context");
    engine
        .loader_registry
        .remove(second)
        .expect("draining the last loader context");
    engine
        .apply_quiesced_discovery(&mut session, Vec::new(), 0)
        .expect("the draining batch succeeds");
    assert!(
        engine.expected_target_exit(),
        "the latch completes once drainage finishes"
    );
    assert!(
        engine
            .counters
            .object_skips
            .iter()
            .all(|skip| !skip.reason.contains("cleanup was still pending")),
        "no trip reason on a drain that kept progressing: {:?}",
        engine.counters.object_skips
    );
}

