/// Link gaps refuse the quiet claim: a finally lost link truncates at the
/// arm instant, and a recorded gap episode voids idle even when the final
/// snapshot shows every link live.
#[test]
fn prearm_link_gaps_refuse_idle() {
    use crate::render::{PrearmWatchEnd, PrearmWatchState};

    // Detach: arm with live links, then lose every link before the end.
    // The claim truncates at the last verified instant (the arm 1000), not
    // at the detection time (the stop 5000).
    let fixture = DiscoveryLifecycleFixture::start();
    let mut engine = fixture.discover_prearm_before_load();
    let mut linked = ScriptedSession::default();
    for slot in engine.plan().slots.iter() {
        linked.scripted_links.insert(slot.index);
        linked.scripted_stamps.insert(slot.index, 1000);
    }
    engine.refresh_prearm_liveness(&linked, Some(1000));
    let unlinked = ScriptedSession::default();
    engine.finish_prearm_capture(
        &unlinked,
        PrearmWatchEnd::ScopeEnd,
        &BTreeSet::new(),
        &[],
        Some(5000),
        &crate::metrics::KernelEvidence::default(),
        0,
        None,
        false,
        None,
    );
    let watch = engine.discovery.modules[0]
        .watch
        .as_ref()
        .expect("finish renders every watch");
    assert_eq!(watch.state, PrearmWatchState::Ended);
    assert_eq!(watch.ended_by, Some(PrearmWatchEnd::HealthLoss));
    assert_eq!(watch.since_ns, Some(1000));
    assert_eq!(watch.until_ns, Some(1000));
    // Rebuild: a healed gap the final snapshot cannot see still voids the
    // uninterrupted-quiet claim.
    let watch = finish_prearm_terminal_health(crate::metrics::KernelEvidence::default(), 0, 1);
    assert_eq!(watch.state, PrearmWatchState::Ended);
    assert_eq!(watch.ended_by, Some(PrearmWatchEnd::HealthLoss));
    assert_eq!(watch.since_ns, Some(1000));
    assert_eq!(watch.until_ns, Some(1000));
}

/// Packet 6.13 round-2 (F3): an object change detected after the first
/// stop must not extend the published bound past it. The watch arms at
/// 1000, the first stop freezes at 1000, and the change is detected later
/// at real-clock time: the published `until_ns` never exceeds the stop.
/// Round-3 (re-audit finding 1): the stop caps the coverage end only — the
/// published bracket still equals the real held-FD evidence.
#[test]
fn prearm_object_change_detected_after_stop_never_exceeds_first_stop() {
    use crate::render::{PrearmWatchEnd, PrearmWatchState};
    use std::io::Write as _;

    let fixture = DiscoveryLifecycleFixture::start();
    let mut engine = fixture.discover_prearm_before_load();
    assert!(engine.has_prearm_watches());
    let watch_id = engine
        .prearm
        .watches()
        .keys()
        .next()
        .copied()
        .expect("one pre-arm watch");
    let mut session = ScriptedSession::default();
    for slot in engine.plan().slots.iter() {
        session.scripted_links.insert(slot.index);
        session.scripted_stamps.insert(slot.index, 1000);
    }
    // A last successful held-FD check after the synthetic stop: the
    // published bracket must preserve it, not rewrite it to the stop.
    assert_eq!(engine.pinned().check_object_unchanged(watch_id), Ok(true));
    // Dirty the pinned provider after arming so the terminal refresh
    // detects the change at real-clock time (far past the frozen stop).
    std::thread::sleep(std::time::Duration::from_millis(20));
    {
        let provider = fixture.provider_path();
        let mut file = std::fs::OpenOptions::new()
            .append(true)
            .open(provider)
            .expect("dirty the pinned provider");
        file.write_all(b"x").expect("extend the pinned provider");
        file.sync_all().expect("persist the change");
    }
    engine.finish_prearm_capture(
        &session,
        PrearmWatchEnd::ScopeEnd,
        &BTreeSet::new(),
        &[],
        Some(1000),
        &crate::metrics::KernelEvidence::default(),
        0,
        None,
        false,
        None,
    );
    let watch = engine.discovery.modules[0]
        .watch
        .as_ref()
        .expect("finish renders every watch");
    assert_eq!(watch.state, PrearmWatchState::Ended);
    assert_eq!(watch.ended_by, Some(PrearmWatchEnd::ObjectChanged));
    assert_eq!(watch.since_ns, Some(1000));
    let until = watch
        .until_ns
        .expect("an object-changed end carries its bound");
    assert!(
        until <= 1000,
        "published bound {until} exceeds the first stop 1000"
    );
    // Round-3 (re-audit finding 1): the stop bounds the coverage end only.
    // The published bracket must equal the real held-FD evidence — both
    // checks ran after the synthetic stop, and neither may be rewritten.
    let real = engine
        .pinned()
        .change_bracket(watch_id)
        .expect("detection latched a real held-FD bracket");
    assert!(
        real.last_ok_ns > 1000 && real.detected_ns > 1000,
        "both bracket checks ran after the synthetic stop 1000: {real:?}"
    );
    assert_eq!(
        watch.changed,
        Some(real),
        "published bracket must equal the held-FD evidence"
    );
}

/// Packet 6.13 round-4 (re-audit finding 1): an object change detected
/// during terminal cleanup after an *unknown* first stop must not publish
/// a numeric coverage end — the detection ran in the blind tail past the
/// stop, so it cannot bound coverage. The watch still ends
/// `object_changed` with the exact held-FD bracket, but `until_ns` stays
/// unknown.
