#[test]
fn structurally_valid_orphan_table_record_is_rejected_and_never_lowered() {
    let dir = tempfile::tempdir().unwrap();
    let provider = dir.path().join("provider.so");
    std::fs::copy("/bin/sh", &provider).unwrap();
    let base = object_facts(&provider).2;
    let mut manifest = valid_manifest_for(std::slice::from_ref(&provider), &[0; 67]);
    manifest.selection_evidence =
        manifest_selection_evidence(Version { major: 3, minor: 0 }, &[("C_GetInfo", base + 80)]);
    let pins = pin_manifest_objects(&manifest).unwrap();
    let mut orphan = manifest.selection_evidence.tables[0].clone();
    orphan.id = 1;
    orphan
        .functions
        .iter_mut()
        .find(|function| function.name == "C_GetInfo")
        .unwrap()
        .resolution = Resolution::Resolved {
        object: 0,
        file_offset: base + 90,
    };
    manifest.selection_evidence.tables.push(orphan);
    // The table record itself is fully valid. Schema v5 deliberately makes
    // the containing document invalid solely because no authoritative
    // query references it, so no valid orphan document exists to accept.
    assert_eq!(
        crate::manifest_input::validate_structure(&manifest),
        ["selection table 1 is orphaned"]
    );
    let mut plan = plan::build_from_sources(&[], std::slice::from_ref(&manifest), &pins);
    let allocated = plan.clone();

    let (admissions, refused) = lower_manifest_selection_tables(
        &mut plan,
        &allocated,
        std::slice::from_ref(&manifest),
        &[7],
        &pins,
    );

    assert_eq!(
        admissions
            .iter()
            .map(|admission| admission.source)
            .collect::<Vec<_>>(),
        [(7, 0)]
    );
    assert!(refused.is_empty());
    assert!(plan.slots.iter().all(|slot| slot.file_offset != base + 90));
}

/// 6.07c item 16: KEM ordinals stay unwalked outside a resolved
/// 3.2 extent. v3.0 selection evidence never lists the KEM names;
/// all-NULL KEM resolutions lower no KEM targets while neighbors
/// survive; a partial 3.2 extent preserves its neighbors.
#[test]
fn manifest_selection_kem_ordinals_need_resolved_32_extent() {
    // Catalog structure: KEM lives only in the 3.2 extra fields,
    // past the v3.0 walk extent.
    let v30: Vec<&str> = pkcs11_module::FUNCTION_LIST_FIELDS
        .iter()
        .chain(pkcs11_module::FUNCTION_LIST_3_0_EXTRA_FIELDS)
        .map(|field| field.name)
        .collect();
    assert_eq!(v30.len(), 92, "v3.0 walks ordinals 0..92");
    assert!(!v30.contains(&"C_EncapsulateKey"));
    assert!(!v30.contains(&"C_DecapsulateKey"));
    let extra32: Vec<&str> = pkcs11_module::FUNCTION_LIST_3_2_EXTRA_FIELDS
        .iter()
        .map(|field| field.name)
        .collect();
    assert!(extra32.contains(&"C_EncapsulateKey"));
    assert!(extra32.contains(&"C_DecapsulateKey"));

    // v3.0 evidence lists no KEM function: nothing to lower.
    let evidence30 =
        manifest_selection_evidence(Version { major: 3, minor: 0 }, &[("C_GetInfo", 0x1000)]);
    assert!(
        !evidence30.tables[0].functions.iter().any(|function| {
            function.name == "C_EncapsulateKey" || function.name == "C_DecapsulateKey"
        }),
        "v3.0 selection never names KEM"
    );

    // v3.2 evidence with all-NULL KEM resolutions lowers the resolved
    // neighbor only: no KEM target enters the plan.
    let dir = tempfile::tempdir().unwrap();
    let provider = dir.path().join("provider.so");
    std::fs::copy("/bin/sh", &provider).unwrap();
    let base = object_facts(&provider).2;
    let mut manifest = valid_manifest_for(std::slice::from_ref(&provider), &[0; 67]);
    manifest.selection_evidence =
        manifest_selection_evidence(Version { major: 3, minor: 2 }, &[("C_GetInfo", base + 80)]);
    let problems = crate::manifest_input::validate_structure(&manifest);
    assert!(problems.is_empty(), "{problems:?}");
    let pins = pin_manifest_objects(&manifest).unwrap();
    let mut plan = plan::build_from_sources(&[], std::slice::from_ref(&manifest), &pins);
    let allocated = plan.clone();
    let (admissions, refused) = lower_manifest_selection_tables(
        &mut plan,
        &allocated,
        std::slice::from_ref(&manifest),
        &[0],
        &pins,
    );
    assert!(refused.is_empty());
    assert!(!admissions.is_empty(), "the neighbor admits");
    assert!(
        plan.slots.iter().all(|slot| {
            !slot
                .names
                .iter()
                .any(|name| name == "C_EncapsulateKey" || name == "C_DecapsulateKey")
        }),
        "NULL KEM resolutions lower no KEM targets"
    );
    assert!(
        plan.slots
            .iter()
            .any(|slot| slot.names.iter().any(|name| name == "C_GetInfo")),
        "the resolved neighbor survives"
    );

    // Partial 3.2 extent: one resolved KEM target lowers alongside
    // its neighbor; the NULL sibling stays out.
    let mut manifest = valid_manifest_for(std::slice::from_ref(&provider), &[0; 67]);
    manifest.selection_evidence = manifest_selection_evidence(
        Version { major: 3, minor: 2 },
        &[("C_GetInfo", base + 80), ("C_EncapsulateKey", base + 96)],
    );
    let problems = crate::manifest_input::validate_structure(&manifest);
    assert!(problems.is_empty(), "{problems:?}");
    let pins = pin_manifest_objects(&manifest).unwrap();
    let mut plan = plan::build_from_sources(&[], std::slice::from_ref(&manifest), &pins);
    let allocated = plan.clone();
    let (_, refused) = lower_manifest_selection_tables(
        &mut plan,
        &allocated,
        std::slice::from_ref(&manifest),
        &[0],
        &pins,
    );
    assert!(refused.is_empty());
    assert!(
        plan.slots
            .iter()
            .any(|slot| slot.names.iter().any(|name| name == "C_EncapsulateKey")),
        "the resolved KEM target lowers"
    );
    assert!(
        plan.slots
            .iter()
            .any(|slot| slot.names.iter().any(|name| name == "C_GetInfo")),
        "the neighbor survives the partial extent"
    );
    assert!(
        plan.slots
            .iter()
            .all(|slot| { !slot.names.iter().any(|name| name == "C_DecapsulateKey") }),
        "the NULL KEM sibling stays out"
    );
}

#[test]
fn stale_manifest_selection_does_not_transfer_to_scan_replacement() {
    let dir = tempfile::tempdir().unwrap();
    let provider = dir.path().join("provider.so");
    std::fs::copy("/bin/sh", &provider).unwrap();
    let base = object_facts(&provider).2;
    let paths = vec![provider.clone()];
    let targets = vec![0; 67];
    let mut manifest = valid_manifest_for(&paths, &targets);
    manifest.selection_evidence =
        manifest_selection_evidence(Version { major: 3, minor: 0 }, &[("C_GetInfo", base + 80)]);
    let problems = crate::manifest_input::validate_structure(&manifest);
    assert!(problems.is_empty(), "{problems:?}");
    let scan = scanned_manifest_replacement(&paths, &targets);
    let scan_pins = pin_scan(&scan);
    std::fs::remove_file(&provider).unwrap();
    let input = manifest_input_from_pinning("stale-selection.json", manifest);
    assert_eq!(input.stale[0].reason, ManifestStaleReason::OpenStale);
    let view = ProcessView::open(ProcessViewId(0), std::process::id()).unwrap();
    let mut discovered = lifecycle_discovered(vec![view]);
    discovered.scan_inputs.insert(
        ProcessViewId(0),
        ScanInput {
            modules: vec![scan],
            pins: scan_pins,
            counters: DiscoveryCounters::default(),
        },
    );
    discovered.manifest_inputs.push(input);

    rebuild_discovered(&mut discovered).unwrap();

    assert!(discovered.manifests.is_empty());
    assert_eq!(discovered.plan.modules.len(), 1);
    assert_eq!(discovered.plan.modules[0].source, "scan");
    assert!(
        discovered
            .plan
            .slots
            .iter()
            .any(|slot| slot.file_offset == base),
        "the exact scan replacement was accepted"
    );
    assert!(
        discovered
            .plan
            .slots
            .iter()
            .all(|slot| slot.file_offset != base + 80),
        "the scan replacement cannot inherit stale offline selection authority"
    );
}

fn selection_provider_address(engine: &Engine, binding: SelectionBindingFact) -> u64 {
    let provider = engine.pinned.summary(binding.object).unwrap().key;
    parse_maps(&std::fs::read(format!("/proc/{}/maps", engine.views[0].pid())).unwrap())
        .unwrap()
        .into_iter()
        .find(|mapping| ObjectKey::of(mapping) == provider)
        .unwrap()
        .start
}

/// [`armed_seed_route`] plus a retained provider: the engine already
/// discovered and holds the seed module when the loader record arrives —
/// the live shape of a no-change hit (a failed or refcount open resolves
/// against retained state, it does not discover the provider).
fn armed_seed_route_with_retained_provider(
    loader_hits: u64,
) -> (
    LoadedSeedProvider,
    Engine,
    LoaderContextId,
    DiscoveryRecord,
    ScriptedSession,
) {
    let (fixture, engine, mut session) = initial_export_route();
    session.counters.loader_hits = loader_hits;
    let pid = engine.views[0].pid();
    let context = engine.loader_registry.ids_for_view(ProcessViewId(0))[0];
    let spec = engine
        .loader_registry
        .context(context)
        .unwrap()
        .spec
        .clone();
    let mapping = spec.mapping.as_ref().unwrap();
    let mut record = loader_record_for(context, pid);
    record.table_ptr = mapping.start + (spec.hook.file_offset - mapping.file_offset);
    record.hook_ts_ns = engine.views[0].admitted_ns();
    assert!(
        !engine.modules.is_empty(),
        "the route must retain the seed provider or no-change twins are vacuous"
    );
    (fixture, engine, context, record, session)
}

fn armed_seed_route(
    loader_hits: u64,
) -> (
    LoadedSeedProvider,
    Engine,
    LoaderContextId,
    DiscoveryRecord,
    ScriptedSession,
) {
    let (fixture, view, _module, _pins) = loaded_seed_provider();
    let pid = view.pid();
    let mut engine = Engine::empty();
    engine.scope = Scope::Pid(pid);
    engine.next_view_id = 1;
    engine.views.push(view);
    let mut session = ScriptedSession::default();
    session.counters.loader_hits = loader_hits;
    engine
        .arm_loader_or_partial(
            0,
            &mut session,
            &mut true,
            &mut PendingViewRetirements::new(),
        )
        .unwrap();
    let context = engine.loader_registry.ids_for_view(ProcessViewId(0))[0];
    let spec = engine
        .loader_registry
        .context(context)
        .unwrap()
        .spec
        .clone();
    let mapping = spec.mapping.as_ref().unwrap();
    let mut record = loader_record_for(context, pid);
    record.table_ptr = mapping.start + (spec.hook.file_offset - mapping.file_offset);
    record.hook_ts_ns = engine.views[0].admitted_ns();
    (fixture, engine, context, record, session)
}

#[test]
fn loader_readiness_requires_committed_attachment_and_exact_session_link() {
    let (_fixture, mut engine, context, _record, mut session) = armed_seed_route(0);
    assert_eq!(engine.active_loader_hook_count(&session), 1);
    let link = session.dynamic_loader_links[0];
    for wrong in [
        (LoaderContextId::from_case_id(200), link.1, link.2, link.3),
        (link.0, PinnedObjectId(u32::MAX), link.2, link.3),
        (link.0, link.1, link.2 + 1, link.3),
        (link.0, link.1, link.2, link.3 ^ 1),
    ] {
        session.dynamic_loader_links = vec![wrong];
        assert_eq!(engine.active_loader_hook_count(&session), 0, "{wrong:?}");
    }
    session.dynamic_loader_links.clear();
    session
        .attach_dynamic_export(
            context,
            engine.views[0].pid(),
            (link.1, link.2),
            link.3,
            HookAbi::FunctionList,
            &engine.pinned,
        )
        .unwrap();
    assert_eq!(
        engine.active_loader_hook_count(&session),
        0,
        "a different program is not a loader hook"
    );
    session.dynamic_loader_links = vec![link];
    assert_eq!(engine.active_loader_hook_count(&session), 1);
    engine.loader_registry.tombstone(context).unwrap();
    assert!(
        engine
            .loader_registry
            .context(context)
            .unwrap()
            .was_attached
    );
    assert_eq!(engine.active_loader_hook_count(&session), 0);
}

#[test]
fn loader_readiness_prepared_context_with_installed_link_is_not_committed() {
    let (_fixture, mut engine, context, _record, mut session) = armed_seed_route(0);
    let spec = engine
        .loader_registry
        .context(context)
        .unwrap()
        .spec
        .clone();
    engine.loader_registry.tombstone(context).unwrap();
    let prepared = engine.loader_registry.preflight(spec.clone()).unwrap();
    let cookie = prepared.cookie();
    let pending = engine.loader_registry.prepare(prepared).unwrap();
    session
        .attach_dynamic_loader(
            pending,
            engine.views[0].pid(),
            spec.loader,
            spec.hook.file_offset,
            cookie,
            &engine.pinned,
        )
        .unwrap();
    assert_eq!(engine.active_loader_hook_count(&session), 0);
    engine.loader_registry.mark_attached(pending).unwrap();
    assert_eq!(engine.active_loader_hook_count(&session), 1);
}

#[test]
fn loader_readiness_refuses_retiring_gone_or_unowned_views() {
    let (mut fixture, mut engine, context, _record, session) = armed_seed_route(0);
    assert_eq!(engine.active_loader_hook_count(&session), 1);
    let view = engine.views[0].id();
    engine.queue_retirement(
        view,
        RetirementCause::ExecRefresh,
        &mut PendingViewRetirements::new(),
    );
    let before = engine.budget.attempted_io_bytes();
    assert_eq!(engine.active_loader_hook_count(&session), 0);
    assert_eq!(engine.budget.attempted_io_bytes(), before);
    engine.retirement_intents.clear();
    assert_eq!(engine.active_loader_hook_count(&session), 1);
    let pin = engine.pinned.clone();
    engine.pinned.remove_view(view).unwrap();
    assert_eq!(engine.active_loader_hook_count(&session), 0);
    engine.pinned = pin;
    let owner = engine.views.pop().unwrap();
    assert_eq!(engine.active_loader_hook_count(&session), 0);
    engine.views.push(owner);
    assert_eq!(engine.active_loader_hook_count(&session), 1);
    fixture.child.kill().unwrap();
    fixture.child.wait().unwrap();
    assert!(!engine.views[0].still_the_same());
    assert!(
        engine
            .loader_registry
            .context(context)
            .unwrap()
            .was_attached
    );
    assert_eq!(engine.active_loader_hook_count(&session), 0);
}

