#[test]
fn loader_readiness_revalidates_the_current_held_loader_mapping() {
    let (_fixture, mut engine, original, _record, mut session) = armed_seed_route(0);
    let original_spec = engine
        .loader_registry
        .context(original)
        .unwrap()
        .spec
        .clone();
    engine.loader_registry.tombstone(original).unwrap();
    let mut shifted = original_spec.mapping.clone().unwrap();
    shifted.start += 1;
    for (mapping, expected) in [(None, 1), (Some(shifted), 0)] {
        let mut spec = original_spec.clone();
        spec.mapping = mapping;
        let prepared = engine.loader_registry.preflight(spec.clone()).unwrap();
        let cookie = prepared.cookie();
        let context = engine.loader_registry.prepare(prepared).unwrap();
        session
            .attach_dynamic_loader(
                context,
                engine.views[0].pid(),
                spec.loader,
                spec.hook.file_offset,
                cookie,
                &engine.pinned,
            )
            .unwrap();
        engine.loader_registry.mark_attached(context).unwrap();
        assert_eq!(engine.active_loader_hook_count(&session), expected);
        engine.loader_registry.tombstone(context).unwrap();
    }
}

#[test]
fn loader_readiness_rechecks_original_pin_after_current_locator() {
    use std::os::unix::fs::PermissionsExt as _;
    use std::rc::Rc;
    let (_fixture, view, _module, _pins) = loaded_seed_provider_with_owned_loader(true);
    let mut engine = Engine::empty();
    engine.scope = Scope::Pid(view.pid());
    engine.views.push(view);
    let mut session = ScriptedSession::default();
    engine
        .arm_loader_or_partial(
            0,
            &mut session,
            &mut true,
            &mut PendingViewRetirements::new(),
        )
        .unwrap();
    assert_eq!(engine.active_loader_hook_count(&session), 1);
    let link = session.dynamic_loader_links[0];
    let loader = link.1;
    let file = engine.pinned.file_for(loader).unwrap().try_clone().unwrap();
    let before = FileSnapshot::read(&file).unwrap();
    assert!(engine.pinned.object_unchanged(loader).unwrap());
    let mode = file.metadata().unwrap().permissions().mode();
    let queried = Rc::new(Cell::new(false));
    let changed = queried.clone();
    *session.before_dynamic_loader_query.borrow_mut() = Some(Box::new(move || {
        file.set_permissions(std::fs::Permissions::from_mode(mode ^ 0o010))
            .unwrap();
        assert_ne!(FileSnapshot::read(&file).unwrap(), before);
        changed.set(true);
    }));
    let count = engine.active_loader_hook_count(&session);
    assert!(
        queried.get(),
        "the metadata change must follow the first original-pin check"
    );
    assert_eq!(session.dynamic_loader_links, [link]);
    assert!(engine.views[0].still_the_same());
    assert!(!engine.pinned.object_unchanged(loader).unwrap());
    assert_eq!(
        count, 0,
        "matching new locator snapshots cannot replace the original pin"
    );
}

/// Real direct-ELF child, pre-exec loader pin and post-exec identity check;
/// only kernel link installation and ring delivery use the scripted seam.
fn mapped_loader_record(engine: &mut Engine, context: LoaderContextId) -> DiscoveryRecord {
    let spec = engine
        .loader_registry
        .context(context)
        .unwrap()
        .spec
        .clone();
    let key = engine.pinned.summary(spec.loader).unwrap().key;
    let view = engine
        .views
        .iter()
        .find(|view| view.id() == spec.view)
        .unwrap();
    let maps = Engine::read_maps(view, &mut engine.budget).unwrap();
    let mapping = maps
        .iter()
        .find(|mapping| {
            ObjectKey::of(mapping) == key
                && mapping.permissions[2] == b'x'
                && spec.hook.file_offset >= mapping.file_offset
                && spec.hook.file_offset - mapping.file_offset < mapping.end - mapping.start
        })
        .unwrap();
    let mut record = loader_record_for(context, view.pid());
    record.table_ptr = mapping.start + spec.hook.file_offset - mapping.file_offset;
    record.hook_ts_ns = crate::attach::monotonic_ns().unwrap();
    record
}

fn owned_prearmed_seed_route(
    revalidate: bool,
) -> (
    LoadedSeedProvider,
    OwnedChild,
    Engine,
    LoaderContextId,
    DiscoveryRecord,
    ScriptedSession,
) {
    let (fixture, _, _, _) = loaded_seed_provider();
    let mut child = OwnedChild::spawn(
        fixture._dir.path().join("seed-runner").into_os_string(),
        vec![
            fixture
                ._dir
                .path()
                .join("seed-provider.so")
                .into_os_string(),
        ],
    )
    .unwrap();
    let mut engine = Engine::empty();
    engine.scope = Scope::Pid(child.pid());
    engine.next_view_id = 1;
    engine
        .views
        .push(ProcessView::open(ProcessViewId(0), child.pid()).unwrap());
    let mut session = ScriptedSession::default();
    session.dynamic_loader_reports_added = true;
    assert!(matches!(
        engine
            .arm_owned_loader_before_release(
                &child,
                &mut session,
                &mut true,
                &mut PendingViewRetirements::new()
            )
            .unwrap(),
        OwnedLoaderPrearmOutcome::Armed
    ));
    let context = engine.loader_registry.ids_for_view(ProcessViewId(0))[0];
    engine.record_loader_arm(ProcessViewId(0), true);
    child.release().unwrap();
    let exec = exec_record_for(child.pid());
    if revalidate {
        engine
            .revalidate_owned_session_with(
                &child,
                &mut session,
                &mut Engine::collect_discovery_records,
            )
            .unwrap();
    }
    assert!(session.detached.is_empty());
    // Wait for the provider's real mapping, not an arbitrary settle sleep.
    let provider = fixture._dir.path().join("seed-provider.so");
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
    while !std::fs::read_to_string(format!("/proc/{}/maps", child.pid()))
        .unwrap()
        .contains(provider.to_str().unwrap())
    {
        assert!(std::time::Instant::now() < deadline);
        std::thread::yield_now();
    }
    (fixture, child, engine, context, exec, session)
}

/// The owned pre-exec loader arming accepts a run cgroup scope naming
/// the held child, exactly as it accepts the exact PID scope: the
/// barrier-held child is discovered, armed, and never released here
/// (dropping it exits 127 behind the closed barrier).
#[test]
fn owned_loader_prearm_arms_beside_a_run_cgroup_naming_the_child() {
    let (fixture, _, _, _) = loaded_seed_provider();
    let child = OwnedChild::spawn(
        fixture._dir.path().join("seed-runner").into_os_string(),
        vec![
            fixture
                ._dir
                .path()
                .join("seed-provider.so")
                .into_os_string(),
        ],
    )
    .unwrap();
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(
        dir.path().join("cgroup.procs"),
        format!("{}\n", child.pid()),
    )
    .unwrap();
    let mut engine = Engine::empty();
    engine.scope = crate::scope::cgroup(dir.path()).unwrap();
    engine.next_view_id = 1;
    engine
        .views
        .push(ProcessView::open(ProcessViewId(0), child.pid()).unwrap());
    let mut session = ScriptedSession::default();
    session.dynamic_loader_reports_added = true;
    assert!(matches!(
        engine
            .arm_owned_loader_before_release(
                &child,
                &mut session,
                &mut true,
                &mut PendingViewRetirements::new()
            )
            .unwrap(),
        OwnedLoaderPrearmOutcome::Armed
    ));
}

#[test]
fn engine_retains_pid_reports_live_views_only() {
    let mut engine = Engine::empty();
    assert!(
        !engine.retains_pid(std::process::id()),
        "an empty engine retains nothing"
    );
    engine.next_view_id = 1;
    engine
        .views
        .push(ProcessView::open(ProcessViewId(0), std::process::id()).expect("own view opens"));
    assert!(
        engine.retains_pid(std::process::id()),
        "a live view for the pid retains it"
    );
    assert!(!engine.retains_pid(u32::MAX), "no view, no retention");
    let mut sleeper = std::process::Command::new("sleep")
        .arg("30")
        .spawn()
        .expect("spawn sleeper");
    let stale_pid = sleeper.id();
    engine
        .views
        .push(ProcessView::open(ProcessViewId(1), stale_pid).expect("sleeper view opens"));
    assert!(engine.retains_pid(stale_pid), "a live view retains its pid");
    sleeper.kill().expect("kill sleeper");
    sleeper.wait().expect("reap sleeper");
    assert!(
        !engine.retains_pid(stale_pid),
        "a reaped view retains nothing"
    );
}

#[test]
fn engine_pid_target_pin_returns_the_named_view_pin() {
    let mut engine = Engine::empty();
    assert!(
        engine.pid_target_pin(std::process::id()).is_none(),
        "an empty engine holds no pin"
    );
    engine.next_view_id = 1;
    engine
        .views
        .push(ProcessView::open(ProcessViewId(0), std::process::id()).expect("own view opens"));
    let pin = engine
        .pid_target_pin(std::process::id())
        .expect("the named view keeps its pin");
    assert_eq!(pin.pid(), std::process::id());
    assert!(pin.still_the_same(), "the live pin brackets its own view");
    assert!(
        std::sync::Arc::ptr_eq(&pin, engine.views[0].retained_pin_arc()),
        "the accessor shares the view allocation, never a reopen"
    );
    assert!(engine.pid_target_pin(u32::MAX).is_none(), "no view, no pin");
}

#[test]
fn loader_arming_gate_spares_the_owned_run_child_under_tree_scope() {
    let mut engine = Engine::empty();
    engine.scope = Scope::Cgroup {
        id: 1,
        path: "/".into(),
        dir: std::sync::Arc::new(std::fs::File::open("/").unwrap()),
    };
    engine.next_view_id = 2;
    engine
        .views
        .push(ProcessView::open(ProcessViewId(0), std::process::id()).expect("own view opens"));
    let mut sleeper = std::process::Command::new("sleep")
        .arg("30")
        .spawn()
        .expect("spawn sleeper");
    engine
        .views
        .push(ProcessView::open(ProcessViewId(1), sleeper.id()).expect("sleeper view opens"));
    // Provider-free under a generation-admitting scope: both gate.
    assert!(engine.loader_arming_gated(ProcessViewId(0)));
    assert!(engine.loader_arming_gated(ProcessViewId(1)));
    // The owned run child is the one named generation: it always
    // arms, so the pause follows its exec chain; other members stay
    // exploratory.
    engine.owned_run_pid = Some(std::process::id());
    assert!(!engine.loader_arming_gated(ProcessViewId(0)));
    assert!(engine.loader_arming_gated(ProcessViewId(1)));
    // Exact-PID scope never gates (base behavior, unaffected).
    engine.scope = Scope::Pid(1);
    engine.owned_run_pid = None;
    assert!(!engine.loader_arming_gated(ProcessViewId(0)));
    assert!(!engine.loader_arming_gated(ProcessViewId(1)));
    sleeper.kill().expect("kill sleeper");
    sleeper.wait().expect("reap sleeper");
}

#[test]
fn engine_note_run_tree_gap_publishes_under_the_run_tree_subject() {
    let mut engine = Engine::empty();
    assert_eq!(engine.run_tree_handed_back(), 0);
    engine.note_run_tree_gap(crate::render::RUN_TREE_DEGRADED, None);
    assert_eq!(engine.counters.object_skips.len(), 1);
    let skipped = &engine.counters.object_skips[0];
    assert_eq!(skipped.subject, "run process tree");
    assert_eq!(skipped.reason, crate::render::RUN_TREE_DEGRADED);
    assert_eq!(
        engine.run_tree_handed_back(),
        0,
        "a degradation measures no survivors"
    );
    engine.note_run_tree_gap(crate::render::RUN_TREE_DEGRADED, None);
    assert_eq!(
        engine.counters.object_skips.len(),
        1,
        "an identical gap dedups like every other skip"
    );
    engine.note_run_tree_gap(crate::render::RUN_TREE_SURVIVORS, Some(2));
    assert_eq!(engine.run_tree_handed_back(), 2);
    assert_eq!(engine.counters.object_skips.len(), 2);
}

