/// Live regression (GT-1): `run --pause auto` of a short-lived child lost the
/// whole capture — the next tick's deferred loader scan found the child gone,
/// and "pid N exited before discovery" aborted the capture with no report.
/// A process that exits before its deferred scan runs is a bounded, counted
/// discovery loss for that view, never a capture-fatal error.
#[test]
fn rt_add_deferral_fallback_after_target_exit_is_bounded_loss_not_fatal() {
    let (mut fixture, mut engine, _context, mut record, mut session) = armed_seed_route(1);
    record.announced_count = 1;
    apply_ordinary_batch(&mut engine, &mut session, vec![record]).unwrap();
    assert_eq!(engine.pending_loader_scans.len(), 1);
    let truncated_before = engine.discovery_truncated;

    fixture.child.kill().unwrap();
    fixture.child.wait().unwrap();

    let outcome = apply_ordinary_batch(&mut engine, &mut session, Vec::new());

    let outcome = outcome.expect("an exited target's deferred scan must not abort the capture");
    assert!(!outcome.required_complete);
    assert!(engine.pending_loader_scans.is_empty());
    assert_eq!(engine.loader_memory_scan_attempts, 1);
    assert!(engine.discovery_truncated > truncated_before);
}

/// R57 boundary fixture: both subjects have the same vendor factory and
/// no standard PKCS#11 exports. Only one returns a real sparse table. Its
/// private callback executes three times before the target is ended.
fn exit_loader_subject(
    private_provider: bool,
) -> (LoadedSeedProvider, Engine, DiscoveryRecord, ScriptedSession) {
    let dir = tempfile::tempdir().unwrap();
    let source = dir.path().join("subject.c");
    let library = dir.path().join("subject.so");
    let runner = dir.path().join("runner");
    let ready = dir.path().join("ready");
    let go = dir.path().join("go");
    std::fs::write(
        &source,
        r#"
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdint.h>
#include <stdio.h>
#include <unistd.h>
typedef unsigned long (*callback)(void *);
struct table { unsigned char version[2]; callback functions[68]; };
#ifdef SUBJECT_LIBRARY
#ifdef PRIVATE_PROVIDER
static unsigned long hidden_init(void *arg) { (void)arg; return 0; }
static struct table surface = { {3,2}, { [0] = hidden_init } };
__attribute__((visibility("default"))) void *VendorSurface(void) { return &surface; }
#else
__attribute__((visibility("default"))) void *VendorSurface(void) { return 0; }
#endif
#else
static int signal_ready(const char *path, const char *state, unsigned calls) {
    FILE *f = fopen(path, "w");
    if (!f) return 1;
    int failed = fprintf(f, "%s calls=%u\n", state, calls) < 0;
    return fclose(f) != 0 || failed;
}
int main(int argc, char **argv) {
    if (argc != 4 || signal_ready(argv[2], "READY", 0)) return 2;
    while (access(argv[3], F_OK) != 0) usleep(1000);
    void *handle = dlopen(argv[1], RTLD_NOW | RTLD_LOCAL);
    if (!handle) return 3;
    void *(*factory)(void) = (void *(*)(void))dlsym(handle, "VendorSurface");
    if (!factory) return 4;
    struct table *t = factory();
    unsigned calls = 0;
    if (t) {
        if (t->version[0] != 3 || t->version[1] != 2 || !t->functions[0]) return 5;
        for (unsigned i = 1; i < 68; i++) if (t->functions[i]) return 6;
        for (unsigned i = 0; i < 3; i++) {
            if (t->functions[0](0) != 0) return 7;
            calls++;
        }
    }
    if (signal_ready(argv[2], t ? "PRIVATE" : "BENIGN", calls)) return 8;
    while (access(argv[3], F_OK) == 0) usleep(1000);
    return 0;
}
#endif
"#,
    )
    .unwrap();
    let mut compile = std::process::Command::new("gcc");
    compile.args([
        "-std=c11",
        "-Wall",
        "-Wextra",
        "-Werror",
        "-fvisibility=hidden",
        "-shared",
        "-fPIC",
        "-DSUBJECT_LIBRARY",
    ]);
    if private_provider {
        compile.arg("-DPRIVATE_PROVIDER");
    }
    assert!(
        compile
            .arg(&source)
            .arg("-o")
            .arg(&library)
            .status()
            .unwrap()
            .success()
    );
    assert!(
        std::process::Command::new("gcc")
            .args(["-std=c11", "-Wall", "-Wextra", "-Werror"])
            .arg(&source)
            .arg("-ldl")
            .arg("-o")
            .arg(&runner)
            .status()
            .unwrap()
            .success()
    );
    let child = std::process::Command::new(&runner)
        .arg(&library)
        .arg(&ready)
        .arg(&go)
        .die_with_parent()
        .spawn()
        .unwrap();
    let mut fixture = LoadedSeedProvider {
        child,
        peers: Vec::new(),
        _dir: dir,
    };
    let wait_for = |fixture: &mut LoadedSeedProvider, expected: &str| {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(3);
        loop {
            if std::fs::read_to_string(&ready).is_ok_and(|line| line == expected) {
                break;
            }
            assert!(
                fixture.child.try_wait().unwrap().is_none(),
                "subject exited before its handshake"
            );
            assert!(
                std::time::Instant::now() < deadline,
                "subject readiness timed out"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
    };
    wait_for(&mut fixture, "READY calls=0\n");
    let view = ProcessView::open(ProcessViewId(0), fixture.child.id()).unwrap();
    let mut engine = Engine::empty();
    engine.scope = Scope::Pid(fixture.child.id());
    engine.next_view_id = 1;
    engine.module_hints = vec![library.clone()];
    engine.views.push(view);
    let mut session = ScriptedSession::default();
    session.counters.loader_hits = 2;
    engine
        .arm_loader_or_partial(
            0,
            &mut session,
            &mut true,
            &mut PendingViewRetirements::new(),
        )
        .unwrap();
    let context = engine.loader_registry.ids_for_view(ProcessViewId(0))[0];
    let spec = engine
        .loader_registry
        .context(context)
        .unwrap()
        .spec
        .clone();
    let mapping = spec.mapping.as_ref().unwrap();
    let mut record = loader_record_for(context, fixture.child.id());
    record.table_ptr = mapping.start + (spec.hook.file_offset - mapping.file_offset);
    record.hook_ts_ns = engine.views[0].admitted_ns();
    record.announced_count = 1;
    std::fs::write(&go, b"go").unwrap();
    wait_for(
        &mut fixture,
        if private_provider {
            "PRIVATE calls=3\n"
        } else {
            "BENIGN calls=0\n"
        },
    );
    // An export-only acquisition intentionally cannot see the private
    // table. Its empty tables are not negative provider authority.
    let (metadata, _) = Engine::scan_retained_view_without_memory(
        &engine.views[0],
        &engine.module_hints,
        &engine.hooks,
        &mut engine.budget,
        engine.broad_admit,
        &mut engine.stage_timings,
    );
    let (modules, _, _) = metadata.unwrap();
    assert_eq!(
        modules.len(),
        1,
        "the hinted subject must actually be examined"
    );
    assert_eq!(Path::new(&modules[0].path), library.as_path());
    assert!(modules[0].tables.is_empty() && modules[0].interfaces.is_empty());
    assert!(modules[0].exports.is_empty());
    (fixture, engine, record, session)
}

fn finish_exit_loader_subject(fixture: &mut LoadedSeedProvider) {
    std::fs::remove_file(fixture._dir.path().join("go")).unwrap();
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(3);
    loop {
        if let Some(status) = fixture.child.try_wait().unwrap() {
            assert!(status.success());
            break;
        }
        assert!(
            std::time::Instant::now() < deadline,
            "subject exit timed out"
        );
        std::thread::sleep(std::time::Duration::from_millis(1));
    }
}

/// Future R57 desired positive, expected RED until the observer has a
/// provider-free transaction receipt. This draft has not been run. ADD/zero
/// and empty metadata-only surface currently do not supply that receipt.
/// Tracked as ignored (see docs/notes/2026-10-29-r57-exit-receipt-boundary.md):
/// no sufficient exit-time receipt exists; settlement is always a counted
/// truncation. Un-ignore when a settlement receipt lands.
#[test]
#[ignore]
fn exit_loader_balanced_benign_transaction_needs_no_terminal_truncation() {
    let (mut fixture, mut engine, record, mut session) = exit_loader_subject(false);
    session.counters.loader_hits = 1;
    apply_ordinary_batch(&mut engine, &mut session, vec![record]).unwrap();
    assert_eq!(engine.pending_loader_scans.len(), 1);
    assert_eq!(engine.loader_records_accepted, 1);
    finish_exit_loader_subject(&mut fixture);
    let mut consistent = record;
    consistent.announced_count = 0;
    consistent.hook_ts_ns += 1;
    session.counters.loader_hits = 2;
    apply_ordinary_batch(&mut engine, &mut session, vec![consistent]).unwrap();
    assert_eq!(
        engine.discovery_truncated, 0,
        "R57: balanced benign exit-time work needs a strong settlement receipt; empty metadata is insufficient"
    );
}

#[test]
fn exit_loader_same_metadata_private_sparse_provider_stays_unknown() {
    let (mut fixture, mut engine, record, mut session) = exit_loader_subject(true);
    session.counters.loader_hits = 1;
    apply_ordinary_batch(&mut engine, &mut session, vec![record]).unwrap();
    assert_eq!(engine.pending_loader_scans.len(), 1);
    assert_eq!(engine.loader_records_accepted, 1);
    finish_exit_loader_subject(&mut fixture);
    let mut consistent = record;
    consistent.announced_count = 0;
    consistent.hook_ts_ns += 1;
    session.counters.loader_hits = 2;
    apply_ordinary_batch(&mut engine, &mut session, vec![consistent]).unwrap();
    assert!(
        engine.discovery_truncated > 0,
        "balanced states and no standard exports cannot erase a private sparse provider's unread table"
    );
}

#[test]
fn exit_loader_live_balanced_benign_transaction_runs_ordinary_scan() {
    let (_fixture, mut engine, record, mut session) = exit_loader_subject(false);
    let mut consistent = record;
    consistent.announced_count = 0;
    consistent.hook_ts_ns += 1;
    apply_ordinary_batch(&mut engine, &mut session, vec![record, consistent]).unwrap();
    assert!(engine.pending_loader_scans.is_empty());
    assert_eq!(engine.loader_memory_scan_attempts, 1);
    assert_eq!(engine.discovery_truncated, 0);
}

/// Live: `run --pause auto` of a child that dlopens SoftHSM2 captured
/// 2000/2000 calls with 6-7 confirmed stops, and still read `concrete_gap`
/// because its loader context's dlopen timing was "unproven". Timing is
/// unproven only for want of a loader timing catalog; a stop does not need
/// one. When every loader hit of the view was held by a pause cycle (and so
/// every table it published was attached before the child resumed), the
/// context is pause-protected, not a gap. One unpaused hit keeps it lossy.
#[test]
fn a_loader_context_whose_every_hit_was_paused_is_pause_protected() {
    let (_fixture, mut engine, _context, mut record, mut session) = armed_seed_route(2);
    record.announced_count = 0;

    engine.set_pause_owned_batch(true);
    apply_ordinary_batch(&mut engine, &mut session, vec![record]).unwrap();
    engine.set_pause_owned_batch(false);

    let aggregate = engine.loader_discovery();
    assert_eq!(aggregate.strategies.debug_state_every_hit, 1);
    assert_eq!(
        aggregate.dlopen_timing.unproven, 0,
        "a held hit is not unproven timing: {aggregate:?}"
    );
    assert_eq!(aggregate.dlopen_timing.pause_protected, 1);

    let mut unpaused = record;
    unpaused.hook_ts_ns += 1;
    apply_ordinary_batch(&mut engine, &mut session, vec![unpaused]).unwrap();
    let aggregate = engine.loader_discovery();
    assert_eq!(aggregate.dlopen_timing.pause_protected, 0);
    assert_eq!(
        aggregate.dlopen_timing.unproven, 1,
        "one hit the child ran through keeps the context lossy"
    );
}

/// An owned run published "the empty timing catalog leaves initial-set
/// capture unproven" as a `discovery subject / discovery unavailable` skip
/// on every run, beside the `loader_discovery.initial_set_capture` class that
/// already states exactly that gap: nothing was unavailable, and the one fact
/// was counted twice. The aggregate is the one authority for it now.
#[test]
fn the_initial_set_timing_gap_is_not_also_published_as_a_skip() {
    let source = include_str!("engine.rs");
    let marker = [
        "the empty timing catalog leaves ",
        "initial-set capture unproven",
    ]
    .concat();
    assert!(
        !source.contains(&marker),
        "the initial-set timing gap is published by loader_discovery alone"
    );
}

/// GT-4: `attach_gap_ms` was `null` on ordinary `run` captures. An RT_ADD or
/// RT_DELETE hit only defers a memory scan until the RT_CONSISTENT that ends
/// the loader transaction; a process that exits first never relocated or
/// initialized the object, so no provider code ran unobserved. Settling that
/// scan at the process's provable exit stays a counted truncation, but it
/// used to erase every measured gap in the capture as if a causal record had
/// been lost.
#[test]
fn a_deferred_scan_ended_by_its_process_exit_keeps_the_measured_attach_gap() {
    let (mut fixture, mut engine, _context, mut record, mut session) = armed_seed_route(1);
    let measured = timing_key(0);
    engine.timings.observe(&measured, 1_000_000);
    engine.timings.complete(&measured, 3_000_000);
    record.announced_count = 1;
    apply_ordinary_batch(&mut engine, &mut session, vec![record]).unwrap();
    assert_eq!(engine.pending_loader_scans.len(), 1);
    let truncated_before = engine.discovery_truncated;

    fixture.child.kill().unwrap();
    fixture.child.wait().unwrap();
    apply_ordinary_batch(&mut engine, &mut session, Vec::new()).unwrap();

    assert!(engine.pending_loader_scans.is_empty());
    assert!(
        engine.discovery_truncated > truncated_before,
        "the unresolved scan stays counted"
    );
    assert!(
        engine
            .capture_facts()
            .attach_gap_ms()
            .is_some_and(|gap| gap >= 2),
        "the measured gap survives: {:?}",
        engine.capture_facts().attach_gap_ms()
    );
}

/// The same rule on the record path: a loader record of a generation that
/// provably ended cannot be resolved, but an RT_ADD or RT_DELETE hit
/// introduces no code that could run. Only a record that could have
/// published a callable provider (RT_CONSISTENT, an export return, an exec)
/// still leaves the capture's gap unproven.
#[test]
fn an_ended_generations_loader_record_nulls_the_gap_only_if_code_could_have_run() {
    for (state, keeps_gap) in [(1, true), (2, true), (0, false)] {
        let (mut fixture, mut engine, _context, mut record, mut session) = armed_seed_route(1);
        let measured = timing_key(0);
        engine.timings.observe(&measured, 1_000_000);
        engine.timings.complete(&measured, 3_000_000);
        fixture.child.kill().unwrap();
        fixture.child.wait().unwrap();
        record.announced_count = state;

        apply_ordinary_batch(&mut engine, &mut session, vec![record]).unwrap();

        assert_eq!(
            engine.capture_facts().attach_gap_ms().is_some(),
            keeps_gap,
            "r_state {state}: {:?}",
            engine.counters.object_skips
        );
    }
}

/// Asserts the named capture ended the ordinary way after its target exited:
/// the view retired as an expected removal, and no generation loss was
/// published for a process that provably just ended.
fn assert_named_target_exit_ended_capture(engine: &Engine) {
    assert!(
        engine.expected_target_exit(),
        "the capture ends as a target exit: {:?}",
        engine.counters.object_skips
    );
    assert!(engine.views.is_empty());
    assert!(
        engine.counters.object_skips.iter().all(|skip| {
            skip.subject != "live discovery generation"
                && skip.subject != "live inventory generation"
                && !skip.reason.contains("generation changed")
        }),
        "a proven exit is not a lost generation: {:?}",
        engine.counters.object_skips
    );
}

/// RB-1 remainder, loader arming. A `--pid`/`run` target that exits while its
/// loader context is being attached failed the whole capture with "the named
/// process generation changed during loader attachment": `still_the_same()` is
/// false for an exit and a replacement alike, and the arm path never asked the
/// retained pin which one it was. A provable exit is the target ending.
#[test]
fn named_target_exit_during_loader_arming_ends_the_capture_not_fails_it() {
    let (_fixture, view, _module, _pins) = loaded_seed_provider();
    let pid = view.pid();
    let view_id = view.id();
    let mut engine = Engine::empty();
    engine.scope = Scope::Pid(pid);
    engine.next_view_id = 1;
    engine.views.push(view);
    let mut session = ScriptedSession::default();
    session.lose_generation_at_dynamic_loader_attach(pid);
    let mut pending = PendingViewRetirements::new();

    let armed = engine.arm_loader_or_partial(0, &mut session, &mut true, &mut pending);

    armed.expect("a named target that exited mid-arm is not a capture failure");
    assert_eq!(session.dynamic_loader_attach_calls, 1);
    assert_eq!(
        pending.get(&view_id),
        Some(&RetirementCause::ExpectedRemoval)
    );
    apply_ordinary_batch(&mut engine, &mut session, Vec::new())
        .expect("the next batch retires the exited target");
    assert_named_target_exit_ended_capture(&engine);
    assert!(engine.loader_registry.ids_for_view(view_id).is_empty());
}

/// RB-1 remainder, inventory preflight. A named target that exits between a
/// refresh's scan and either inventory preflight is the target ending, not a
/// changed generation: the capture ends as a target exit with its report.
/// The post-retirement preflight used to fail the capture with "the named
/// process generation changed during inventory preflight"; the first one
/// published a false generation loss.
#[test]
fn named_target_exit_during_inventory_preflight_ends_the_capture_not_fails_it() {
    for (label, losses) in [
        ("first", vec![Some(())]),
        ("post-retirement", vec![None, Some(())]),
    ] {
        // The preflight kills and reaps this child; the test never waits on it.
        let pid = spawn_execed_sleep().id();
        let mut engine = Engine::empty();
        engine.scope = Scope::Pid(pid);
        engine.next_view_id = 1;
        engine
            .views
            .push(ProcessView::open(ProcessViewId(0), pid).unwrap());
        engine.request_refresh(pid, None);
        engine.scheduler.set_tick_quantum_ns_for_test(u64::MAX);
        let mut session = ScriptedSession::default();
        session.lose_generations_at_preflight(losses.iter().map(|loss| loss.map(|()| pid)));
        let mut collect: Box<DiscoveryCollector<'_>> = Box::new(Engine::collect_discovery_records);

        let mut tick_now = crate::attach::monotonic_ns;
        let refreshed = engine.refresh_inventory(
            &mut session,
            &mut true,
            &mut Vec::new(),
            &mut PendingViewRetirements::new(),
            &mut *collect,
            &mut PauseClosure::new(true),
            &mut tick_now,
        );

        refreshed.unwrap_or_else(|error| {
            panic!("{label} preflight: a named target's exit is not a capture failure: {error:#}")
        });
        assert!(
            session.preflight_targets.borrow().len() >= losses.len(),
            "{label}: the scripted exit ran inside that preflight"
        );
        assert_named_target_exit_ended_capture(&engine);
    }
}

