/// Block until `pid` has exec'd past its fork-of-the-test-runner phase:
/// its exe link no longer names this test binary AND its maps already carry
/// that image's executable mapping (the exe link alone switches in
/// `begin_new_exec()`, before the new segments are mapped — see
/// `maps_have_executable_image`). A snapshot taken before this point sees
/// the test runner's own mappings, including transiently dlopened
/// `/tmp/.tmp*/provider.so` fixtures that vanish before pin time (hosted CI
/// run 37422857664). Bounded like the snapshot loop below, with a generous
/// deadline plus a final predicate check after the last sleep (P2-6: the
/// child may settle during that sleep); on timeout FAILS LOUD naming the
/// child and the last evidence, never silently proceeds.
fn wait_for_child_exec(pid: u32) {
    let this_image = std::env::current_exe().unwrap();
    let exe = format!("/proc/{pid}/exe");
    let maps_path = format!("/proc/{pid}/maps");
    let settled = || {
        let image = std::fs::read_link(&exe).ok();
        let maps = std::fs::read_to_string(&maps_path).ok();
        let execed = image.as_ref().is_some_and(|image| {
            image != &this_image
                && maps
                    .as_ref()
                    .is_some_and(|maps| maps_have_executable_image(maps, image))
        });
        let evidence = format!(
            "exe={image:?} maps_head={:?}",
            maps.as_deref()
                .map(|maps| maps.lines().take(3).collect::<Vec<_>>().join("\\n"))
        );
        (execed, evidence)
    };
    for _ in 0..3000 {
        if settled().0 {
            return;
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
    }
    let (execed, evidence) = settled();
    if execed {
        return;
    }
    panic!("sleep child {pid} never execed; last evidence: {evidence}");
}

// Self-contained fixture control: exercise this actual code without compiling
// the observer when checking loader phases and the existing wait budget.
mod provider_pair_readiness {
    use std::path::{Path, PathBuf};

    pub(super) fn indices(paths: &[PathBuf], exe: &Path) -> Option<(usize, usize)> {
        let image = paths.iter().position(|path| path == exe)?;
        // Keep the existing facts consumer's libc classification; readiness
        // must wait for that same object, rather than accepting the loader.
        let libc = paths
            .iter()
            .position(|path| path != exe && path.to_string_lossy().contains("libc.so"))?;
        Some((image, libc))
    }

    pub(super) fn poll<T>(
        mut attempt: impl FnMut() -> Option<T>,
        mut pause: impl FnMut(),
        polls: usize,
    ) -> Option<T> {
        for _ in 0..polls {
            if let Some(pair) = attempt() {
                return Some(pair);
            }
            pause();
        }
        attempt()
    }

    #[test]
    fn executable_and_loader_do_not_prove_libc_ready() {
        let exe = Path::new("/fixture/sleep");
        let paths = vec![exe.to_path_buf(), PathBuf::from("/fixture/ld-linux.so.2")];
        assert_eq!(indices(&paths, exe), None);
    }

    #[test]
    fn ready_pair_selects_exact_executable_and_libc() {
        let exe = Path::new("/fixture/sleep");
        let paths = vec![
            PathBuf::from("/fixture/other-program"),
            PathBuf::from("/fixture/ld-linux.so.2"),
            PathBuf::from("/fixture/libc.so.6"),
            exe.to_path_buf(),
        ];
        assert_eq!(indices(&paths, exe), Some((3, 2)));
    }

    #[test]
    fn delayed_libc_is_checked_on_the_final_existing_attempt() {
        let exe = Path::new("/fixture/sleep");
        let phase = std::cell::Cell::new(0);
        let result = poll(
            || {
                let mut paths = vec![exe.to_path_buf(), PathBuf::from("/fixture/ld-linux.so.2")];
                if phase.get() == 2 {
                    paths.push(PathBuf::from("/fixture/libc.so.6"));
                }
                indices(&paths, exe)
            },
            || phase.set(phase.get() + 1),
            2,
        );
        assert_eq!(result, Some((0, 2)));
        assert_eq!(phase.get(), 2);
    }

    #[test]
    fn missing_libc_exhausts_the_existing_attempt_budget() {
        let exe = Path::new("/fixture/sleep");
        let paths = vec![exe.to_path_buf(), PathBuf::from("/fixture/ld-linux.so.2")];
        let attempts = std::cell::Cell::new(0);
        let pauses = std::cell::Cell::new(0);
        let result = poll(
            || {
                attempts.set(attempts.get() + 1);
                indices(&paths, exe)
            },
            || pauses.set(pauses.get() + 1),
            3,
        );
        assert_eq!(result, None);
        assert_eq!((attempts.get(), pauses.get()), (4, 3));
    }
}

/// Two provider modules over distinct executable objects the live child
/// really mapped. Keep the existing bounded wait and final snapshot attempt.
fn snapshot_two_provider_modules(view: &ProcessView) -> Vec<ScannedModule> {
    let attempt = || {
        let bytes = std::fs::read(format!("/proc/{}/maps", view.pid())).unwrap();
        let maps = parse_maps(&bytes).unwrap();
        let map_index = MapIndex::new(&maps).expect("the live child maps snapshot is valid");
        let exe = std::fs::read_link(format!("/proc/{}/exe", view.pid())).unwrap();
        let mut keys = BTreeSet::new();
        let mut objects = Vec::new();
        for mapping in maps
            .iter()
            .filter(|mapping| mapping.permissions[2] == b'x' && mapping.inode != 0)
        {
            let Resolved::File {
                path: MappedPath::Usable(path),
                ..
            } = map_index.resolve(mapping.start)
            else {
                continue;
            };
            if !keys.insert(ObjectKey::of(mapping)) {
                continue;
            }
            objects.push((mapping, path));
        }
        let paths: Vec<_> = objects.iter().map(|(_, path)| path.clone()).collect();
        let (exe, libc) = provider_pair_readiness::indices(&paths, &exe)?;
        Some(vec![
            provider_module(view, objects[exe].0, &objects[exe].1, 0x1000),
            provider_module(view, objects[libc].0, &objects[libc].1, 0x1000),
        ])
    };
    provider_pair_readiness::poll(
        attempt,
        || std::thread::sleep(std::time::Duration::from_millis(10)),
        3000,
    )
    .expect("the live child never mapped its executable and libc provider pair")
}

fn child_provider_modules(view: &ProcessView) -> Vec<ScannedModule> {
    wait_for_child_exec(view.pid());
    snapshot_two_provider_modules(view)
}

/// Settle a pipe-held pre-exec child: asserts the child is provably still
/// a fork of the test runner (it cannot have passed the release gate),
/// then releases it and waits for exec settle. The pre-exec assertion is
/// what makes the RED direction deterministic: a helper that snapshots
/// without waiting sees test-runner mappings.
fn child_provider_modules_with_held_child(
    view: &ProcessView,
    child: &mut HeldChild,
) -> Vec<ScannedModule> {
    let test_image = std::env::current_exe().unwrap();
    let exe = std::fs::read_link(format!("/proc/{}/exe", child.pid()))
        .expect("the held child is alive and readable");
    assert_eq!(
        exe, test_image,
        "the held child exec'd before release: the handshake is broken"
    );
    child.release();
    wait_for_child_exec(child.pid());
    snapshot_two_provider_modules(view)
}

fn pin_test_modules(view: &ProcessView, modules: &[ScannedModule]) -> PinnedObjects {
    let mut budget = CaptureWorkBudget::new(ScanLimits {
        per_object_bytes: u64::MAX,
        total_bytes: u64::MAX,
    });
    let (pins, skipped) = pin_scanned_view_objects(view, modules, &mut budget).unwrap();
    assert!(skipped.is_empty(), "{skipped:?}");
    pins
}

/// A live child, an Engine that retains one process view on it, and one
/// accepted provider already attached in slot 0. The returned modules are
/// `[accepted, peer]`; the peer is what a later candidate allocates.
fn engine_with_one_accepted_provider() -> (std::process::Child, Engine, Vec<ScannedModule>) {
    let child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let view = ProcessView::open(ProcessViewId(3), child.id()).unwrap();
    let modules = child_provider_modules(&view);
    let mut engine = Engine::empty();
    engine.scope = Scope::Pid(child.id());
    engine.next_view_id = 4;
    engine.views.push(view);
    let pins = pin_test_modules(&engine.views[0], &modules[..1]);
    let candidate = engine
        .live_candidate(pins, vec![modules[0].clone()], Vec::new())
        .unwrap();
    assert_eq!(candidate.delta.new.len(), 1);
    let mut session = ScriptedSession::default();
    let mut additions = true;
    let outcome = engine
        .apply_candidate(&mut session, candidate, &mut additions, false, &[])
        .unwrap();
    assert!(outcome.accepted(), "the first candidate is accepted whole");
    assert_eq!(engine.plan.slots.len(), 1);
    assert!(engine.plan.module_of_slot(0).is_some());
    (child, engine, modules)
}

/// The candidate that allocates one more cell for the peer provider.
fn peer_candidate(engine: &mut Engine, modules: &[ScannedModule]) -> LiveCandidate {
    let mut pins = engine.pinned.clone();
    let skipped = pins.absorb(pin_test_modules(&engine.views[0], &modules[1..2]));
    let candidate = engine
        .live_candidate(pins, modules.to_vec(), skipped)
        .unwrap();
    assert_eq!(
        candidate.delta.new.len(),
        1,
        "only the peer provider is newly allocated"
    );
    assert_eq!(candidate.plan.slots.len(), 2);
    candidate
}

/// A raw fork held pre-exec by a parent/child pipe handshake (P2-6):
/// the child signals readiness, then blocks on the release pipe until
/// [`HeldChild::release`] writes the release byte. No sleep establishes
/// the ordering under test — the child cannot exec before release, however
/// the host schedules. Dropping without release kills and reaps the held
/// child.
struct HeldChild {
    pid: u32,
    release: Option<std::fs::File>,
}

impl HeldChild {
    fn pid(&self) -> u32 {
        self.pid
    }

    /// Writes the release byte, then closes the pipe: the child execs
    /// `sleep 30`. An explicit byte, not EOF: `O_CLOEXEC` does not cross
    /// fork, so an unrelated forked-but-never-exec'd child may inherit the
    /// writer and an EOF-close release would hang until it exits. A write
    /// failure means the child is already dead; the exec wait then fails
    /// loudly instead of hanging.
    fn release(&mut self) {
        if let Some(release) = self.release.take() {
            use std::os::unix::io::AsRawFd as _;
            let fd = release.as_raw_fd();
            let byte = [1u8];
            loop {
                // SAFETY: one byte into the live release pipe. Rust ignores
                // SIGPIPE process-wide, so a dead child surfaces as EPIPE.
                let wrote = unsafe { libc::write(fd, byte.as_ptr() as *const _, 1) };
                if wrote == 1 {
                    break;
                }
                if wrote == -1
                    && std::io::Error::last_os_error().kind() == std::io::ErrorKind::Interrupted
                {
                    continue;
                }
                break;
            }
        }
    }
}

impl Drop for HeldChild {
    fn drop(&mut self) {
        // SAFETY: this unprivileged fixture owns this live, unreaped child.
        unsafe {
            libc::kill(self.pid as libc::pid_t, libc::SIGKILL);
            let mut status = 0;
            libc::waitpid(self.pid as libc::pid_t, &mut status, 0);
        }
    }
}

/// Spawn `sleep 30` through a raw fork whose child blocks pre-exec until
/// release: immediately after this returns, the child is provably still a
/// fork of the test runner (the ready byte was consumed). A
/// `Command::pre_exec` gate cannot do this — it forces the fork path whose
/// error pipe makes `spawn` block until the exec — and plain `spawn` only
/// wins the pre-exec race under load (0/2000 locally, fatal on hosted CI run
/// 37422857664).
fn spawn_held_sleep_child() -> HeldChild {
    let program = std::ffi::CString::new("sleep").unwrap();
    let arg0 = std::ffi::CString::new("sleep").unwrap();
    let arg1 = std::ffi::CString::new("30").unwrap();
    let argv = [arg0.as_ptr(), arg1.as_ptr(), std::ptr::null()];
    let mut ready = [0 as libc::c_int; 2];
    let mut release = [0 as libc::c_int; 2];
    // SAFETY: pipe2 writes both fds on success; CLOEXEC keeps them out of
    // the exec'd image.
    assert_eq!(
        unsafe { libc::pipe2(ready.as_mut_ptr(), libc::O_CLOEXEC) },
        0,
        "ready pipe failed: {}",
        std::io::Error::last_os_error()
    );
    assert_eq!(
        unsafe { libc::pipe2(release.as_mut_ptr(), libc::O_CLOEXEC) },
        0,
        "release pipe failed: {}",
        std::io::Error::last_os_error()
    );
    // SAFETY: fork in a multithreaded binary. The child calls only
    // async-signal-safe functions before the exec (prctl, getppid, close,
    // read, write, execvp) and `_exit(127)` if the exec fails; it never
    // returns to test code, runs no destructors, and touches no allocator
    // state. All pointers are parent C strings, valid across the fork.
    let owner = std::process::id();
    let pid = unsafe { libc::fork() };
    assert!(pid >= 0, "fork failed: {}", std::io::Error::last_os_error());
    if pid == 0 {
        unsafe {
            // Parent-death guard (same body as
            // `crate::fixture_guard::DieWithParent`): a test that dies
            // mid-hold must not strand the sleeper.
            if libc::prctl(libc::PR_SET_PDEATHSIG, libc::SIGKILL as libc::c_ulong) != 0 {
                libc::_exit(127);
            }
            if libc::getppid() != owner as libc::pid_t {
                libc::_exit(127);
            }
            libc::close(ready[0]);
            libc::close(release[1]);
            let byte = [1u8];
            // The ready byte cannot block: the pipe is empty.
            libc::write(ready[1], byte.as_ptr() as *const _, 1);
            libc::close(ready[1]);
            // Block until the parent's release byte arrives, or EOF if the
            // parent died without releasing: either way the child proceeds
            // to a harmless `sleep`. Interrupted reads retry; any other
            // outcome proceeds to exec rather than hanging.
            let mut gate = [0u8; 1];
            loop {
                let got = libc::read(release[0], gate.as_mut_ptr() as *mut _, 1);
                if got == 1 || got == 0 {
                    break;
                }
                if got == -1 && *libc::__errno_location() == libc::EINTR {
                    continue;
                }
                break;
            }
            libc::close(release[0]);
            libc::execvp(program.as_ptr(), argv.as_ptr());
            libc::_exit(127);
        }
    }
    // SAFETY: the parent owns these fresh pipe ends; closing the ends it
    // never uses lets EOF report a dead child instead of hanging.
    unsafe {
        libc::close(ready[1]);
        libc::close(release[0]);
    }
    // Bound the wait with a poll: a stuck child must fail loudly, never
    // hang the suite; interrupted polls retry inside the helper.
    let readable = system_scope_poll_fd(ready[0], std::time::Duration::from_secs(30))
        .unwrap_or_else(|error| panic!("held child {pid} readiness poll failed: {error}"));
    let mut byte = [0u8; 1];
    // SAFETY: `ready[0]` is the parent's live read end.
    let read = if readable {
        loop {
            let got = unsafe { libc::read(ready[0], byte.as_mut_ptr() as *mut _, 1) };
            if got == 1 || got == 0 {
                break got;
            }
            if got == -1
                && std::io::Error::last_os_error().kind() == std::io::ErrorKind::Interrupted
            {
                continue;
            }
            break got;
        }
    } else {
        -2
    };
    // SAFETY: the ready byte was consumed (or the child is dead); the read
    // end is no longer needed.
    unsafe {
        libc::close(ready[0]);
    }
    if read != 1 {
        // SAFETY: this unprivileged fixture owns this live, unreaped child.
        unsafe {
            libc::kill(pid, libc::SIGKILL);
            let mut status = 0;
            libc::waitpid(pid, &mut status, 0);
            libc::close(release[1]);
        }
        panic!("held child {pid} died before its ready byte (read={read})");
    }
    // SAFETY: `release[1]` is a fresh pipe end this process owns; `File`
    // closes it on drop, which is the release signal.
    let release = unsafe { std::os::unix::io::FromRawFd::from_raw_fd(release[1]) };
    HeldChild {
        pid: pid as u32,
        release: Some(release),
    }
}

/// A forked-but-never-exec'd child that inherits every fd (astra A4):
/// models a concurrent test's `SwapChild` outliving the release. Killed
/// and reaped on drop; exits on its own after 60 s if drop never runs.
struct FdInheritor {
    pid: libc::pid_t,
}

impl FdInheritor {
    fn spawn() -> Self {
        let mut ready = [0 as libc::c_int; 2];
        // SAFETY: pipe2 writes both fds on success; CLOEXEC keeps them
        // out of any exec'd image.
        assert_eq!(
            unsafe { libc::pipe2(ready.as_mut_ptr(), libc::O_CLOEXEC) },
            0,
            "ready pipe failed: {}",
            std::io::Error::last_os_error()
        );
        // SAFETY: fork in a multithreaded binary. The child calls only
        // async-signal-safe functions (prctl, getppid, write, close,
        // nanosleep on a stack timespec, _exit) and never returns to
        // test code.
        let owner = std::process::id();
        let pid = unsafe { libc::fork() };
        assert!(
            pid >= 0,
            "inheritor fork failed: {}",
            std::io::Error::last_os_error()
        );
        if pid == 0 {
            unsafe {
                libc::close(ready[0]);
                // Parent-death guard (same body as
                // `crate::fixture_guard::DieWithParent`): a test that dies
                // abruptly must not strand the sleeping child.
                if libc::prctl(libc::PR_SET_PDEATHSIG, libc::SIGKILL as libc::c_ulong) != 0 {
                    libc::_exit(127);
                }
                if libc::getppid() != owner as libc::pid_t {
                    libc::_exit(127);
                }
                // Readiness: the parent returns only after this write, so
                // a returned child is always armed. Without it, the
                // spawner thread can exit before the child arms, and the
                // `getppid` recheck cannot observe thread death, so the
                // child misses its death signal and sleeps on.
                let byte = [1u8];
                if libc::write(ready[1], byte.as_ptr().cast(), byte.len()) != byte.len() as isize {
                    libc::_exit(127);
                }
                libc::close(ready[1]);
                let delay = libc::timespec {
                    tv_sec: 60,
                    tv_nsec: 0,
                };
                libc::nanosleep(&delay, std::ptr::null_mut());
                libc::_exit(0);
            }
        }
        // SAFETY: the parent owns the read end; one byte proves the child
        // armed before this returns. A child that died first closes its
        // ends, so a short read ends as EOF, never a hang.
        unsafe {
            libc::close(ready[1]);
        }
        let mut byte = [0u8; 1];
        loop {
            // SAFETY: `read` into the live stack buffer.
            let got = unsafe { libc::read(ready[0], byte.as_mut_ptr().cast(), byte.len()) };
            if got == byte.len() as isize {
                break;
            }
            if got == 0 {
                panic!("inheritor child died before arming");
            }
            if got < 0 {
                let error = std::io::Error::last_os_error();
                if error.raw_os_error() == Some(libc::EINTR) {
                    continue;
                }
                panic!("inheritor readiness read failed: {error}");
            }
        }
        // SAFETY: the readiness byte was consumed; the read end served
        // its single byte.
        unsafe {
            libc::close(ready[0]);
        }
        Self { pid }
    }
}

impl Drop for FdInheritor {
    fn drop(&mut self) {
        // SAFETY: this unprivileged fixture owns this live, unreaped child.
        unsafe {
            libc::kill(self.pid, libc::SIGKILL);
            let mut status = 0;
            libc::waitpid(self.pid, &mut status, 0);
        }
    }
}

/// A forked fd-inheriting child must die with its spawner: without the
/// parent-death arm it sleeps its whole 60 s once its spawner is gone.
/// A helper thread plays the spawner; only the arm can kill the
/// forgotten child.
#[test]
fn fd_inheritor_dies_with_spawning_thread() {
    let recorded = std::thread::spawn(|| {
        let child = FdInheritor::spawn();
        let pid = child.pid as u32;
        let start =
            crate::process::process_start_time(pid).expect("the inheriting child has a start time");
        let recorded = vec![(pid, start)];
        std::mem::forget(child);
        recorded
    })
    .join()
    .expect("the spawner thread joins");
    let survivors =
        crate::fixture_guard::poll_descendants_gone(&recorded, std::time::Duration::from_secs(2));
    crate::fixture_guard::cleanup_descendants(&recorded);
    assert!(
        survivors.is_empty(),
        "the fd-inheriting child {recorded:?} outlived its spawner"
    );
}

/// Astra A4: `O_CLOEXEC` does not cross fork, so a concurrent test's
/// forked-but-never-exec'd child inherits the release writer; an EOF-close
/// release would hang until that child exits. The explicit release byte
/// wakes the held child regardless of unrelated inheritors.
#[test]
fn held_child_release_byte_ignores_unrelated_inheritors() {
    let mut child = spawn_held_sleep_child();
    let pid = child.pid();
    let _inheritor = FdInheritor::spawn();
    let test_image = std::env::current_exe().unwrap();
    let exe = std::fs::read_link(format!("/proc/{pid}/exe")).unwrap();
    assert_eq!(exe, test_image, "the held child exec'd before release");
    child.release();
    wait_for_child_exec(pid);
    let image = std::fs::read_link(format!("/proc/{pid}/exe")).unwrap();
    assert_ne!(
        image, test_image,
        "release did not exec the held child past the inheritor"
    );
}

/// Dev-flake regression (hosted CI run 37422857664): the helper snapshotted
/// a freshly spawned child before it exec'd and returned the TEST RUNNER's
/// own mappings — including transiently dlopened `/tmp/.tmp*/provider.so`
/// fixtures — which then vanished before pin time (ENOENT `Skipped`). The
/// child below is provably pre-exec when the helper runs, so the old code
/// deterministically returned the test binary as its first module. The
/// settled helper never returns test-runner mappings, and the settled child
/// maps its own image.
#[test]
fn child_provider_modules_waits_for_exec_settle() {
    let mut child = spawn_held_sleep_child();
    let pid = child.pid();
    let view = ProcessView::open(ProcessViewId(3), pid).unwrap();
    let modules = child_provider_modules_with_held_child(&view, &mut child);
    let test_image = std::env::current_exe().unwrap();
    assert!(
        modules
            .iter()
            .all(|module| Path::new(&module.path) != test_image),
        "pre-exec garbage: the helper returned test-runner mappings: {modules:?}"
    );
    let image = std::fs::read_link(format!("/proc/{pid}/exe")).unwrap();
    assert!(
        modules
            .iter()
            .any(|module| Path::new(&module.path) == image),
        "the settled child maps its own image {image:?}: {modules:?}"
    );
}

/// `entries` endpoints of one heuristic table at `0x1000, 0x1008, …` of
/// `module`'s own object.
fn with_endpoints(mut module: ScannedModule, entries: u32) -> ScannedModule {
    let table = module.tables[0].clone();
    module.tables = vec![ScannedTable {
        entries: (0..entries)
            .map(|entry| ScannedEntry {
                name: "C_Sign",
                object: module.key,
                object_path: module.path.clone(),
                file_offset: 0x1000 + u64::from(entry) * 8,
            })
            .collect(),
        ..table
    }];
    module
}

/// PC-1 (A row 1-04). Every ordinary process exit in a cgroup or system
/// capture queues a conservative replay, which rebuilds the plan from every
/// still-listed module with additions closed. A listed endpoint that is not
/// active — its attach failed, or a closed tick blocked it — was allocated a
/// fresh capture-lifetime cell by every such replay and deactivated unlinked
/// in the same breath. Under churn that burned the whole slot budget: the
/// replays kept draining, but a provider that fit the active slots many times
/// over was then refused for the rest of the capture. A candidate whose
/// additions never ran gives its unlinked cells back.
#[test]
fn conservative_replays_under_churn_never_burn_capacity() {
    let capacity = p11scope_ebpf_common::MAX_SLOTS;
    let child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let _reap = ChildReaper(child);
    let view = ProcessView::open(ProcessViewId(3), _reap.0.id()).unwrap();
    let modules = child_provider_modules(&view);
    let busy = with_endpoints(modules[0].clone(), capacity - 100);
    let late = with_endpoints(modules[1].clone(), 50);
    let mut engine = Engine::empty();
    engine.scope = Scope::System;
    engine.next_view_id = 4;
    engine.views.push(view);
    let pins = pin_test_modules(&engine.views[0], std::slice::from_ref(&busy));
    let candidate = engine
        .live_candidate(pins, vec![busy.clone()], Vec::new())
        .unwrap();
    let mut session = ScriptedSession::default();
    // Thirty of the busy provider's attaches fail: listed, not active.
    session.fail_target_slots(0..30);
    let outcome = engine
        .apply_candidate(&mut session, candidate, &mut true, false, &[])
        .unwrap();
    assert!(outcome.accepted());
    session.fail_target_slots([]);
    let allocated = engine.plan.slots.len();
    assert_eq!(allocated, capacity as usize - 100);
    assert_eq!(engine.plan.active_slot_count(), allocated - 30);

    // Churn: an ambient process with no modules exits, again and again.
    for exit in 0..8 {
        engine.pending_retirements.insert(ProcessViewId(100 + exit));
        engine.replay_pending_conservative(
            &mut session,
            &mut true,
            &mut PendingViewRetirements::new(),
        );
        assert!(
            engine.pending_retirements.is_empty(),
            "exit {exit}: the replay drained its retirement"
        );
        assert_eq!(
            engine.plan.slots.len(),
            allocated,
            "exit {exit}: a replay with additions closed allocates nothing"
        );
    }
    assert!(
        engine.plan.modules_skipped.is_empty(),
        "no capacity refusal was published: {:?}",
        engine.plan.modules_skipped
    );

    // Discovery still admits a later provider that fits, and retries the
    // busy provider's inactive endpoints in the same open candidate.
    let mut pins = engine.pinned.clone();
    let skipped = pins.absorb(pin_test_modules(
        &engine.views[0],
        std::slice::from_ref(&late),
    ));
    let candidate = engine
        .live_candidate(pins, vec![busy, late], skipped)
        .unwrap();
    let outcome = engine
        .apply_candidate(&mut session, candidate, &mut true, false, &[])
        .unwrap();
    assert!(outcome.accepted());
    assert!(
        engine.plan.modules_skipped.is_empty(),
        "the late provider was admitted: {:?}",
        engine.plan.modules_skipped
    );
    assert_eq!(engine.plan.slots.len(), allocated + 30 + 50);
    assert_eq!(engine.plan.active_slot_count(), allocated + 50);
}

/// Kills and reaps its child when dropped.
struct ChildReaper(std::process::Child);

impl Drop for ChildReaper {
    fn drop(&mut self) {
        let _ = self.0.kill();
        let _ = self.0.wait();
    }
}

#[test]
fn post_mutation_generation_loss_never_owns_the_cell_it_allocated() {
    let (child, mut engine, modules) = engine_with_one_accepted_provider();
    let accepted_owner = engine.plan.module_of_slot(0);
    let candidate = peer_candidate(&mut engine, &modules);
    let mut session = ScriptedSession::losing_generation_at_attach(child.id());
    let mut additions = true;

    let outcome = engine
        .apply_candidate(&mut session, candidate, &mut additions, false, &[])
        .unwrap();

    assert!(!outcome.stale_views.is_empty(), "the generation was lost");
    assert_eq!(
        engine.plan.slots.len(),
        2,
        "an allocated endpoint is never given back"
    );
    assert!(!engine.plan.is_active(0));
    assert!(!engine.plan.is_active(1));
    assert_eq!(
        engine.plan.module_of_slot(1),
        None,
        "a cell this candidate allocated but never got accepted owns nothing"
    );
    assert_eq!(
        engine.plan.module_of_slot(0),
        accepted_owner,
        "an owner already accepted before the candidate stays valid"
    );
    assert_eq!(engine.plan.module_ambiguous, 0);
    assert_eq!(
        engine.pinned.pinned().count(),
        0,
        "the stale view's live pins are cleaned"
    );
    assert!(engine.modules.is_empty());
    assert!(!additions);
    assert!(!outcome.required_complete());
}

fn rebuild_timing_owners(
    pins: &PinnedObjects,
    plan: &plan::AttachPlan,
) -> BTreeMap<plan::ModuleId, PinnedTimingKey> {
    plan.modules
        .iter()
        .filter_map(|module| {
            pins.owned_timing_key(module.object)
                .map(|key| (module.id, key))
        })
        .collect()
}

#[test]
fn rebuild_report_recompletions_record_reactivation_for_siblings() {
    let (mut plan, pins) = plan_with_pins(2, 0);
    let owners = rebuild_timing_owners(&pins, &plan);
    let key = owners.get(&plan::ModuleId(0)).cloned().unwrap();
    let mut engine = Engine::empty();
    let mut outcome = ApplyOutcome::default();

    engine.apply_group_rebuild(
        &mut plan,
        &owners,
        DetachOutcome {
            pending: None,
            recompleted: vec![(1, Some(50))],
            rebuild_failures: Vec::new(),
            rebuilt_groups: 1,
        },
        &mut outcome,
    );

    assert!(plan.is_active(0));
    assert!(plan.is_active(1));
    assert_eq!(outcome.static_completions.len(), 1);
    assert_eq!(
        outcome.static_completions[0],
        (BTreeSet::from([key]), Some(50))
    );
    assert!(outcome.static_failures.is_empty());
    assert_eq!(engine.multi_rebuild_gaps(), 1);
    assert!(
        engine.counters.object_skips.iter().any(|skip| skip.subject
            == "multi group rebuild"
            && skip.reason
                == "one or more groups rebuilt; calls in flight across the rebuild window may pair entry and return across attachment generations"),
        "the rebuild window publishes pairing uncertainty: {:?}",
        engine.counters.object_skips
    );
}

#[test]
fn rebuild_report_failures_deactivate_and_record_loss() {
    let (mut plan, pins) = plan_with_pins(2, 0);
    let owners = rebuild_timing_owners(&pins, &plan);
    let key = owners.get(&plan::ModuleId(0)).cloned().unwrap();
    let mut engine = Engine::empty();
    let mut outcome = ApplyOutcome::default();

    engine.apply_group_rebuild(
        &mut plan,
        &owners,
        DetachOutcome {
            pending: None,
            recompleted: Vec::new(),
            rebuild_failures: vec![(1, "p11_return refused".into())],
            rebuilt_groups: 1,
        },
        &mut outcome,
    );

    assert!(plan.is_active(0));
    assert!(!plan.is_active(1));
    assert!(outcome.static_completions.is_empty());
    assert_eq!(outcome.static_failures, BTreeSet::from([key]));
    assert_eq!(engine.multi_rebuild_gaps(), 1);
    assert!(
        engine.counters.object_skips.iter().any(
            |skip| skip.subject == "multi group rebuild" && skip.reason.contains("deactivated")
        ),
        "failed survivors deactivate with a published reason: {:?}",
        engine.counters.object_skips
    );
}

