#[derive(Debug)]
struct FakeSession(std::rc::Rc<std::cell::RefCell<Vec<&'static str>>>);

impl Drop for FakeSession {
    fn drop(&mut self) {
        self.0.borrow_mut().push("drop");
    }
}

/// Mutation caught: starting before the precheck would attach against a raw,
/// potentially recycled named PID.
#[test]
fn named_generation_change_before_attach_never_starts_a_session() {
    let view = ProcessView::open(ProcessViewId(0), std::process::id()).unwrap();
    let stale = view.id();
    let mut discovered = lifecycle_discovered(vec![view]);
    let starts = Cell::new(0);
    let error = start_retained_with(
        &mut discovered,
        true,
        |_| vec![stale],
        |_, _| {
            starts.set(starts.get() + 1);
            Ok(FakeSession(Default::default()))
        },
    )
    .expect_err("a named generation change is fatal");

    assert!(error.to_string().contains("before attach"), "{error:#}");
    assert_eq!(starts.get(), 0, "no attach action may follow the mismatch");
}

/// Mutation caught: returning the new session before the postcheck would make its
/// ring/maps consumable; failing without dropping it would leave its links live.
#[test]
fn named_generation_change_during_attach_drops_before_event_consumption() {
    let view = ProcessView::open(ProcessViewId(0), std::process::id()).unwrap();
    let stale = view.id();
    let mut discovered = lifecycle_discovered(vec![view]);
    let checks = Cell::new(0);
    let log = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
    let error = start_retained_with(
        &mut discovered,
        true,
        |_| {
            checks.set(checks.get() + 1);
            (checks.get() == 2).then_some(stale).into_iter().collect()
        },
        |_, _| {
            log.borrow_mut().push("start");
            Ok(FakeSession(std::rc::Rc::clone(&log)))
        },
    )
    .expect_err("a named generation change is fatal");

    assert!(error.to_string().contains("while attaching"), "{error:#}");
    assert_eq!(*log.borrow(), ["start", "drop"]);
    assert!(!log.borrow().contains(&"consume"));
}

/// Mutation caught: retrying without subtracting an originally accepted stale
/// view can spin forever under cgroup churn. Before any session exists, each
/// accepted view that went stale is removed with one plan rebuild, and the
/// session then starts exactly once.
#[test]
fn cgroup_retries_retire_one_original_view_each_time_and_publish_partial() {
    let views: Vec<_> = (0..3)
        .map(|id| ProcessView::open(ProcessViewId(id), std::process::id()).unwrap())
        .collect();
    let original: Vec<_> = views.iter().map(ProcessView::id).collect();
    let mut discovered = lifecycle_discovered(views);
    let checks = Cell::new(0usize);
    let starts = Cell::new(0usize);
    let log = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
    let session = start_retained_with(
        &mut discovered,
        false,
        |_| {
            checks.set(checks.get() + 1);
            original
                .get(checks.get() - 1)
                .copied()
                .into_iter()
                .collect()
        },
        |_, _| {
            starts.set(starts.get() + 1);
            log.borrow_mut().push("start");
            Ok(FakeSession(std::rc::Rc::clone(&log)))
        },
    )
    .unwrap();

    assert_eq!(starts.get(), 1, "the session starts once");
    assert_eq!(
        checks.get(),
        original.len() + 2,
        "one check per removal, one before and one after the start"
    );
    assert!(discovered.views.is_empty());
    assert_eq!(
        discovered
            .counters
            .object_skips
            .iter()
            .filter(|skip| skip.reason == STALE_VIEW_REASON)
            .count(),
        original.len(),
        "each retired accepted view remains accounted internally"
    );
    assert_eq!(
        discovered.plan.skipped.len(),
        1,
        "identical public cgroup losses use the existing bounded deduplication"
    );
    assert!(
        discovered
            .plan
            .skipped
            .iter()
            .map(render::capture_skipped_out)
            .all(|skip| skip.name == "discovery subject" && skip.reason == "discovery unavailable")
    );
    assert_eq!(*log.borrow(), ["start"], "no session was torn down");
    drop(session);
}

/// A counter start that meets stale views during attach preparation keeps
/// its Counters policy. The retain loop rebuilds the plan from the surviving
/// views' scan inputs, which always lowers a Detailed plan; without a
/// re-admission under the start budget the session holds prepared counter
/// banks while the Engine plan — and therefore the capture's counter owner
/// inputs — silently leaves the Counters policy, and the first collection
/// read bails with "prepared counter collection unavailable (owner limits
/// and reserver required)". Zero modules, one stale view before the start.
#[test]
fn counter_start_readmits_retained_plan_under_its_budget_after_stale_removal() {
    let views: Vec<_> = (0..2)
        .map(|id| ProcessView::open(ProcessViewId(id), std::process::id()).unwrap())
        .collect();
    let stale = views[0].id();
    let mut discovered = lifecycle_discovered(views);
    // Mirrors `start_session_with` just before the retain loop: the empty
    // discovery plan re-admitted under the counter endpoint budget.
    let budget = crate::capacity::CounterBudget::new(8192).unwrap();
    discovered.plan = discovered.plan.with_counters_policy(budget).unwrap();
    let checks = Cell::new(0usize);
    let log = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
    let session = start_retained_with(
        &mut discovered,
        false,
        |_| {
            checks.set(checks.get() + 1);
            (checks.get() == 1).then_some(stale).into_iter().collect()
        },
        |_, _| {
            log.borrow_mut().push("start");
            Ok(FakeSession(std::rc::Rc::clone(&log)))
        },
    )
    .unwrap();
    assert!(
        matches!(
            discovered.plan.admission_policy(),
            crate::plan::AdmissionPolicy::Detailed
        ),
        "stale-view removal rebuilds the retained plan Detailed"
    );
    discovered
        .restore_counters_policy_after_retain(budget)
        .unwrap();
    assert!(
        matches!(
            discovered.plan.admission_policy(),
            crate::plan::AdmissionPolicy::Counters(kept) if kept == budget
        ),
        "the retained plan is re-admitted under the unchanged start budget"
    );
    assert!(
        discovered.plan.slots.is_empty(),
        "re-admission keeps the retained slots"
    );
    drop(session);
}

/// H-2. A multi-process capture started a whole new session — every link
/// detached, the plan rebuilt, BPF reloaded and reattached — whenever any
/// retained view went stale during the seconds-long load and attach, once per
/// ambient exit and with no bound, and the dropped session's loss counters went
/// with it. It now starts once and retires the stale view live, like any
/// member that ends mid-capture: a provable exit is an expected removal (no
/// loss); anything else defers with a partial mark until a later pass
/// proves it, never recorded as loss without positive evidence of change.
#[test]
fn multi_process_start_retires_views_that_went_stale_during_attach_live() {
    let child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let exiting = std::cell::RefCell::new(ChildReaper(child));
    let exiting_pid = exiting.borrow().0.id();
    let views = vec![
        ProcessView::open(ProcessViewId(0), exiting_pid).unwrap(),
        crate::process::unprovable_process_view_for_test(ProcessViewId(1), std::process::id())
            .unwrap(),
        ProcessView::open(ProcessViewId(2), std::process::id()).unwrap(),
    ];
    let (exited, unprovable, kept) = (views[0].id(), views[1].id(), views[2].id());
    let mut discovered = lifecycle_discovered(views);
    discovered.scope = Scope::System;
    let checks = Cell::new(0usize);
    let starts = Cell::new(0usize);
    let log = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
    let session = start_retained_with(
        &mut discovered,
        false,
        |views| {
            checks.set(checks.get() + 1);
            if checks.get() == 1 {
                // Nothing is stale yet when the session starts.
                return Vec::new();
            }
            if checks.get() == 2 {
                let mut exiting = exiting.borrow_mut();
                exiting.0.kill().unwrap();
                exiting.0.wait().unwrap();
            }
            crate::process::stale_view_ids(views)
        },
        |_, _| {
            starts.set(starts.get() + 1);
            log.borrow_mut().push("start");
            Ok(FakeSession(std::rc::Rc::clone(&log)))
        },
    )
    .expect("an ambient exit during attach never fails a multi-process start");

    assert_eq!(starts.get(), 1, "one session, never restarted");
    assert_eq!(*log.borrow(), ["start"], "the session was not torn down");
    assert_eq!(
        discovered.views.len(),
        3,
        "stale views retire live, not here"
    );
    assert_eq!(
        discovered.retirement_intents.get(&exited),
        Some(&RetirementCause::ExpectedRemoval),
        "a provable exit is the process ending"
    );
    // E17 midfinal correction: a generation whose state cannot be proven
    // is deferred with a partial mark, never recorded as loss — there is
    // no positive evidence anything changed, and the live pass re-checks.
    assert!(
        !discovered.retirement_intents.contains_key(&unprovable),
        "an unprovable generation records no intent: {:?}",
        discovered.retirement_intents
    );
    assert!(!discovered.retirement_intents.contains_key(&kept));
    assert!(
        discovered
            .counters
            .object_skips
            .iter()
            .any(|skip| skip.subject == "live discovery generation"
                && skip.reason.contains("contradicted or unprovable")),
        "the unprovable generation's deferral is published: {:?}",
        discovered.counters.object_skips
    );

    // The startup record pass retires them like any live retirement.
    let mut collect: Box<DiscoveryCollector<'_>> = Box::new(Engine::collect_discovery_records);
    discovered
        .process_discovery_records(
            &mut ScriptedSession::default(),
            &mut Vec::new(),
            &mut PendingViewRetirements::new(),
            &mut true,
            &mut *collect,
            &mut PauseClosure::new(true),
        )
        .unwrap();
    assert!(discovered.retirement_intents.is_empty());
    assert!(discovered.pending_retirements.is_empty());
    assert!(
        discovered.views.iter().all(|view| view.id() != exited),
        "the exited view is gone"
    );
    assert!(discovered.views.iter().any(|view| view.id() == kept));
    drop(session);
}

/// Mutation caught: retaining only the initial `Agreed` outcome drops the
/// manifest's valid offsets when its sole agreeing scan owner is retired.
#[test]
fn stale_sole_owner_agreement_falls_back_to_the_retained_manifest() {
    let fixture = ScanManifestFixture::new();
    let (view, modules, pins, input) = same_object_scan_and_manifest(&fixture, 0x40);
    let stale = view.id();
    let mut discovered = discovered_from_inputs(vec![view], modules, pins, vec![input]);
    assert_eq!(discovered.plan.slots.len(), 1);
    assert_eq!(discovered.plan.modules[0].source, "scan+manifest");
    assert!(
        discovered.plan.slots[0].semantic_authorized,
        "an agreed explicit manifest remains an exact plan claim"
    );
    assert_eq!(
        discovered.plan.slots[0].semantics,
        crate::kinds::descriptor("C_Sign").unwrap()
    );
    assert_eq!(discovered.plan.entries_seen, 1);

    remove_stale_views(&mut discovered, &[stale]).unwrap();

    assert_eq!(discovered.plan.slots.len(), 1);
    assert_eq!(discovered.plan.slots[0].names, ["C_Sign"]);
    assert_eq!(discovered.plan.slots[0].file_offset, 0x40);
    assert!(discovered.plan.slots[0].semantic_authorized);
    assert_eq!(discovered.plan.modules[0].source, "manifest");
    assert_eq!(discovered.counters.uncorroborated, 1);
    assert_eq!(discovered.identity_mismatches, 0);
}

/// Mutation caught: a stale path-matching view's mismatch must not remain
/// latched and abort the rebuild after that view's scan slot is subtracted.
#[test]
fn stale_only_identity_mismatch_becomes_manifest_fallback_for_stable_scope() {
    let dir = tempfile::tempdir().unwrap();
    let provider = dir.path().join("provider.so");
    std::fs::copy("/bin/sh", &provider).unwrap();
    let path = provider.display().to_string();
    let own = pin_as_manifest_object(&path);
    let old_sha = own.pinned().next().unwrap().sha256.to_string();
    let manifest = manifest_naming(&path, Some(old_sha));

    let replacement = dir.path().join("replacement.so");
    std::fs::copy("/bin/true", &replacement).unwrap();
    std::fs::rename(&replacement, &provider).unwrap();
    let file = p11scope_manifest::identity::open_object(&provider).unwrap();
    let mapping = p11scope_manifest::identity::mapping_file_key(&file).unwrap();
    let key = ObjectKey {
        device: p11scope_manifest::maps::Device {
            major: mapping.device_major,
            minor: mapping.device_minor,
        },
        inode: mapping.inode,
    };
    let module = ScannedModule {
        module_hint: None,
        mapped_identity: None,
        double_loaded: false,
        same_file_loads: 1,
        pre_copy_up: None,
        view: ProcessViewId(0),
        mount_namespace: current_mount_namespace(),
        key,
        path: path.clone(),
        tables_scan_finished: false,
        decoder_abi: Some(ElfAbi::Lp64),
        exports: vec!["C_GetFunctionList".into()],
        tables: vec![ScannedTable {
            version: (2, 40),
            walk: "full",
            entries: vec![ScannedEntry {
                name: "C_Sign",
                object: key,
                object_path: path.clone(),
                file_offset: 0x80,
            }],
            null_entries: vec![],
            unpinned: vec![],
            address: 0x7000,
            file_offset: Some(0),
            live_return: false,
            manifest_supported: false,
            extension_impossible: false,
        }],
        interfaces: vec![],
    };
    let (scan_pins, skipped) = pin_scanned_objects(
        std::process::id(),
        std::slice::from_ref(&module),
        &mut CaptureWorkBudget::default(),
    )
    .unwrap();
    assert!(skipped.is_empty(), "{skipped:?}");
    let stale = ProcessView::open(ProcessViewId(0), std::process::id()).unwrap();
    let stable = ProcessView::open(ProcessViewId(1), std::process::id()).unwrap();
    let stale_id = stale.id();
    let input = ManifestInput {
        path: PathBuf::from("stale-manifest.json"),
        manifest,
        pins: own,
        stale: Vec::new(),
    };
    let mut discovered =
        discovered_from_inputs(vec![stale, stable], vec![module], scan_pins, vec![input]);
    assert_eq!(discovered.identity_mismatches, 1);
    assert_eq!(
        discovered.plan.slots.len(),
        1,
        "the scan initially keeps capture viable"
    );

    remove_stale_views(&mut discovered, &[stale_id]).unwrap();

    assert_eq!(
        discovered.views.len(),
        1,
        "the unrelated stable view remains"
    );
    assert_eq!(discovered.identity_mismatches, 0);
    assert_eq!(discovered.plan.modules[0].source, "manifest");
    assert_eq!(discovered.plan.slots[0].names, ["C_Sign"]);
}

/// Mutation caught: subtracting the only conflicting scan owner must recompute
