    e07_rescan(
        &mut engine,
        &mut session,
        context,
        &mut additions,
        &mut pending,
    );
    assert!(!e07_active_targets(&engine).is_empty());

    drop(provider);
    let outcome = e07_rescan(
        &mut engine,
        &mut session,
        context,
        &mut additions,
        &mut pending,
    );
    assert!(outcome.changed(), "the unmap detaches its targets");
