/// Midfinal round-2 residual, item 1 (P1 remainder): a declined view must
/// not lose selection-derived slots without an accepted removal. The final
/// inventory rebuild drops selection claims/tables when the retained pin
/// reads stale; their sole-owned endpoints then enter `delta.retire`, and
/// the deferral currency exemption would let that reduced candidate commit.
/// The decline decision must survive into the rebuild, so the deferred tick
/// keeps claims, tables, contexts and slots.
#[test]
fn midfinal_res2_declined_inventory_keeps_selection_derived_slots() {
    let (fixture, mut engine, mut session, binding) = attached_selection_route();
    let pid = engine.views[0].pid();
    let view = engine.views[0].id();
    let provider = engine
        .pinned
        .owned_timing_key(binding.object)
        .expect("the binding provider pins a timing key");
    let table = selection_only_table(
        &engine,
        binding,
        0x20,
        &[("C_Initialize", 0x100)],
        Vec::new(),
    );
    let result = SelectionRequest {
        name: SelectionNameClass::ExactStandard,
        version: SelectionVersionClass::V3_0,
        flags: 0,
    };
    let (claims, tables, pending) = engine
        .propose_selection_claim(&binding, provider, &table, &result)
        .expect("the consistent selection claim is proposed");
    let raw_modules = engine
        .modules
        .iter()
        .map(|module| module.scanned.clone())
        .collect();
    let candidate = engine
        .live_candidate_with_selection(engine.pinned.clone(), raw_modules, claims, tables, pending)
        .expect("the selection candidate builds");
    assert!(
        engine
            .apply_candidate(&mut session, candidate, &mut true, false, &[])
            .expect("the selection candidate applies")
            .accepted()
    );
    assert_eq!(
        engine.selection_claims.len(),
        1,
        "precondition: the claim is admitted"
    );
    assert_eq!(
        engine
            .plan
            .slots
            .iter()
            .filter(|slot| slot.file_offset == 0x100 && engine.plan.is_active(slot.index))
            .count(),
        1,
        "precondition: the selection target holds one active slot"
    );
    let claims_before = engine.selection_claims.clone();
    let tables_before = engine.selection_tables.clone();
    let contexts_before = engine.loader_registry.ids_for_view(view);
    assert!(
        !contexts_before.is_empty(),
        "precondition: the attached view owns loader contexts"
    );
    let slots_before = engine.plan.active_slot_count();

    engine.views[0] = crate::process::unprovable_process_view_for_test(view, pid)
        .expect("an unprovable pin over the live child");
    assert!(
        !engine.views[0].still_the_same(),
        "precondition: the pin reads stale while the child lives"
    );
    assert!(
        engine.request_refresh(pid, None),
        "the refresh request is accepted"
    );
    apply_ordinary_batch(&mut engine, &mut session, Vec::new())
        .expect("a deferred inventory tick never fails the capture");
    assert!(
        engine.views.iter().any(|retained| retained.id() == view),
        "the deferred view stays retained"
    );
    assert_eq!(
        engine.selection_claims, claims_before,
        "the deferred view keeps its selection claims without an accepted removal"
    );
    assert_eq!(
        engine.selection_tables, tables_before,
        "the deferred view keeps its selection tables without an accepted removal"
    );
    assert_eq!(
        engine.loader_registry.ids_for_view(view),
        contexts_before,
        "the deferred view keeps its loader contexts"
    );
    assert_eq!(
        engine.plan.active_slot_count(),
        slots_before,
        "the deferred view keeps its slots"
    );
    assert!(
        !engine
            .retirement_intents
            .values()
            .any(|cause| *cause == RetirementCause::GenerationLost),
        "a live generation is never loss: {:?}",
        engine.retirement_intents
    );
    assert!(
        engine
            .counters
            .object_skips
            .iter()
            .any(|skip| skip.subject == "live discovery generation"
                && skip.reason.contains("contradicted or unprovable")),
        "the deferral is marked: {:?}",
        engine.counters.object_skips
    );
    assert!(
        engine.refresh_requested.is_empty(),
        "the serviced request completes instead of sticking: {:?}",
        engine.refresh_requested
    );
    drop(fixture);
}

/// Midfinal round-2 residual, item 1 positive twin: an accepted removal
/// still retires selection-derived coverage through the same inventory
/// path. A proven exit drops the view, its claims, tables, contexts and
/// slots exactly once.
#[test]
fn midfinal_res2_accepted_removal_retires_selection_derived_slots() {
    let (mut fixture, mut engine, mut session, binding) = attached_selection_route();
    let view = engine.views[0].id();
    let provider = engine
        .pinned
        .owned_timing_key(binding.object)
        .expect("the binding provider pins a timing key");
    let table = selection_only_table(
        &engine,
        binding,
        0x20,
        &[("C_Initialize", 0x100)],
        Vec::new(),
    );
    let result = SelectionRequest {
        name: SelectionNameClass::ExactStandard,
        version: SelectionVersionClass::V3_0,
        flags: 0,
    };
    let (claims, tables, pending) = engine
        .propose_selection_claim(&binding, provider, &table, &result)
        .expect("the consistent selection claim is proposed");
    let raw_modules = engine
        .modules
        .iter()
        .map(|module| module.scanned.clone())
        .collect();
    let candidate = engine
        .live_candidate_with_selection(engine.pinned.clone(), raw_modules, claims, tables, pending)
        .expect("the selection candidate builds");
    assert!(
        engine
            .apply_candidate(&mut session, candidate, &mut true, false, &[])
            .expect("the selection candidate applies")
            .accepted()
    );
    assert_eq!(
        engine.selection_claims.len(),
        1,
        "precondition: the claim is admitted"
    );

    fixture.child.kill().expect("kill the child");
    fixture.child.wait().expect("reap the child");
    assert!(
        !engine.views[0].still_the_same(),
        "precondition: the reaped child reads stale"
    );
    apply_ordinary_batch(&mut engine, &mut session, Vec::new())
        .expect("a proven exit after selection ends gracefully");
    assert!(
        engine.expected_target_exit(),
        "the exit finalized: {:?}",
        engine.retirement_intents
    );
    assert!(
        engine.views.iter().all(|retained| retained.id() != view),
        "the exited view is gone"
    );
    assert!(
        engine.selection_claims.is_empty(),
        "the accepted removal retires the selection claims"
    );
    assert!(
        engine.selection_tables.is_empty(),
        "the accepted removal retires the selection tables"
    );
    assert!(
        engine.loader_registry.ids_for_view(view).is_empty(),
        "the exited view released its loader contexts"
    );
    assert_eq!(
        engine.plan.active_slot_count(),
        0,
        "the ended target retired its slots"
    );
    assert!(
        engine.retirement_intents.is_empty(),
        "no retirement stays queued: {:?}",
        engine.retirement_intents
    );
}

/// Midfinal round-2 residual, item 2 (new P2): a declined view must not
/// authorize fresh attachment retries. A previously failed (inactive)
/// endpoint rebuilds as `delta.new`, but the deferral currency exemption
/// must not let it attach without generation revalidation: the retry waits
/// while the retained coverage commits unchanged.
///
/// Round-3 extension (item B): repeated deferral ticks must not leak slot
/// allocations (the allocation count stays stable, not just the active
/// set), and the same engine recovers after withholding — once the
/// generation is proven, the retry attaches with capacity intact.
#[test]
fn midfinal_res2_declined_inventory_withholds_failed_endpoint_retry() {
    let dir = tempfile::tempdir().expect("a fixture directory");
    let first = system_scope_build_fixture(dir.path(), "withhold-retry");
    let driver = system_scope_build_driver(dir.path());
    let mut child_a = system_scope_spawn_loaded(&driver, &first);
    let pid_a = child_a.pid();
    let scope_dir = tempfile::tempdir().expect("a scope directory");
    e06_write_listing(scope_dir.path(), &[pid_a]);
    let scope = crate::scope::cgroup(scope_dir.path()).expect("open scope directory");
    let mut engine = Engine::discover(
        &e06_cgroup_args(scope_dir.path(), vec![first.clone()], Some(16)),
        &scope,
        None,
    )
    .expect("cgroup scope discovers the child");
    let id_a = engine
        .views
        .iter()
        .find(|view| view.pid() == pid_a)
        .expect("the child is admitted")
        .id();
    let module_id = engine
        .plan()
        .modules
        .iter()
        .find(|module| module.path.ends_with("withhold-retry.so"))
        .expect("the plan names the provider")
        .id;
    let retry_key: (crate::discovery::identity::PinnedObjectId, u64) = {
        let slot = engine
            .plan()
            .slots
            .iter()
            .find(|slot| {
                slot.module_ids.as_slice() == [module_id] && engine.plan.is_active(slot.index)
            })
            .expect("the provider holds an active slot");
        (slot.object, slot.file_offset)
    };
    let retry_index = engine
        .plan()
        .slots
        .iter()
        .find(|slot| {
            slot.object == retry_key.0
                && slot.file_offset == retry_key.1
                && engine.plan.is_active(slot.index)
        })
        .expect("the retry target is active")
        .index;
    engine.plan.deactivate(retry_index);
    assert!(
        !engine.plan.is_active(retry_index),
        "precondition: the failed endpoint is inactive"
    );
    let active_before = engine.plan.active_slot_count();
    let alloc_before = engine.plan.slots.len();
    let contexts_before = engine.loader_registry.ids_for_view(id_a);
    let position = engine
        .views
        .iter()
        .position(|view| view.id() == id_a)
        .expect("the child's retained position");
    engine.views[position] = crate::process::unprovable_process_view_for_test(id_a, pid_a)
        .expect("an unprovable pin over the live child");
    assert!(
        !engine.views[position].still_the_same(),
        "precondition: the pin reads stale while the child lives"
    );
    assert!(
        engine.request_refresh(pid_a, None),
        "the refresh request is accepted"
    );

    let mut session = ScriptedSession::with_records([], 0);
    let mut collect: Box<DiscoveryCollector<'_>> = Box::new(Engine::collect_discovery_records);
    let mut tick_now = crate::attach::monotonic_ns;
    let mut run_tick = |engine: &mut Engine, session: &mut ScriptedSession| {
        engine.refresh_inventory(
            session,
            &mut true,
            &mut Vec::new(),
            &mut PendingViewRetirements::new(),
            &mut *collect,
            &mut PauseClosure::new(true),
            &mut tick_now,
        )
    };
    run_tick(&mut engine, &mut session).expect("the deferring tick applies");
    assert!(
        engine
            .counters
            .object_skips
            .iter()
            .any(|skip| skip.subject == "live discovery generation"
                && skip.reason.contains("contradicted or unprovable")),
        "the deferral is marked: {:?}",
        engine.counters.object_skips
    );
    assert!(
        engine.views.iter().any(|retained| retained.id() == id_a),
        "the deferred view stays retained"
    );
    assert!(
        engine
            .plan
            .slots
            .iter()
            .filter(|slot| {
                slot.object == retry_key.0
                    && slot.file_offset == retry_key.1
                    && engine.plan.is_active(slot.index)
            })
            .count()
            == 0,
        "the declined view's failed endpoint does not reattach without a proven generation"
    );
    assert_eq!(
        engine.plan.active_slot_count(),
        active_before,
        "the retained coverage commits unchanged"
    );
    assert_eq!(
        engine.plan.slots.len(),
        alloc_before,
        "the withheld retry releases its cell instead of consuming lifetime capacity"
    );
    assert_eq!(
        engine.loader_registry.ids_for_view(id_a),
        contexts_before,
        "the deferred view keeps its loader contexts"
    );
    for tick in 2..=3 {
        assert!(
            engine.request_refresh(pid_a, None),
            "tick {tick}: the refresh request is accepted"
        );
        run_tick(&mut engine, &mut session)
            .unwrap_or_else(|error| panic!("tick {tick}: the deferring tick applies: {error:?}"));
        assert!(
            engine
                .plan
                .slots
                .iter()
                .filter(|slot| {
                    slot.object == retry_key.0
                        && slot.file_offset == retry_key.1
                        && engine.plan.is_active(slot.index)
                })
                .count()
                == 0,
            "tick {tick}: the retry keeps waiting while the generation stays unproven"
        );
        assert_eq!(
            engine.plan.active_slot_count(),
            active_before,
            "tick {tick}: the retained coverage commits unchanged"
        );
        assert_eq!(
            engine.plan.slots.len(),
            alloc_before,
            "tick {tick}: repeated deferral ticks hold the allocation count stable"
        );
    }
    let position = engine
        .views
        .iter()
        .position(|view| view.id() == id_a)
        .expect("the deferred view's retained position");
    engine.views[position] =
        ProcessView::open(id_a, pid_a).expect("a proven pin over the live child");
    assert!(
        engine.views[position].still_the_same(),
        "the healed generation reads current"
    );
    assert!(
        engine.request_refresh(pid_a, None),
        "the recovery refresh request is accepted"
    );
    run_tick(&mut engine, &mut session).expect("the recovery tick applies");
    assert!(
        engine.views.iter().any(|retained| retained.id() == id_a),
        "the proven view stays retained"
    );
    assert_eq!(
        engine
            .plan
            .slots
            .iter()
            .filter(|slot| {
                slot.object == retry_key.0
                    && slot.file_offset == retry_key.1
                    && engine.plan.is_active(slot.index)
            })
            .count(),
        1,
        "withholding recovers: the proven generation reattaches its failed endpoint"
    );
    assert_eq!(
        engine.plan.slots.len(),
        alloc_before + 1,
        "the recovered retry consumes exactly one cell for one attached endpoint"
    );
    child_a.reap().expect("reap the child");
}

