#[test]
fn collected_finish_nonempty_retirement_waits_for_original_native_verdict() {
    for fail_return in [false, true] {
        let mut case = CollectedFinishGraphCase::new(fail_return);
        case.child.reap().unwrap();
        assert_eq!(case.engine.views[0].original_exited(), Ok(true));
        case.engine.update_counter_snapshot(&case.session).unwrap();
        case.engine.dispatch_lifecycle_record(
            &mut case.session,
            &collected_finish_leader_exit(case.child.pid()),
            &mut PendingViewRetirements::new(),
        );
        assert!(case.engine.pending_leader_exit_views.contains(&case.view));
        let plan = case.engine.plan.clone();
        let pins = case.engine.pinned.revision();
        let reads = case.session.counter_reads();
        let zero = case.service(0);
        assert!(zero.pending && !zero.progressed);
        assert_eq!(case.session.counter_reads(), reads);
        assert_eq!(case.engine.plan, plan);
        assert_eq!(case.engine.pinned.revision(), pins);
        assert_eq!(
            case.session
                .global_retirement
                .as_ref()
                .unwrap()
                .borrow()
                .begins,
            0
        );
        case.assert_original_pending();
        case.reach_native_handoff();
        assert!(case.engine.pending_retirements.contains(&case.view));
        case.release();
        case.returned
            .recv_timeout(std::time::Duration::from_secs(2))
            .unwrap();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        loop {
            let progress = case.service(1);
            let refused = case.engine.counters.object_skips.iter().any(|skip| {
                skip.subject == "global native retirement"
                    && skip.reason == "original static ownership remains uncertain; replacement admission is blocked"
            });
            if fail_return && refused {
                assert!(progress.pending);
                assert!(case.engine.pending_retirements.contains(&case.view));
                case.assert_original_pending();
                for _ in 0..4 {
                    assert!(case.service(1).pending);
                    case.assert_original_pending();
                }
                break;
            }
            if !fail_return && !progress.pending {
                assert!(
                    !case
                        .session
                        .global_retirement
                        .as_ref()
                        .unwrap()
                        .borrow()
                        .blocking()
                );
                assert!(!case.engine.pending_retirements.contains(&case.view));
                assert!(
                    case.engine
                        .views
                        .iter()
                        .all(|owner| owner.id() != case.view)
                );
                assert!(
                    case.engine
                        .modules
                        .iter()
                        .all(|module| module.scanned.view != case.view)
                );
                assert!(case.engine.pinned.view_claims(case.view).is_none());
                assert!(!case.engine.plan.is_active(case.original_slot.index));
                assert_eq!(
                    case.engine.plan.module_of_slot(case.original_slot.index),
                    Some(case.original_owner)
                );
                assert_eq!(case.engine.plan.slots.len(), 1);
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "actual native verdict did not resolve the retained graph"
            );
            std::thread::yield_now();
        }
        let begins = case
            .session
            .global_retirement
            .as_ref()
            .unwrap()
            .borrow()
            .begins;
        assert_eq!(begins, 1);
        assert_eq!(case.engine.deep_scans, 0);
        assert!(
            case.session.attached_slots.is_empty() && case.session.dynamic_attach_calls.is_empty()
        );
        if !fail_return {
            let quiet = case.service(1);
            assert!(!quiet.pending && !quiet.progressed);
            assert_eq!(
                case.session
                    .global_retirement
                    .as_ref()
                    .unwrap()
                    .borrow()
                    .begins,
                begins
            );
        }
    }
}

#[test]
fn collected_finish_nonempty_rejection_keeps_actual_collision_until_disposition() {
    use crate::discovery::identity::test_fixture::real_scan_pin;

    let mut case = CollectedFinishGraphCase::new(false);
    let object = case.original_slot.object;
    let summary = case.engine.pinned.summary(object).unwrap();
    let key = summary.key;
    let sha256 = summary.sha256.to_string();
    let dir = tempfile::tempdir().unwrap();
    let peer = dir.path().join("different-kernel-file.so");
    std::fs::copy(case.engine.pinned.attach_path_for(object).unwrap(), &peer).unwrap();
    // Existing identity fixture: a controlled raw mapping key names a second
    // real opened file. The full same-kernel-file test must reject this actual
    // collision even though the copied bytes/digest agree. Neither file changes.
    let conflicting = real_scan_pin(&peer, Some(key), 991, &sha256);
    let peer_id = conflicting.pinned().next().unwrap().id;
    assert!(!conflicting.exactly_matches(peer_id, &case.engine.pinned, object));
    assert_eq!(case.engine.pinned.check_unchanged(), Ok(true));
    let mut pins = case.engine.pinned.clone();
    let skipped = pins.absorb(conflicting);
    assert!(pins.rejects(key) && !skipped.is_empty());
    let raw = case
        .engine
        .modules
        .iter()
        .map(|module| module.scanned.clone())
        .collect();
    let candidate = case.engine.live_candidate(pins, raw, skipped).unwrap();
    assert_eq!(candidate.delta.retire.len(), 1);
    assert!(candidate.delta.new.is_empty() && candidate.delta.replace.is_empty());
    // A real native preflight refusal leaves the previously accepted graph in
    // place; the Engine itself retains the collision that the candidate proved.
    case.session.refuse_preflights([true]);
    let outcome = case
        .engine
        .apply_candidate(&mut case.session, candidate, &mut false, false, &[])
        .unwrap();
    assert!(!outcome.accepted() && outcome.retains_intent());
    assert!(outcome.newly_rejected_keys.contains(&key));
    assert!(!case.session.preflight_targets.borrow().is_empty());
    case.engine
        .queue_apply_outcome(&outcome, &mut PendingViewRetirements::new());
    assert!(case.engine.pending_rejected_keys.contains(&key));
    assert!(case.engine.plan.is_active(case.original_slot.index));
    case.assert_original_pending();
    assert_eq!(
        case.session
            .global_retirement
            .as_ref()
            .unwrap()
            .borrow()
            .begins,
        0
    );
    assert!(
        case.session
            .global_retirement
            .as_ref()
            .unwrap()
            .borrow()
            .has_slot_link(case.original_slot.index)
    );
    let reads = case.session.counter_reads();
    let facts = case.engine.facts_revision;
    let revision = case.engine.pinned.revision();
    let zero = case.service(0);
    assert!(zero.pending && !zero.progressed);
    assert_eq!(case.session.counter_reads(), reads);
    assert_eq!(case.engine.facts_revision, facts);
    assert_eq!(case.engine.pinned.revision(), revision);
    assert!(case.engine.pending_rejected_keys.contains(&key));
    case.session.refuse_preflights([]);

    case.reach_native_handoff();
    assert!(case.engine.pending_rejected_keys.contains(&key));
    assert!(
        !case.engine.pinned.rejects(key),
        "the old canonical graph remains held before native settlement"
    );
    case.release();
    case.returned
        .recv_timeout(std::time::Duration::from_secs(2))
        .unwrap();
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
    loop {
        let progress = case.service(1);
        if !progress.pending {
            break;
        }
        assert!(
            std::time::Instant::now() < deadline,
            "the original collision needs a real terminal disposition"
        );
        std::thread::yield_now();
    }
    assert!(case.engine.pending_rejected_keys.is_empty());
    assert!(
        case.engine.pinned.rejects(key),
        "the actual collision stays irreversibly rejected"
    );
    assert!(!case.engine.plan.is_active(case.original_slot.index));
    assert_eq!(
        case.engine.plan.module_of_slot(case.original_slot.index),
        Some(case.original_owner)
    );
    assert_eq!(case.engine.plan.slots.len(), 1);
    assert!(case.engine.views.iter().any(|owner| {
        owner.id() == case.view && owner.view_admission().same_allocation(&case.admission)
    }));
    assert_eq!(case.engine.deep_scans, 0);
    assert!(case.session.attached_slots.is_empty() && case.session.dynamic_attach_calls.is_empty());
    assert!(case.session.replaced_slot_indices.is_empty());
    assert_eq!(
        case.session
            .global_retirement
            .as_ref()
            .unwrap()
            .borrow()
            .begins,
        1
    );
    assert_eq!(
        case.session
            .global_retirement
            .as_ref()
            .unwrap()
            .borrow()
            .released(),
        2
    );
    let quiet = case.service(1);
    assert!(!quiet.pending && !quiet.progressed);
    assert_eq!(
        case.session
            .global_retirement
            .as_ref()
            .unwrap()
            .borrow()
            .begins,
        1
    );
    assert_eq!(
        case.session
            .global_retirement
            .as_ref()
            .unwrap()
            .borrow()
            .released(),
        2
    );
}

/// Two live views, each with one accepted provider over a distinct object.
///
/// Builds on [`engine_with_one_accepted_provider`] (one view, slot 0) and adds
/// a second view by the same open → snapshot → pin → candidate → apply
/// pattern, accepting the peer object as slot 1. Both children stay alive for
/// the test; dropping the guard kills and reaps them.
struct TwoViewProviderEngine {
    _first: SystemScopeChildGuard,
    _second: SystemScopeChildGuard,
    engine: Engine,
}

impl TwoViewProviderEngine {
    fn new() -> Self {
        let (child, mut engine, first) = engine_with_one_accepted_provider();
        let first_guard = SystemScopeChildGuard::new(child);
        let child = std::process::Command::new("sleep")
            .arg("30")
            .die_with_parent()
            .spawn()
            .unwrap();
        let view = ProcessView::open(ProcessViewId(4), child.id()).unwrap();
        let second = child_provider_modules(&view);
        engine.views.push(view);
        engine.next_view_id = 5;
        // The peer object is distinct from the accepted one by construction of
        // `snapshot_two_provider_modules` (distinct `ObjectKey`s).
        assert_ne!(second[1].key, first[0].key);
        let mut pins = engine.pinned.clone();
        let skipped = pins.absorb(pin_test_modules(&engine.views[1], &second[1..2]));
        let candidate = engine
            .live_candidate(pins, vec![first[0].clone(), second[1].clone()], skipped)
            .unwrap();
        assert_eq!(
            candidate.delta.new.len(),
            1,
            "only the second view's provider is newly allocated"
        );
        assert_eq!(candidate.plan.slots.len(), 2);
        let mut session = ScriptedSession::default();
        let mut additions = true;
        let outcome = engine
            .apply_candidate(&mut session, candidate, &mut additions, false, &[])
            .unwrap();
        assert!(outcome.accepted(), "the second candidate is accepted whole");
        assert_eq!(engine.views.len(), 2);
        assert_eq!(engine.plan.slots.len(), 2);
        assert_eq!(engine.modules.len(), 2);
        assert!(engine.plan.modules_skipped.is_empty());
        Self {
            _first: first_guard,
            _second: SystemScopeChildGuard::new(child),
            engine,
        }
    }
}

/// Drives a plan cursor to its terminal state one `work`-sized credit at a
/// time. Returns `Ready` or the refusal; panics on `Yielded` (a positive
/// credit must advance or finish) and on non-termination.
fn drive_plan_cursor_to_terminal<'a>(
    old: &plan::AttachPlan,
    make_sources: &dyn Fn() -> crate::plan::ConservativePlanSources<'a>,
    stable: &mut dyn FnMut(PinnedObjectId) -> Option<plan::ModuleId>,
    cursor: &mut crate::plan::ConservativePlanCursor,
    reserve: &crate::semantics_edge::resources::SemanticResourceReserver,
    work: usize,
) -> Result<crate::discovery::identity::GraphStep, crate::discovery::identity::GraphRefusal> {
    use crate::discovery::identity::GraphStep;
    for _ in 0..100_000 {
        let sources = make_sources();
        match old.poll_conservative_rebuild(sources, stable, cursor, reserve, work)? {
            GraphStep::Ready => return Ok(GraphStep::Ready),
            GraphStep::Advanced => {}
            GraphStep::Yielded => panic!("a work-{work} credit must advance or finish"),
        }
    }
    panic!("the plan cursor did not converge within 100_000 credits");
}

#[test]
fn collected_plan_cursor_matches_removal_only_reference() {
    use crate::discovery::identity::{GraphRefusal, GraphStep};
    use crate::plan::{ConservativePlanCursor, ConservativePlanSources};
    use crate::semantics_edge::resources::{SEMANTIC_TRANSITION_SCRATCH, SemanticResourcePool};

    let mut two = TwoViewProviderEngine::new();
    let engine = &mut two.engine;
    let retired_view = engine.views[0].id();
    let surviving: Vec<ReconciledModule> = engine
        .modules
        .iter()
        .filter(|module| module.scanned.view != retired_view)
        .cloned()
        .collect();
    assert_eq!(surviving.len(), 1);

    // The removal-only oracle: rebuild from the surviving sources, bind stable
    // IDs, extend the old plan.
    let old = engine.plan.clone();
    let mut rebuilt = old.rebuild_from_sources_broad(
        &surviving,
        &engine.manifests,
        &engine.pinned,
        engine.broad_admit,
    );
    engine
        .capture_facts
        .bind_plan_module_ids(&mut rebuilt, &surviving, &engine.manifests, &engine.pinned)
        .unwrap();
    let mut next = old.clone();
    let delta = next.extend_exact_with_stable_module_ids(rebuilt).unwrap();
    assert!(delta.new.is_empty(), "the reference must not grow");
    assert!(delta.replace.is_empty(), "the reference must not replace");
    assert_eq!(delta.retire.len(), 1, "the reference retires one slot");

    let pool = SemanticResourcePool::default();
    let reserve = pool.reserver();
    let pinned = &engine.pinned;
    let facts = &engine.capture_facts;
    let manifests = &engine.manifests;
    let broad_admit = engine.broad_admit;
    let make_sources = || ConservativePlanSources::new(&surviving, manifests, pinned, broad_admit);
    let mut stable = |object: PinnedObjectId| facts.module_id_for_object(pinned, object).ok();

    // Work 0 changes nothing.
    let mut cursor = ConservativePlanCursor::new();
    let idle = old
        .poll_conservative_rebuild(make_sources(), &mut stable, &mut cursor, &reserve, 0)
        .unwrap();
    assert_eq!(idle, GraphStep::Yielded);
    assert!(cursor.plan().is_none());
    assert!(cursor.delta().is_none());
    assert!(cursor.removed().is_none());
    assert!(cursor.required_bytes().is_none());

    // One credit at a time to Ready; the output equals the oracle field for
    // field.
    drive_plan_cursor_to_terminal(&old, &make_sources, &mut stable, &mut cursor, &reserve, 1)
        .unwrap();
    let plan = cursor
        .plan()
        .expect("a Ready cursor holds the rebuilt plan");
    let cursor_delta = cursor.delta().expect("a Ready cursor holds the delta");
    let removed = cursor.removed().expect("a Ready cursor holds the removals");
    assert_eq!(plan.slots, next.slots);
    assert_eq!(plan.modules, next.modules);
    assert_eq!(plan.skipped, next.skipped);
    assert_eq!(plan.modules_skipped, next.modules_skipped);
    assert_eq!(plan.surfaces, next.surfaces);
    assert_eq!(
        plan, &next,
        "private plan state (slot index, retirements, aggregate owners) matches"
    );
    assert_eq!(cursor_delta.new, delta.new);
    assert_eq!(cursor_delta.replace, delta.replace);
    assert_eq!(cursor_delta.retire, delta.retire);
    let mut retired: Vec<u32> = delta.retire.iter().map(|slot| slot.index).collect();
    retired.sort();
    assert_eq!(removed, retired.as_slice());

    // Payment: exact fit reaches Ready; one byte short refuses with no output.
    let required = cursor
        .required_bytes()
        .expect("a Ready cursor measured its cost");
    assert!(required > 0);
    let fit = SemanticResourcePool::default();
    fit.reference_set_limit(SEMANTIC_TRANSITION_SCRATCH + required);
    let mut fit_cursor = ConservativePlanCursor::new();
    drive_plan_cursor_to_terminal(
        &old,
        &make_sources,
        &mut stable,
        &mut fit_cursor,
        &fit.reserver(),
        1,
    )
    .unwrap();
    assert!(fit_cursor.plan().is_some());
    let short = SemanticResourcePool::default();
    short.reference_set_limit(SEMANTIC_TRANSITION_SCRATCH + required - 1);
    let short_reserve = short.reserver();
    let mut short_cursor = ConservativePlanCursor::new();
    let mut steps = 0;
    let refusal = loop {
        steps += 1;
        assert!(steps < 100_000, "a one-short pool must refuse promptly");
        match old.poll_conservative_rebuild(
            make_sources(),
            &mut stable,
            &mut short_cursor,
            &short_reserve,
            1,
        ) {
            Ok(GraphStep::Ready) => panic!("a one-short pool must refuse"),
            Ok(_) => {}
            Err(refusal) => break refusal,
        }
    };
    assert!(matches!(refusal, GraphRefusal::Storage(_)));
    assert!(short_cursor.plan().is_none());
}

#[test]
fn collected_plan_cursor_never_grows_at_q() {
    use crate::plan::{ConservativePlanCursor, ConservativePlanSources};
    use crate::semantics_edge::resources::SemanticResourcePool;

    let mut two = TwoViewProviderEngine::new();
    let engine = &mut two.engine;
    // An extra module over a fresh key: the first module re-decoded at a new
    // offset, so the reference rebuild genuinely grows.
    let mut grown = engine.modules.clone();
    let mut extra = grown[0].clone();
    extra.scanned.tables[0].entries[0].file_offset = 0x2000;
    assert!(
        !engine
            .plan
            .slots
            .iter()
            .any(|slot| slot.object == extra.object && slot.file_offset == 0x2000)
    );
    grown.push(extra);

    let mut old = engine.plan.clone();
    // Non-vacuity probe: an unattributed historical refusal the cursor must
    // keep while refusing growth.
    old.modules_skipped.push(crate::plan::Skipped {
        subject: "/refused-provider.so".into(),
        reason: "historical refusal kept without growth".into(),
    });
    let mut rebuilt = old.rebuild_from_sources_broad(
        &grown,
        &engine.manifests,
        &engine.pinned,
        engine.broad_admit,
    );
    engine
        .capture_facts
        .bind_plan_module_ids(&mut rebuilt, &grown, &engine.manifests, &engine.pinned)
        .unwrap();
    let mut next = old.clone();
    let delta = next.extend_exact_with_stable_module_ids(rebuilt).unwrap();
    assert_eq!(delta.new.len(), 1, "the grown reference must add one slot");
    assert!(delta.retire.is_empty());

    let pool = SemanticResourcePool::default();
    let reserve = pool.reserver();
    let pinned = &engine.pinned;
    let facts = &engine.capture_facts;
    let manifests = &engine.manifests;
    let broad_admit = engine.broad_admit;
    let make_sources = || ConservativePlanSources::new(&grown, manifests, pinned, broad_admit);
    let mut stable = |object: PinnedObjectId| facts.module_id_for_object(pinned, object).ok();
    let mut cursor = ConservativePlanCursor::new();
    drive_plan_cursor_to_terminal(&old, &make_sources, &mut stable, &mut cursor, &reserve, 1)
        .unwrap();
    let plan = cursor
        .plan()
        .expect("a Ready cursor holds the rebuilt plan");
    let cursor_delta = cursor.delta().expect("a Ready cursor holds the delta");
    assert!(
        cursor_delta.new.is_empty(),
        "no growth at Q: the delta adds nothing"
    );
    assert!(
        cursor_delta.replace.is_empty(),
        "no growth at Q: the delta replaces nothing"
    );
    assert_eq!(plan.modules_skipped, old.modules_skipped);
    assert_eq!(plan.slots, old.slots);
    assert_eq!(plan.modules, old.modules);
    let refused: Vec<(PinnedObjectId, &crate::plan::Skipped)> = plan.refused_modules().collect();
    let old_refused: Vec<(PinnedObjectId, &crate::plan::Skipped)> = old.refused_modules().collect();
    assert_eq!(refused, old_refused);
    for slot in &old.slots {
        assert_eq!(
            plan.module_of_slot(slot.index),
            old.module_of_slot(slot.index)
        );
    }
    assert!(cursor.removed().unwrap().is_empty());
}

#[test]
fn collected_plan_cursor_refuses_in_place_mutation_and_missing_ids() {
    use crate::discovery::identity::{GraphRefusal, GraphStep};
    use crate::plan::{ConservativePlanCursor, ConservativePlanSources};
    use crate::semantics_edge::resources::SemanticResourcePool;

    let mut two = TwoViewProviderEngine::new();
    let engine = &mut two.engine;
    let retired_view = engine.views[0].id();
    let surviving: Vec<ReconciledModule> = engine
        .modules
        .iter()
        .filter(|module| module.scanned.view != retired_view)
        .cloned()
        .collect();
    assert_eq!(surviving.len(), 1);

    let pool = SemanticResourcePool::default();
    let reserve = pool.reserver();
    let pinned = &engine.pinned;
    let facts = &engine.capture_facts;
    let manifests = &engine.manifests;
    let broad_admit = engine.broad_admit;
    let make_sources = || ConservativePlanSources::new(&surviving, manifests, pinned, broad_admit);
    let mut stable = |object: PinnedObjectId| facts.module_id_for_object(pinned, object).ok();

    // In-place mutation between credits.
    let mut cursor = ConservativePlanCursor::new();
    let first = engine
        .plan
        .poll_conservative_rebuild(make_sources(), &mut stable, &mut cursor, &reserve, 1)
        .unwrap();
    assert_eq!(first, GraphStep::Advanced);
    let slot0 = engine.plan.slots[0].index;
    engine.plan.deactivate(slot0);
    let err = engine
        .plan
        .poll_conservative_rebuild(make_sources(), &mut stable, &mut cursor, &reserve, 1)
        .unwrap_err();
    assert!(matches!(err, GraphRefusal::SourceChanged));

    // Whole-plan replacement between credits.
    let mut cursor = ConservativePlanCursor::new();
    let first = engine
        .plan
        .poll_conservative_rebuild(make_sources(), &mut stable, &mut cursor, &reserve, 1)
        .unwrap();
    assert_eq!(first, GraphStep::Advanced);
    engine.plan = engine.plan.clone();
    let err = engine
        .plan
        .poll_conservative_rebuild(make_sources(), &mut stable, &mut cursor, &reserve, 1)
        .unwrap_err();
    assert!(matches!(err, GraphRefusal::SourceChanged));

    // An object with no module ID.
    let mut cursor = ConservativePlanCursor::new();
    let mut no_ids = |_: PinnedObjectId| None;
    let terminal = drive_plan_cursor_to_terminal(
        &engine.plan,
        &make_sources,
        &mut no_ids,
        &mut cursor,
        &reserve,
        1,
    );
    assert!(matches!(terminal, Err(GraphRefusal::Identity)));

    // A poisoned token is refused at the first credit.
    engine.plan.poison_token_for_test();
    let mut cursor = ConservativePlanCursor::new();
    let err = engine
        .plan
        .poll_conservative_rebuild(make_sources(), &mut stable, &mut cursor, &reserve, 1)
        .unwrap_err();
    assert!(matches!(err, GraphRefusal::SourceChanged));
}

/// T4 helper (G23): `count` accepted providers, generalizing
/// `engine_with_one_accepted_provider`. Each child is accepted under its own
/// PID scope exactly like the single helper; the engine ends in System scope.
fn engine_with_accepted_providers(count: usize) -> (Vec<SystemScopeChildGuard>, Engine) {
    let mut guards = Vec::new();
    let mut engine = Engine::empty();
    for index in 0..count {
        let child = std::process::Command::new("sleep")
            .arg("30")
            .die_with_parent()
            .spawn()
            .unwrap();
        engine.scope = Scope::Pid(child.id());
        let view = ProcessView::open(ProcessViewId(3 + index as u32), child.id()).unwrap();
        let modules = child_provider_modules(&view);
        engine.views.push(view);
        let pins = pin_test_modules(&engine.views[index], &modules[..1]);
        let candidate = engine
            .live_candidate(pins, vec![modules[0].clone()], Vec::new())
            .unwrap();
        let mut session = ScriptedSession::default();
        let mut additions = true;
        let outcome = engine
            .apply_candidate(&mut session, candidate, &mut additions, false, &[])
            .unwrap();
        assert!(outcome.accepted(), "provider {index} is accepted whole");
        guards.push(SystemScopeChildGuard::new(child));
    }
    engine.next_view_id = engine.next_view_id.max(3 + count as u32);
    engine.scope = Scope::System;
    assert_eq!(engine.views.len(), count);
    (guards, engine)
}

#[test]
fn collected_graph_barrier_fences_records_and_assessments() {
    // First half: a live graph fences a queued record and a pending
    // assessment; both advance in original order after Done.
    let (child, mut engine, _) = engine_with_one_accepted_provider();
    let _accepted = SystemScopeChildGuard::new(child);
    engine.scope = Scope::System;
    let view = engine.views[0].id();
    let mut session = ScriptedSession::default();
    // T4b real native transfer needs a carrier: without one the graph
    // refuses before mutation and stays pending per §1.9 (it only
    // reached Done under T4's vacuous advance). Setup only; every
    // assertion below is unchanged.
    let (_entered, _returned) = attach_nonblocking_native_carrier(&engine, &mut session);
    assert!(
        engine
            .retirement_intents
            .insert(view, RetirementCause::ExpectedRemoval)
            .is_none()
    );
    assert!(engine.ready_expected_removals.insert(view));
    // Credit 1: the named intent requests the graph.
    let first = engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(first.pending);
    assert!(engine.collected_graph_requested);
    assert_eq!(engine.collected_graphs_created, 0);
    // Drive until the graph reaches Pins.
    for _ in 0..8 {
        if engine
            .collected_graph
            .as_ref()
            .is_some_and(|graph| graph.phase == GraphPhase::Pins)
        {
            break;
        }
        engine
            .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
            .unwrap();
    }
    assert!(
        engine
            .collected_graph
            .as_ref()
            .is_some_and(|graph| graph.phase == GraphPhase::Pins),
        "the graph must reach Pins"
    );
    assert_eq!(engine.collected_graphs_created, 1);
    // Two unnamed views: W's exit is already a pending assessment, U's exit
    // arrives as a record while the graph lives.
    let w_child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let u_child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let w = ProcessView::open(ProcessViewId(4), w_child.id()).unwrap();
    let u = ProcessView::open(ProcessViewId(5), u_child.id()).unwrap();
    let (w_id, u_id) = (w.id(), u.id());
    engine.views.push(w);
    engine.views.push(u);
    let mut w_guard = SystemScopeChildGuard::new(w_child);
    let mut u_guard = SystemScopeChildGuard::new(u_child);
    assert!(
        engine
            .dispatch_lifecycle_record(
                &mut session,
                &collected_finish_leader_exit(w_guard.pid()),
                &mut PendingViewRetirements::new()
            )
            .is_none()
    );
    assert!(engine.pending_leader_exit_views.contains(&w_id));
    w_guard.reap().unwrap();
    u_guard.reap().unwrap();
    // The record queues behind the live graph instead of dispatching.
    engine
        .service_collected_finish_records(
            &mut session,
            vec![collected_finish_leader_exit(u_guard.pid())],
            0,
            1,
        )
        .unwrap();
    assert_eq!(engine.pending_discovery_records.len(), 1);
    assert!(engine.pending_leader_exit_views.contains(&w_id));
    assert!(!engine.pending_leader_exit_views.contains(&u_id));
    // Neither advances until Done. The drive waits on the async worker
    // close instead of racing it with a fixed count (256 flaked once in
    // a 39-test battery, solo green); every assertion is unchanged.
    drive_graph_until(&mut engine, &mut session, |engine, _, _| {
        if engine.collected_graph.is_none() {
            return true;
        }
        assert_eq!(engine.pending_discovery_records.len(), 1);
        assert!(engine.pending_leader_exit_views.contains(&w_id));
        assert!(!engine.pending_leader_exit_views.contains(&u_id));
        assert_eq!(engine.collected_graphs_created, 1);
        false
    });
    assert_eq!(engine.pending_discovery_records.len(), 1);
    assert!(engine.pending_leader_exit_views.contains(&w_id));
    // After Done the record dispatches first, queueing U's assessment behind W's.
    engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(engine.pending_discovery_records.is_empty());
    assert!(engine.pending_leader_exit_views.contains(&w_id));
    assert!(engine.pending_leader_exit_views.contains(&u_id));
    assert_eq!(engine.collected_graphs_created, 1);
    // Then the assessments settle in original order: W before U.
    engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert_eq!(engine.collected_finish_assessment_after, Some(w_id));
    assert!(!engine.pending_leader_exit_views.contains(&w_id));
    assert!(engine.pending_leader_exit_views.contains(&u_id));
    assert!(engine.retirement_intents.contains_key(&w_id));
    engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(!engine.pending_leader_exit_views.contains(&u_id));
    assert!(engine.retirement_intents.contains_key(&u_id));
    assert!(engine.pending_leader_exit_views.is_empty());
    assert_eq!(engine.collected_graphs_created, 1);

    // Second half: a requested-but-uncreated graph lets a queued record
    // dispatch first and is created on the first credit with an empty queue,
    // no pending assessment and no open journal/batch.
    let w_child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let u_child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let w_pid = w_child.id();
    let u_pid = u_child.id();
    let mut second = lifecycle_discovered(vec![
        ProcessView::open(ProcessViewId(4), w_pid).unwrap(),
        ProcessView::open(ProcessViewId(5), u_pid).unwrap(),
    ]);
    second.scope = Scope::System;
    let mut guards = vec![
        SystemScopeChildGuard::new(w_child),
        SystemScopeChildGuard::new(u_child),
    ];
    let mut session = ScriptedSession::default();
    assert!(
        second
            .dispatch_lifecycle_record(
                &mut session,
                &collected_finish_leader_exit(w_pid),
                &mut PendingViewRetirements::new()
            )
            .is_none()
    );
    second
        .pending_discovery_records
        .push(QueuedDiscoveryRecord {
            record: collected_finish_leader_exit(u_pid),
            terminal_owner: None,
            terminal_exports: Vec::new(),
        });
    second.collected_graph_requested = true;
    for guard in &mut guards {
        guard.reap().unwrap();
    }
    // Credit 1: the queued record dispatches; no creation with work queued.
    second
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(second.pending_discovery_records.is_empty());
    assert_eq!(second.pending_leader_exit_views.len(), 2);
    assert_eq!(second.collected_graphs_created, 0);
    // Credits 2-3: the assessments settle; intents do not block creation,
    // but pending assessments do.
    second
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert_eq!(second.pending_leader_exit_views.len(), 1);
    assert_eq!(second.collected_graphs_created, 0);
    second
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(second.pending_leader_exit_views.is_empty());
    assert!(!second.retirement_intents.is_empty());
    assert_eq!(second.collected_graphs_created, 0);
    // Credit 4: the first all-clear credit creates the graph.
    assert!(second.terminal_journal.is_none());
    assert!(second.terminal_batch.is_none());
    second
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert_eq!(second.collected_graphs_created, 1);
    assert!(
        second
            .collected_graph
            .as_ref()
            .is_some_and(|graph| graph.phase == GraphPhase::Intake)
    );
}

#[test]
fn collected_graph_intake_selects_ready_intent_only() {
    let mut case = CollectedFinishGraphCase::new(false);
    assert!(
        case.engine
            .retirement_intents
            .insert(case.view, RetirementCause::ExpectedRemoval)
            .is_none()
    );
    assert!(case.engine.ready_expected_removals.insert(case.view));
    let first = case.service(1);
    assert!(first.pending);
    assert!(case.engine.collected_graph_requested);
    assert_eq!(case.engine.collected_graphs_created, 0);
    let second = case.service(1);
    assert!(second.pending);
    assert_eq!(case.engine.collected_graphs_created, 1);
    assert!(
        case.engine
            .collected_graph
            .as_ref()
            .is_some_and(|graph| graph.phase == GraphPhase::Intake)
    );
    assert!(case.engine.pending_retirements.contains(&case.view));
    assert!(case.engine.retirement_intents.contains_key(&case.view));
    case.assert_original_pending();
    let third = case.service(1);
    assert!(third.pending);
    assert!(case.engine.pending_retirements.contains(&case.view));
    assert!(case.engine.retirement_intents.contains_key(&case.view));
    case.assert_original_pending();
}

#[test]
fn collected_graph_native_error_is_contained() {
    // No-carrier prepare: the error is contained as RefusedUntouched with one
    // disclosure; later credits stay Ok and pending.
    let mut engine = Engine::empty();
    engine.scope = Scope::System;
    let storage = engine
        .collected_test_pool
        .reserve(
            std::mem::size_of::<CollectedGraph>()
                + crate::semantics_edge::resources::OWNED_ALLOCATION_PADDING,
        )
        .unwrap();
    let input = RetainedRetirementInput::from_reserved_removed(
        Vec::new(),
        engine.collected_test_pool.reserve(64).unwrap(),
    )
    .unwrap();
    let mut graph = CollectedGraph::new(storage);
    graph.phase = GraphPhase::NativePrepare;
    graph.removed = Some(input);
    engine.collected_graph = Some(Box::new(graph));
    let mut session = ScriptedSession::default();
    let outcome = engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(outcome.pending);
    assert_eq!(
        engine
            .collected_graph
            .as_ref()
            .expect("refused graph stays boxed")
            .verdict,
        Some(Verdict::RefusedUntouched)
    );
    assert_eq!(
        engine.collected_graph_refused(),
        Some("terminal graph refused before native mutation")
    );
    assert!(engine.counters.object_skips.iter().any(|skip| {
        skip.subject == "collected native retirement"
            && skip.reason
                == "the original removal was refused before native mutation; originals remain owned"
    }));
    let again = engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(again.pending);
    assert_eq!(
        engine
            .counters
            .object_skips
            .iter()
            .filter(|skip| skip.subject == "collected native retirement")
            .count(),
        1
    );

    // Post-mutation poll error: RefusedRetained with the G4 disclosure. The
    // ticket comes from a real fixture preparation; the staged session has no
    // carrier, so the poll fails after the mutation was recorded.
    let (child, mut engine, _) = engine_with_one_accepted_provider();
    let _accepted = SystemScopeChildGuard::new(child);
    engine.scope = Scope::System;
    let mut fixture = crate::attach::RetirementFixture::new_collected(
        &engine.plan.slots,
        &engine.pinned,
        Box::new(|owned, _| {
            drop(owned);
            Ok(())
        }),
    );
    let reserve = engine.collected_test_pool.reserver();
    // A working preparation, not a measure test: real slots carry links and
    // backing the static measure undercounts, so pay headroom.
    let mut input = Some(
        RetainedRetirementInput::from_reserved_removed(
            engine.plan.slots.clone(),
            reserve.reserve(1024 * 1024).unwrap(),
        )
        .unwrap(),
    );
    let mut ticket = None;
    for _ in 0..64 {
        let progress = fixture.collected_prepare(&mut input, &reserve, 1).unwrap();
        match progress.state {
            crate::attach::CollectedRetirementState::Preparing => {}
            crate::attach::CollectedRetirementState::Prepared(ready) => {
                ticket = Some(ready);
                break;
            }
            _ => panic!("unexpected preparation phase"),
        }
    }
    let ticket = ticket.expect("fixture preparation must reach Prepared");
    drop(fixture);
    let storage = engine
        .collected_test_pool
        .reserve(
            std::mem::size_of::<CollectedGraph>()
                + crate::semantics_edge::resources::OWNED_ALLOCATION_PADDING,
        )
        .unwrap();
    let mut graph = CollectedGraph::new(storage);
    graph.phase = GraphPhase::NativePoll;
    graph.ticket = Some(ticket);
    graph.mutated = true;
    engine.collected_graph = Some(Box::new(graph));
    let mut session = ScriptedSession::default();
    let outcome = engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(outcome.pending);
    assert_eq!(
        engine
            .collected_graph
            .as_ref()
            .expect("refused graph stays boxed")
            .verdict,
        Some(Verdict::RefusedRetained)
    );
    assert_eq!(
        engine.collected_graph_refused(),
        Some("native ownership uncertain")
    );
    assert!(engine.counters.object_skips.iter().any(|skip| {
        skip.subject == "global native retirement"
            && skip.reason
                == "original static ownership remains uncertain; replacement admission is blocked"
    }));
    let again = engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(again.pending);
    assert_eq!(
        engine
            .counters
            .object_skips
            .iter()
            .filter(|skip| skip.subject == "global native retirement")
            .count(),
        1
    );
}

#[test]
fn collected_graph_exec_refresh_is_disposed_once() {
    let (child, mut engine, _) = engine_with_one_accepted_provider();
    let _accepted = SystemScopeChildGuard::new(child);
    engine.scope = Scope::System;
    let view = engine.views[0].id();
    let mut session = ScriptedSession::default();
    assert!(
        engine
            .retirement_intents
            .insert(view, RetirementCause::ExecRefresh)
            .is_none()
    );
    assert!(engine.refresh_requested.is_empty());
    let first = engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(first.pending);
    assert!(engine.collected_graph_requested);
    let second = engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(second.pending);
    assert!(!engine.retirement_intents.contains_key(&view));
    assert!(engine.views.iter().any(|owner| owner.id() == view));
    assert!(!engine.pending_retirements.contains(&view));
    assert!(engine.refresh_requested.is_empty());
    assert!(engine.counters.object_skips.iter().any(|skip| {
        skip.subject == "live discovery lifecycle"
            && skip.reason == "an exec refresh observed before the terminal stop was not rescanned"
    }));
    // Exactly one disclosure even after more credits.
    for _ in 0..4 {
        engine
            .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
            .unwrap();
    }
    assert_eq!(
        engine
            .counters
            .object_skips
            .iter()
            .filter(|skip| {
                skip.subject == "live discovery lifecycle"
                    && skip.reason
                        == "an exec refresh observed before the terminal stop was not rescanned"
            })
            .count(),
        1
    );
}

#[test]
fn exec_refresh_outside_finish_still_requests_refresh() {
    // The G15 twin: outside collected Finish the same EXEC queues a refresh
    // for its pid (mirrors `collected_finish_incomplete_terminal_route`'s
    // EXEC dispatch). Pinning twin: the ordinary path is untouched by T4.
    let pid = std::process::id();
    let mut engine = Engine::empty();
    engine.scope = Scope::Pid(pid);
    let (view, _owner) = attach_live_loader_context(&mut engine, pid);
    let mut session = ScriptedSession::default();
    let mut pending = PendingViewRetirements::new();
    assert_eq!(
        engine.dispatch_lifecycle_record(&mut session, &exec_record_for(pid), &mut pending),
        Some(view)
    );
    assert_eq!(
        engine.retirement_intents.get(&view),
        Some(&RetirementCause::ExecRefresh)
    );
    assert!(engine.refresh_requested.contains_key(&pid));
}

#[test]
fn collected_graph_rejection_only_requests_graph() {
    let (child, mut engine, _) = engine_with_one_accepted_provider();
    let _accepted = SystemScopeChildGuard::new(child);
    engine.scope = Scope::System;
    let object = engine.plan.slots[0].object;
    let key = engine.pinned.summary(object).unwrap().key;
    assert!(engine.pending_rejected_keys.insert(key));
    let mut session = ScriptedSession::default();
    // First credit: only rejected keys set the request and report progress.
    let first = engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(first.pending);
    assert!(first.progressed);
    assert!(engine.collected_graph_requested);
    assert_eq!(engine.collected_graphs_created, 0);
    // Next credit: the barrier creates the graph.
    let second = engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(second.pending);
    assert_eq!(engine.collected_graphs_created, 1);
    assert!(
        engine
            .collected_graph
            .as_ref()
            .is_some_and(|graph| graph.phase == GraphPhase::Freeze)
    );
    assert!(engine.pending_rejected_keys.contains(&key));
}

#[test]
fn collected_graph_unready_intent_is_disposed_once_at_q() {
    // Ok(false): a live (unexited) named view is disposed once with the OD-7
    // count, and Finish drains afterwards.
    let (child, mut engine, _) = engine_with_one_accepted_provider();
    let _accepted = SystemScopeChildGuard::new(child);
    engine.scope = Scope::System;
    let view = engine.views[0].id();
    assert_eq!(engine.views[0].original_exited(), Ok(false));
    let mut session = ScriptedSession::default();
    assert!(
        engine
            .retirement_intents
            .insert(view, RetirementCause::ExpectedRemoval)
            .is_none()
    );
    engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(engine.collected_graph_requested);
    engine
        .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
        .unwrap();
    assert!(!engine.retirement_intents.contains_key(&view));
    assert!(engine.views.iter().any(|owner| owner.id() == view));
    assert!(!engine.pending_retirements.contains(&view));
    let mut saw_skip = false;
    let mut drained = false;
    for _ in 0..64 {
        let outcome = engine
            .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
            .unwrap();
        if engine.counters.object_skips.iter().any(|skip| {
            skip.subject == "live discovery lifecycle"
                && skip.reason.starts_with("1 retirements not proven")
        }) {
            saw_skip = true;
        }
        if !outcome.pending {
            drained = true;
            break;
        }
    }
    assert!(saw_skip, "OD-7 must disclose the unproven count once");
    assert_eq!(
        engine
            .counters
            .object_skips
            .iter()
            .filter(|skip| {
                skip.subject == "live discovery lifecycle"
                    && skip.reason.starts_with("1 retirements not proven")
            })
            .count(),
        1
    );
    assert!(drained, "Finish drains after the unproven disposal");

    // Err: no live pin can stage a failing exit read, so the factored Intake
    // readiness arm runs with an injected failure; the loss text, the count
    // disclosure and the drain stay on the real path.
    let mut engine = Engine::empty();
    engine.scope = Scope::System;
    let probe = ProcessView::open(ProcessViewId(3), std::process::id()).unwrap();
    let probe_id = probe.id();
    engine.views.push(probe);
    assert!(
        engine
            .retirement_intents
            .insert(probe_id, RetirementCause::ExpectedRemoval)
            .is_none()
    );
    let storage = engine
        .collected_test_pool
        .reserve(
            std::mem::size_of::<CollectedGraph>()
                + crate::semantics_edge::resources::OWNED_ALLOCATION_PADDING,
        )
        .unwrap();
    let mut graph = CollectedGraph::new(storage);
    graph.phase = GraphPhase::Intake;
    engine.collected_graph = Some(Box::new(graph));
    let mut graph = engine.collected_graph.take().expect("staged graph");
    engine.settle_intake_ready(
        &mut graph,
        probe_id,
        Err("injected pin failure".to_string()),
    );
    engine.collected_graph = Some(graph);
    assert!(!engine.retirement_intents.contains_key(&probe_id));
    assert!(engine.views.iter().any(|owner| owner.id() == probe_id));
    assert!(!engine.pending_retirements.contains(&probe_id));
    assert!(
        engine.counters.object_skips.iter().any(|skip| {
            skip.subject == "live discovery lifecycle"
                && skip.reason
                    == "the original process pin could not prove expected exit; retirement remains queued: injected pin failure"
        })
    );
    let mut session = ScriptedSession::default();
    let mut saw_skip = false;
    let mut drained = false;
    for _ in 0..64 {
        let outcome = engine
            .service_collected_finish_records(&mut session, Vec::new(), 0, 1)
            .unwrap();
        if engine.counters.object_skips.iter().any(|skip| {
            skip.subject == "live discovery lifecycle"
                && skip.reason.starts_with("1 retirements not proven")
        }) {
            saw_skip = true;
        }
        if !outcome.pending {
            drained = true;
            break;
        }
    }
    assert!(saw_skip, "OD-7 must disclose the unproven count once");
    assert_eq!(
        engine
            .counters
            .object_skips
            .iter()
            .filter(|skip| {
                skip.subject == "live discovery lifecycle"
                    && skip.reason.starts_with("1 retirements not proven")
            })
            .count(),
        1
    );
    assert!(drained, "Finish drains after the unproven disposal");
}

