/// Finding 3: newcomer classification ignores timing marks. A truly new pid
/// (absent from the previous enumeration) admits first even when it carries
/// a stale arrival mark (e.g. a pressure pass marked it); marks are timing
/// evidence only.
#[test]
fn truly_new_pid_with_stale_mark_still_admits_first() {
    let guards = e06_spawn_sleeps(3);
    let mut pids: Vec<u32> = guards.iter().map(|guard| guard.pid()).collect();
    pids.sort_unstable();
    let (initial, backlog, newcomer) = (pids[0], pids[1], pids[2]);
    let scope_dir = tempfile::tempdir().expect("a scope directory");
    e06_write_listing(scope_dir.path(), &[initial]);
    let scope = crate::scope::cgroup(scope_dir.path()).expect("open scope directory");
    let args = e06_cgroup_args(scope_dir.path(), vec![], None);
    let mut engine = Engine::discover(&args, &scope, None).expect("an uncapped cgroup captures");
    assert_eq!(engine.views.len(), 1);
    engine.scheduler.set_tick_quantum_ns_for_test(1_000);

    e06_write_listing(scope_dir.path(), &[initial, backlog]);
    opus_probe_refresh_with_permits(&mut engine, 0);
    assert!(!engine.views.iter().any(|view| view.pid() == backlog));
    assert!(
        engine.newcomer_first_seen.contains_key(&backlog),
        "the deferred pid is marked backlog"
    );

    e06_write_listing(scope_dir.path(), &[initial, backlog, newcomer]);
    // Simulate a stale mark (e.g. a pressure service pass marked the truly
    // new pid): classification must still see it as a newcomer.
    engine.newcomer_first_seen.insert(newcomer, None);
    opus_probe_refresh_with_permits(&mut engine, 1);
    let kept: Vec<u32> = engine.views.iter().map(|view| view.pid()).collect();
    assert!(
        kept.contains(&newcomer),
        "the truly new pid admits first despite its stale mark: {kept:?}"
    );
    assert!(
        !kept.contains(&backlog),
        "the marked backlog waits another tick: {kept:?}"
    );
}

/// Scarce ticks admit pending newcomers first: at a full view cap with
/// no evictable view, a pid requested after the previous tick started
/// (fresh pending) completes its probationary probe ahead of an older
/// pending pid, which still completes on the next tick. The fresh pid
/// has the HIGHER pid, so pid order alone would serve it last.
#[test]
fn scarce_tick_serves_fresh_pending_newcomer_before_older_backlog() {
    let dir = tempfile::tempdir().expect("a fixture directory");
    let provider = system_scope_build_fixture(dir.path(), "scarce-fresh");
    let driver = system_scope_build_driver(dir.path());
    let loaded = system_scope_spawn_loaded(&driver, &provider);
    let owner_pid = loaded.pid();
    let mut sleeps = e06_spawn_sleeps(2);
    sleeps.sort_by_key(SystemScopeChildGuard::pid);
    let older_pid = sleeps[0].pid();
    let fresh_pid = sleeps[1].pid();
    let scope_dir = tempfile::tempdir().expect("a scope directory");
    e06_write_listing(scope_dir.path(), &[owner_pid]);
    let scope = crate::scope::cgroup(scope_dir.path()).expect("open scope directory");
    let args = e06_cgroup_args(scope_dir.path(), vec![provider], Some(1));
    let mut engine = Engine::discover(&args, &scope, None).expect("a capped cgroup captures");
    assert_eq!(engine.views.len(), 1);
    engine.scheduler.set_tick_quantum_ns_for_test(1_000);
    // The retained view owns its provider, so no eviction can free a
    // slot: pending newcomers complete viewless (Lane-A P3) in window
    // order, one per truncated tick.
    assert!(
        engine
            .find_evictable_victim_for_selected(fresh_pid)
            .is_none(),
        "no victim: the retained view owns its provider"
    );
    let mut listing = vec![owner_pid, older_pid, fresh_pid];
    listing.sort_unstable();
    e06_write_listing(scope_dir.path(), &listing);
    assert!(engine.request_refresh(older_pid, Some(100)));
    assert!(engine.request_refresh(fresh_pid, Some(200)));
    // Stage the previous tick at 150: the older request (100) reads as
    // backlog, the fresh one (200) as a newcomer.
    engine.scheduler.begin_deep_scan_tick(Some(150));
    opus_probe_refresh_with_permits(&mut engine, 1);
    assert!(
        !engine.refresh_requested.contains_key(&fresh_pid),
        "the fresh pending newcomer completes first"
    );
    assert!(
        engine.refresh_requested.contains_key(&older_pid),
        "the older backlog pid waits another tick"
    );
    assert_eq!(
        engine.probationary_completions, 1,
        "exactly one viewless completion on the truncated tick"
    );
    opus_probe_refresh_with_permits(&mut engine, 1);
    assert!(
        !engine.refresh_requested.contains_key(&older_pid),
        "the older backlog pid completes next"
    );
    assert_eq!(engine.probationary_completions, 2);
}

/// Backlog rotation passes a persistently failing low pid: three backlog
/// pids (all deferred unattempted on their arrival tick), the lowest one
/// persistently unreadable, one attempt per tick. The third pid keeps the
/// every-attempt-recorded-as-newcomer kill past the failed-newcomer sink:
/// with a frozen backlog cursor the first two pids cycle forever while
/// the third never admits. A shared newcomer/backlog cursor strands both
/// followers behind the failing pid instead. Four one-permit ticks: the
/// third is the fourth under-cap tick, whose polling round spends the
/// permit on a retained rescan, so the last follower admits on the fourth.
#[test]
fn opus_r3_backlog_rotation_passes_failing_low_pid() {
    let first = e06_spawn_sleeps(1);
    let first_pid = first[0].pid();
    let scope_dir = tempfile::tempdir().expect("a scope directory");
    e06_write_listing(scope_dir.path(), &[first_pid]);
    let scope = crate::scope::cgroup(scope_dir.path()).expect("open scope directory");
    let args = e06_cgroup_args(scope_dir.path(), vec![], None);
    let mut engine = Engine::discover(&args, &scope, None).unwrap();
    engine.scheduler.set_tick_quantum_ns_for_test(1_000);
    let mut more = e06_spawn_sleeps(3);
    more.sort_by_key(SystemScopeChildGuard::pid);
    let failed_pid = more[0].pid();
    let mid_pid = more[1].pid();
    let later_pid = more[2].pid();
    more[0].reap().expect("reap the owned failed candidate");
    e06_write_listing(
        scope_dir.path(),
        &[first_pid, failed_pid, mid_pid, later_pid],
    );
    opus_probe_refresh_with_permits(&mut engine, 0);
    assert_eq!(engine.views.len(), 1);
    opus_probe_refresh_with_permits(&mut engine, 1);
    let after1 = engine.views.len();
    opus_probe_refresh_with_permits(&mut engine, 1);
    let after2 = engine.views.len();
    opus_probe_refresh_with_permits(&mut engine, 1);
    let after3 = engine.views.len();
    assert_eq!(
        after3, 2,
        "the fourth under-cap tick spends its permit on polling rescans"
    );
    assert!(
        engine.polling_rescans_queued > 0,
        "the third one-permit tick ran the polling round"
    );
    opus_probe_refresh_with_permits(&mut engine, 1);
    let kept: BTreeSet<u32> = engine.views.iter().map(ProcessView::pid).collect();
    eprintln!(
        "OPUS-M16K after_tick1_views={after1} after_tick2_views={after2} after_tick3_views={after3} kept={kept:?} later={later_pid}"
    );
    assert!(
        kept.contains(&mid_pid),
        "the backlog rotation advances past the failing pid"
    );
    assert!(
        kept.contains(&later_pid),
        "the backlog rotation passes the failing pid"
    );
}

fn opus_probe_view_pids(engine: &Engine) -> std::collections::BTreeSet<u32> {
    engine.views.iter().map(|view| view.pid()).collect()
}

/// First existing path among candidates, in order: the static-sleeper
/// probe takes the first installed busybox and reports none when no
/// candidate exists.
fn opus_first_existing(candidates: &[&Path]) -> Option<PathBuf> {
    candidates
        .iter()
        .find(|path| path.is_file())
        .map(|path| path.to_path_buf())
}

/// Builds the static-sleeper fallback: the raw-syscall fixture compiled
/// `gcc -static -nostdlib -fno-stack-protector` (no libc to link, no
/// stack guard to provide), for hosts without busybox. Panics with a
/// named reason when the build fails.
fn opus_build_static_sleeper(dir: &Path) -> PathBuf {
    let source = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/opus-static-sleeper.c");
    let out = dir.join("opus-static-sleeper");
    let status = std::process::Command::new("gcc")
        .args([
            "-std=c11",
            "-O2",
            "-Wall",
            "-Wextra",
            "-Werror",
            "-fno-stack-protector",
            "-static",
            "-nostdlib",
            "-o",
        ])
        .arg(&out)
        .arg(&source)
        .status();
    match status {
        Ok(status) if status.success() => out,
        Ok(status) => panic!(
            "opus B4 static sleeper unavailable: no busybox at /usr/bin/busybox or /bin/busybox and the gcc static fallback failed with {status}"
        ),
        Err(error) => panic!(
            "opus B4 static sleeper unavailable: no busybox at /usr/bin/busybox or /bin/busybox and gcc could not run: {error}"
        ),
    }
}

/// Static sleepers for the B4 waiter test: busybox where installed
/// (probed in a fixed location order — CI runners have none), else a
/// tiny gcc-built static sleeper. Returns the guards plus the fallback
/// build directory when one was built (held so the binary outlives the
/// children). `P11SCOPE_OPUS_SLEEPER=fallback` forces the gcc path.
/// Panics with a named reason when neither backend exists.
fn opus_spawn_static_sleeps(
    count: usize,
) -> (Vec<SystemScopeChildGuard>, Option<tempfile::TempDir>) {
    let force_fallback =
        std::env::var("P11SCOPE_OPUS_SLEEPER").is_ok_and(|value| value == "fallback");
    let busybox = if force_fallback {
        None
    } else {
        opus_first_existing(&[Path::new("/usr/bin/busybox"), Path::new("/bin/busybox")])
    };
    let (program, args, hold): (PathBuf, &[&str], Option<tempfile::TempDir>) = match busybox {
        Some(path) => (path, &["sleep", "60"], None),
        None => {
            let dir = tempfile::tempdir().expect("a sleeper build directory");
            let sleeper = opus_build_static_sleeper(dir.path());
            (sleeper, &["60"], Some(dir))
        }
    };
    let guards: Vec<SystemScopeChildGuard> = (0..count)
        .map(|_| {
            SystemScopeChildGuard::new(
                std::process::Command::new(&program)
                    .args(args)
                    .stdin(std::process::Stdio::null())
                    .stdout(std::process::Stdio::null())
                    .stderr(std::process::Stdio::null())
                    .die_with_parent()
                    .spawn()
                    .unwrap(),
            )
        })
        .collect();
    let self_exe = std::env::current_exe().unwrap();
    for guard in &guards {
        let exe = format!("/proc/{}/exe", guard.pid());
        let mut execed = false;
        for _ in 0..500 {
            if std::fs::read_link(&exe).is_ok_and(|target| target != self_exe) {
                execed = true;
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(execed, "static sleeper child never execed");
    }
    (guards, hold)
}

/// The sleeper probe takes the first installed busybox in location
/// order, and reports none when no candidate exists.
#[test]
fn opus_sleeper_probe_takes_the_first_installed_busybox() {
    let dir = tempfile::tempdir().expect("a probe directory");
    let missing = dir.path().join("no-such-busybox");
    let present = dir.path().join("busybox");
    std::fs::write(&present, "x").expect("a fake busybox");
    assert_eq!(
        opus_first_existing(&[missing.as_path(), present.as_path()]),
        Some(present.clone())
    );
    assert_eq!(
        opus_first_existing(&[present.as_path(), missing.as_path()]),
        Some(present.clone())
    );
    assert_eq!(opus_first_existing(&[missing.as_path()]), None);
    assert_eq!(opus_first_existing(&[]), None);
}

/// The gcc static-sleeper fallback builds and runs: a raw-syscall binary
/// that sleeps its argv seconds with the binary itself as its exe.
#[test]
fn opus_static_sleeper_fallback_builds_and_sleeps() {
    let dir = tempfile::tempdir().expect("a sleeper build directory");
    let sleeper = opus_build_static_sleeper(dir.path());
    let mut child = std::process::Command::new(&sleeper)
        .arg("30")
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
        .expect("the fallback sleeper spawns");
    std::thread::sleep(std::time::Duration::from_secs(1));
    assert!(
        child.try_wait().expect("poll the sleeper").is_none(),
        "the sleeper is still asleep after a second"
    );
    let exe = std::fs::read_link(format!("/proc/{}/exe", child.id())).expect("the sleeper exe");
    assert_eq!(
        std::fs::canonicalize(&exe).expect("canonical exe"),
        std::fs::canonicalize(&sleeper).expect("canonical sleeper"),
        "the sleeper execed the fallback binary"
    );
    child.kill().expect("reap the sleeper");
    let _ = child.wait();
}

/// Opus Probe B4: 200 static (ungrouped) sleeps over a 40-view cap, so a
/// 64-pid reconcile slice holds more unscanned pids than the eviction
/// budget. A marked provider-carrying waiter outside the slice must settle
/// within one sweep; eviction-freed slots reach pending waiters first, not
/// never-touched long-runners.
#[test]
fn reconcile_marked_waiter_vs_ungrouped_slice_settles_within_one_sweep() {
    let (sleeps, _sleeper_hold) = opus_spawn_static_sleeps(200);
    let mut sleep_pids: Vec<u32> = sleeps.iter().map(|guard| guard.pid()).collect();
    sleep_pids.sort_unstable();
    let cap = 40usize;
    let tag = "B4";
    let dir = tempfile::tempdir().expect("a fixture directory");
    let provider = system_scope_build_fixture(dir.path(), "opus-waiter4");
    let driver = system_scope_build_driver(dir.path());
    let scope_dir = tempfile::tempdir().expect("a scope directory");
    e06_write_listing(scope_dir.path(), &sleep_pids);
    let scope = crate::scope::cgroup(scope_dir.path()).expect("open scope directory");
    let args = e06_cgroup_args(scope_dir.path(), vec![provider.clone()], Some(cap));
    let mut engine = Engine::discover(&args, &scope, None).expect("a capped cgroup captures");
    engine.scheduler.set_quantum_ns_for_test(u64::MAX);
    engine.scheduler.set_tick_quantum_ns_for_test(u64::MAX);
    for _ in 0..40 {
        if engine.views.len() >= cap {
            break;
        }
        refresh_inventory_once(&mut engine);
    }
    assert_eq!(engine.views.len(), cap, "rotation fills the cap");
    if engine.scheduler.over_cap_passes() % 2 == 1 {
        refresh_inventory_once(&mut engine);
        assert_eq!(engine.views.len(), cap);
    }
    let child = system_scope_spawn_loaded(&driver, &provider);
    let waiter = child.pid();
    let mut listing = sleep_pids.clone();
    listing.push(waiter);
    listing.sort_unstable();
    e06_write_listing(scope_dir.path(), &listing);
    assert!(engine.request_refresh(waiter, None), "the waiter queues");
    let park = *opus_probe_view_pids(&engine).iter().max().unwrap();
    engine.scheduler.advance_cursor(park);
    let sweeps0 = engine.scheduler.reconcile_sweeps_for_test();
    refresh_inventory_once(&mut engine);
    assert_eq!(
        engine.scheduler.reconcile_sweeps_for_test(),
        sweeps0,
        "an ordinary pass"
    );
    assert!(!opus_probe_view_pids(&engine).contains(&waiter));
    let marked = engine.newcomer_first_seen.contains_key(&waiter);
    let mut settled_after = None;
    for pass in 0..24 {
        let marks: std::collections::BTreeSet<u32> =
            engine.newcomer_first_seen.keys().copied().collect();
        let before = opus_probe_view_pids(&engine);
        let evictions = engine.exploratory_evictions;
        let order = crate::discovery::scheduler::DiscoveryScheduler::rotated_after(
            &listing,
            engine.scheduler.cursor(),
        );
        let slice: Vec<u32> = order.into_iter().take(64).collect();
        let pool = slice
            .iter()
            .filter(|pid| !before.contains(pid) && !engine.scheduler.cooling_down(**pid))
            .count();
        let evictable = engine.exploratory_evictable_views().len();
        refresh_inventory_once(&mut engine);
        let after = opus_probe_view_pids(&engine);
        let added: Vec<u32> = after.difference(&before).copied().collect();
        let added_marked = added.iter().filter(|pid| marks.contains(pid)).count();
        eprintln!(
            "OPUS-PROBE-{tag} pass={pass} sweeps={} pre_evictable={evictable} pre_pool={pool} slice_has_waiter={} evicted={} added={} added_previously_marked={added_marked} waiter_view={}",
            engine.scheduler.reconcile_sweeps_for_test() - sweeps0,
            slice.contains(&waiter),
            engine.exploratory_evictions - evictions,
            added.len(),
            after.contains(&waiter)
        );
        if after.contains(&waiter) {
            settled_after = Some(engine.scheduler.reconcile_sweeps_for_test() - sweeps0);
            break;
        }
    }
    eprintln!(
        "OPUS-PROBE-{tag} waiter_marked_after_ordinary={marked} settled_after_sweeps={settled_after:?}"
    );
    assert_eq!(
        settled_after,
        Some(1),
        "the marked waiter settles within one sweep"
    );
}

/// OPUS r4 B4F: B4 with 20 fresh-classified waiters (requested after the
/// previous working tick started) against a 32-eviction reconcile. All
/// waiters must settle within one sweep: eviction-freed slots reach
/// pending waiters before never-touched slice candidates.
#[test]
fn opus_r4_b4_fresh_waiters_settle_within_one_sweep() {
    let (sleeps, _hold) = opus_spawn_static_sleeps(200);
    let mut sleep_pids: Vec<u32> = sleeps.iter().map(|guard| guard.pid()).collect();
    sleep_pids.sort_unstable();
    let cap = 40usize;
    let scope_dir = tempfile::tempdir().expect("a scope directory");
    e06_write_listing(scope_dir.path(), &sleep_pids);
    let scope = crate::scope::cgroup(scope_dir.path()).expect("open scope directory");
    let args = e06_cgroup_args(scope_dir.path(), vec![], Some(cap));
    let mut engine = Engine::discover(&args, &scope, None).expect("a capped cgroup captures");
    engine.scheduler.set_quantum_ns_for_test(u64::MAX);
    engine.scheduler.set_tick_quantum_ns_for_test(u64::MAX);
    for _ in 0..40 {
        if engine.views.len() >= cap {
            break;
        }
        refresh_inventory_once(&mut engine);
    }
    assert_eq!(engine.views.len(), cap, "rotation fills the cap");
    if engine.scheduler.over_cap_passes() % 2 == 1 {
        refresh_inventory_once(&mut engine);
        assert_eq!(engine.views.len(), cap);
    }
    let (waiters_g, _hold2) = opus_spawn_static_sleeps(20);
    let waiters: Vec<u32> = waiters_g.iter().map(|guard| guard.pid()).collect();
    let mut listing = sleep_pids.clone();
    listing.extend(waiters.iter().copied());
    listing.sort_unstable();
    e06_write_listing(scope_dir.path(), &listing);
    let park = *opus_probe_view_pids(&engine).iter().max().unwrap();
    engine.scheduler.advance_cursor(park);
    let sweeps0 = engine.scheduler.reconcile_sweeps_for_test();
    refresh_inventory_once(&mut engine);
    assert_eq!(
        engine.scheduler.reconcile_sweeps_for_test(),
        sweeps0,
        "an ordinary pass"
    );
    // A long-running capture has had a working tick before this one.
    engine
        .scheduler
        .begin_deep_scan_tick(crate::attach::monotonic_ns());
    for pid in &waiters {
        let had = engine.refresh_requested.get(pid).map(|r| r.first_seen_ns);
        assert!(engine.request_refresh(*pid, crate::attach::monotonic_ns()));
        eprintln!(
            "OPUS-B4F request pid={pid} existing={had:?} now_seen={:?}",
            engine
                .refresh_requested
                .get(pid)
                .and_then(|r| r.first_seen_ns)
        );
    }
    let mut settled = 0usize;
    for pass in 0..24 {
        let evictions = engine.exploratory_evictions;
        refresh_inventory_once(&mut engine);
        let after = opus_probe_view_pids(&engine);
        settled = waiters.iter().filter(|pid| after.contains(pid)).count();
        let sweeps = engine.scheduler.reconcile_sweeps_for_test() - sweeps0;
        eprintln!(
            "OPUS-B4F pass={pass} sweeps={sweeps} evicted={} waiters_settled={settled}/20 views={}",
            engine.exploratory_evictions - evictions,
            after.len()
        );
        if sweeps >= 1 {
            break;
        }
    }
    assert_eq!(settled, 20, "every fresh waiter settles within one sweep");
}

/// OPUS r4 B4H: eviction budget 1, one fresh waiter requested right
/// before each reconcile pass (the ordinary pass between has no pending
/// work, so no window clears the owed flag). Each waiter must take its
/// sweep's only freed slot ahead of the never-touched slice candidate.
#[test]
fn opus_r4_b4_owed_lead_never_hands_the_freed_slot_to_rotation() {
    let (sleeps, _hold) = opus_spawn_static_sleeps(200);
    let mut sleep_pids: Vec<u32> = sleeps.iter().map(|guard| guard.pid()).collect();
    sleep_pids.sort_unstable();
    let cap = 40usize;
    let scope_dir = tempfile::tempdir().expect("a scope directory");
    e06_write_listing(scope_dir.path(), &sleep_pids);
    let scope = crate::scope::cgroup(scope_dir.path()).expect("open scope directory");
    let args = e06_cgroup_args(scope_dir.path(), vec![], Some(cap));
    let mut engine = Engine::discover(&args, &scope, None).expect("a capped cgroup captures");
    engine.scheduler.set_quantum_ns_for_test(u64::MAX);
    engine.scheduler.set_tick_quantum_ns_for_test(u64::MAX);
    for _ in 0..40 {
        if engine.views.len() >= cap {
            break;
        }
        refresh_inventory_once(&mut engine);
    }
    assert_eq!(engine.views.len(), cap, "rotation fills the cap");
    engine.scheduler.set_max_evictions_for_test(1);
    engine
        .scheduler
        .begin_deep_scan_tick(crate::attach::monotonic_ns());
    let (waiters_g, _hold2) = opus_spawn_static_sleeps(3);
    let waiters: Vec<u32> = waiters_g.iter().map(|guard| guard.pid()).collect();
    let mut listing = sleep_pids.clone();
    for waiter in &waiters {
        listing.push(*waiter);
    }
    listing.sort_unstable();
    e06_write_listing(scope_dir.path(), &listing);
    let mut outcomes = Vec::new();
    for waiter in &waiters {
        // Advance to the pass before a reconcile (B4's parity rule).
        let mut guard = 0;
        while engine.scheduler.over_cap_passes().is_multiple_of(2) {
            refresh_inventory_once(&mut engine);
            guard += 1;
            assert!(guard < 8);
        }
        assert!(engine.request_refresh(*waiter, crate::attach::monotonic_ns()));
        let before = engine.scheduler.reconcile_sweeps_for_test();
        refresh_inventory_once(&mut engine);
        assert!(
            engine.scheduler.reconcile_sweeps_for_test() > before,
            "a reconcile pass"
        );
        let settled = opus_probe_view_pids(&engine).contains(waiter);
        eprintln!(
            "OPUS-B4H waiter={waiter} settled_in_its_sweep={settled} views={}",
            engine.views.len()
        );
        outcomes.push(settled);
    }
    assert!(
        outcomes.iter().all(|settled| *settled),
        "a fresh waiter lost the only freed slot: {outcomes:?}"
    );
}

/// Scarce owed debt is repaid by a pending-backlog attempt: at a full
/// view cap with no evictable view, one fresh and two pending-backlog
/// pids, one attempt per truncated tick. Tick 1 serves the fresh pid
/// (higher pid, so pid order alone would serve it last); tick 2, with a
/// second fresh request, serves the pending backlog first (the owed
/// lead); tick 3 serves the waiting fresh pid first (the debt was
/// repaid, so the lead returns to newcomers). Two backlogs keep one
/// remaining on tick 3 to observe the cleared debt — with one backlog,
/// tick 3 would have no backlog and the routing would be unobservable.
/// Recording the tick-2 backlog attempt bare (M24) leaves the debt set,
/// so tick 3 would serve backlog first instead of fresh.
#[test]
fn scarce_backlog_attempt_repays_owed_debt() {
    let dir = tempfile::tempdir().expect("a fixture directory");
    let provider = system_scope_build_fixture(dir.path(), "scarce-owed");
    let driver = system_scope_build_driver(dir.path());
    let loaded = system_scope_spawn_loaded(&driver, &provider);
    let owner_pid = loaded.pid();
    let mut sleeps = e06_spawn_sleeps(4);
    sleeps.sort_by_key(SystemScopeChildGuard::pid);
    let (backlog1, backlog2, fresh1, fresh2) = (
        sleeps[0].pid(),
        sleeps[1].pid(),
        sleeps[2].pid(),
        sleeps[3].pid(),
    );
    let scope_dir = tempfile::tempdir().expect("a scope directory");
    e06_write_listing(scope_dir.path(), &[owner_pid]);
    let scope = crate::scope::cgroup(scope_dir.path()).expect("open scope directory");
    let args = e06_cgroup_args(scope_dir.path(), vec![provider], Some(1));
    let mut engine = Engine::discover(&args, &scope, None).expect("a capped cgroup captures");
    assert_eq!(engine.views.len(), 1);
    engine.scheduler.set_tick_quantum_ns_for_test(1_000);
    assert!(
        engine.find_evictable_victim_for_selected(fresh1).is_none(),
        "no victim: the retained view owns its provider"
    );
    let mut listing = vec![owner_pid, backlog1, backlog2, fresh1];
    listing.sort_unstable();
    e06_write_listing(scope_dir.path(), &listing);
    assert!(engine.request_refresh(backlog1, Some(100)));
    assert!(engine.request_refresh(backlog2, Some(110)));
    assert!(engine.request_refresh(fresh1, Some(200)));
    engine.scheduler.begin_deep_scan_tick(Some(150));
    opus_probe_refresh_with_permits(&mut engine, 1);
    assert!(
        !engine.refresh_requested.contains_key(&fresh1),
        "tick 1 serves the fresh pid first"
    );
    assert!(
        engine.refresh_requested.contains_key(&backlog1)
            && engine.refresh_requested.contains_key(&backlog2),
        "both backlogs wait another tick"
    );
    assert_eq!(engine.probationary_completions, 1);
    listing.push(fresh2);
    listing.sort_unstable();
    e06_write_listing(scope_dir.path(), &listing);
    assert!(engine.request_refresh(fresh2, Some(2_000_000)));
    opus_probe_refresh_with_permits(&mut engine, 1);
    assert!(
        !engine.refresh_requested.contains_key(&backlog1),
        "tick 2 serves the pending backlog first (the owed lead)"
    );
    assert!(
        engine.refresh_requested.contains_key(&backlog2)
            && engine.refresh_requested.contains_key(&fresh2),
        "the second backlog and the second fresh wait"
    );
    assert_eq!(engine.probationary_completions, 2);
    opus_probe_refresh_with_permits(&mut engine, 1);
    assert!(
        !engine.refresh_requested.contains_key(&fresh2),
        "tick 3 serves the waiting fresh pid first (the debt was repaid)"
    );
    assert!(
        engine.refresh_requested.contains_key(&backlog2),
        "the remaining backlog waits"
    );
    assert_eq!(engine.probationary_completions, 3);
    opus_probe_refresh_with_permits(&mut engine, 1);
    assert!(
        !engine.refresh_requested.contains_key(&backlog2),
        "the remaining backlog completes last"
    );
    assert_eq!(engine.probationary_completions, 4);
}

/// Scarce owed debt repaid through an eviction-freed slot: the same
/// one-fresh-plus-two-backlog choreography as
/// `scarce_backlog_attempt_repays_owed_debt`, but every serving pass
/// reconciles one exploratory view away first, so the attempt records
/// through the free-slot path instead of the viewless probe path. Odd
/// passes serve nothing (full cap, and the probe skips past the
/// evictable view); even passes evict and serve one pid each: fresh,
/// then backlog (the owed lead), then fresh (the debt repaid), then
/// the remaining backlog. Recording the freed-slot backlog attempt
/// bare leaves the debt set, so the third serving pass would lead
/// backlog instead of fresh; recording the fresh attempt bare never
/// raises the debt, so the second serving pass would lead fresh.
/// Zero viewless completions throughout prove the probe path never ran.
#[test]
fn scarce_backlog_attempt_repays_owed_debt_with_eviction_freed_slot() {
    let dir = tempfile::tempdir().expect("a fixture directory");
    let provider = system_scope_build_fixture(dir.path(), "scarce-owed-slot");
    let driver = system_scope_build_driver(dir.path());
    let loaded = system_scope_spawn_loaded(&driver, &provider);
    let owner_pid = loaded.pid();
    // The evictable sleeper spawns before the choreography pids, so the
    // discovery cursor parks below them and every window rotation starts
    // at the lowest choreography pid.
    let parked = e06_spawn_sleeps(1);
    let parked_pid = parked[0].pid();
    let mut sleeps = e06_spawn_sleeps(4);
    sleeps.sort_by_key(SystemScopeChildGuard::pid);
    let (backlog1, backlog2, fresh1, fresh2) = (
        sleeps[0].pid(),
        sleeps[1].pid(),
        sleeps[2].pid(),
        sleeps[3].pid(),
    );
    let scope_dir = tempfile::tempdir().expect("a scope directory");
    e06_write_listing(scope_dir.path(), &[owner_pid, parked_pid]);
    let scope = crate::scope::cgroup(scope_dir.path()).expect("open scope directory");
    let args = e06_cgroup_args(scope_dir.path(), vec![provider], Some(2));
    let mut engine = Engine::discover(&args, &scope, None).expect("a capped cgroup captures");
    assert_eq!(engine.views.len(), 2);
    engine.scheduler.set_quantum_ns_for_test(u64::MAX);
    engine.scheduler.set_tick_quantum_ns_for_test(1_000);
    engine.scheduler.set_max_evictions_for_test(1);
    assert!(
        engine.find_evictable_victim_for_selected(fresh1).is_some(),
        "the parked sleeper view is the evictable victim"
    );
    // Pass 1 (ordinary): only the two backlogs wait, so the single-class
    // window leads the lowest — which defers at the full cap instead of
    // probing, because the parked view is evictable.
    let mut listing = vec![owner_pid, parked_pid, backlog1, backlog2, fresh1];
    listing.sort_unstable();
    e06_write_listing(scope_dir.path(), &listing);
    assert!(engine.request_refresh(backlog1, Some(100)));
    assert!(engine.request_refresh(backlog2, Some(110)));
    engine.scheduler.begin_deep_scan_tick(Some(150));
    opus_probe_refresh_with_permits(&mut engine, 1);
    assert!(
        engine.refresh_requested.contains_key(&backlog1)
            && engine.refresh_requested.contains_key(&backlog2),
        "pass 1 defers both backlogs past the evictable view"
    );
    assert_eq!(engine.views.len(), 2);
    assert_eq!(engine.probationary_completions, 0);
    // Both fresh pids request after the ordinary pass, newer than any
    // working tick, so every later pass classifies them as newcomers.
    listing.push(fresh2);
    listing.sort_unstable();
    e06_write_listing(scope_dir.path(), &listing);
    assert!(engine.request_refresh(fresh1, Some(2_000_000)));
    assert!(engine.request_refresh(fresh2, Some(2_000_000)));
    // Pass 2 (reconcile): evicts the parked view and serves the fresh
    // pid first through the freed slot.
    opus_probe_refresh_with_permits(&mut engine, 1);
    let viewed = opus_probe_view_pids(&engine);
    assert!(
        !viewed.contains(&parked_pid),
        "pass 2 evicted the parked view"
    );
    assert!(
        !engine.refresh_requested.contains_key(&fresh1) && viewed.contains(&fresh1),
        "pass 2 serves the fresh pid first through the freed slot"
    );
    assert!(
        engine.refresh_requested.contains_key(&backlog1)
            && engine.refresh_requested.contains_key(&backlog2)
            && engine.refresh_requested.contains_key(&fresh2),
        "the backlogs and the second fresh wait"
    );
    assert_eq!(engine.probationary_completions, 0);
    // Pass 3 (ordinary): the owed window leads backlog, which defers at
    // the full cap; the debt survives the zero-attempt pass.
    opus_probe_refresh_with_permits(&mut engine, 1);
    assert!(
        engine.refresh_requested.contains_key(&backlog1)
            && engine.refresh_requested.contains_key(&backlog2)
            && engine.refresh_requested.contains_key(&fresh2),
        "pass 3 defers everything past the evictable fresh view"
    );
    assert_eq!(engine.probationary_completions, 0);
    // Pass 4 (reconcile): evicts the fresh view and serves the pending
    // backlog first — the owed lead, recorded through the freed slot.
    opus_probe_refresh_with_permits(&mut engine, 1);
    let viewed = opus_probe_view_pids(&engine);
    assert!(
        !engine.refresh_requested.contains_key(&backlog1) && viewed.contains(&backlog1),
        "pass 4 serves the pending backlog first (the owed lead)"
    );
    assert!(
        engine.refresh_requested.contains_key(&backlog2)
            && engine.refresh_requested.contains_key(&fresh2),
        "the second backlog and the second fresh wait"
    );
    assert_eq!(engine.probationary_completions, 0);
    // Pass 5 (ordinary): the repaid window leads fresh, which defers at
    // the full cap.
    opus_probe_refresh_with_permits(&mut engine, 1);
    assert!(
        engine.refresh_requested.contains_key(&backlog2)
            && engine.refresh_requested.contains_key(&fresh2),
        "pass 5 defers the backlog and the fresh past the evictable view"
    );
    assert_eq!(engine.probationary_completions, 0);
    // Pass 6 (reconcile): evicts the backlog view and serves the waiting
    // fresh pid first — the debt was repaid, so the lead is newcomer.
    opus_probe_refresh_with_permits(&mut engine, 1);
    let viewed = opus_probe_view_pids(&engine);
    assert!(
        !engine.refresh_requested.contains_key(&fresh2) && viewed.contains(&fresh2),
        "pass 6 serves the waiting fresh pid first (the debt was repaid)"
    );
    assert!(
        engine.refresh_requested.contains_key(&backlog2),
        "the remaining backlog waits"
    );
    assert_eq!(engine.probationary_completions, 0);
    // Pass 7 (ordinary): the lone backlog defers at the full cap.
    opus_probe_refresh_with_permits(&mut engine, 1);
    assert!(
        engine.refresh_requested.contains_key(&backlog2),
        "pass 7 defers the lone backlog past the evictable view"
    );
    assert_eq!(engine.probationary_completions, 0);
    // Pass 8 (reconcile): the remaining backlog completes last, and no
    // request survives the choreography.
    opus_probe_refresh_with_permits(&mut engine, 1);
    let viewed = opus_probe_view_pids(&engine);
    assert!(
        !engine.refresh_requested.contains_key(&backlog2) && viewed.contains(&backlog2),
        "the remaining backlog completes last"
    );
    assert!(engine.refresh_requested.is_empty());
    assert_eq!(engine.probationary_completions, 0);
}

/// A failed scarce rotation attempt through an eviction-freed slot
/// records bare: the rotation pid never enters the failed-newcomer
/// list, so the next free-slots window does not sink it behind untried
/// backlog. Recording the rotation attempt classified would rotate it
/// into the sink at that window instead.
#[test]
fn failed_scarce_rotation_attempt_skips_failed_newcomer_sink() {
    let dir = tempfile::tempdir().expect("a fixture directory");
    let provider = system_scope_build_fixture(dir.path(), "scarce-rot-sink");
    let driver = system_scope_build_driver(dir.path());
    let loaded = system_scope_spawn_loaded(&driver, &provider);
    let owner_pid = loaded.pid();
    let parked = e06_spawn_sleeps(1);
    let parked_pid = parked[0].pid();
    let mut doomed = e06_spawn_sleeps(1);
    let rotation_pid = doomed[0].pid();
    doomed[0].reap().expect("reap the rotation candidate");
    let scope_dir = tempfile::tempdir().expect("a scope directory");
    e06_write_listing(scope_dir.path(), &[owner_pid, parked_pid]);
    let scope = crate::scope::cgroup(scope_dir.path()).expect("open scope directory");
    let args = e06_cgroup_args(scope_dir.path(), vec![provider], Some(2));
    let mut engine = Engine::discover(&args, &scope, None).expect("a capped cgroup captures");
    assert_eq!(engine.views.len(), 2);
    engine.scheduler.set_quantum_ns_for_test(u64::MAX);
    engine.scheduler.set_tick_quantum_ns_for_test(1_000);
    engine.scheduler.set_max_evictions_for_test(1);
    // Pass 1 (ordinary): the dead pid holds no request and no free
    // rotation slot exists, so the pass desires nothing new and opens no
    // window.
    let mut listing = vec![owner_pid, parked_pid, rotation_pid];
    listing.sort_unstable();
    e06_write_listing(scope_dir.path(), &listing);
    opus_probe_refresh_with_permits(&mut engine, 1);
    assert_eq!(engine.views.len(), 2);
    // Pass 2 (reconcile): evicts the parked view, selects the dead pid
    // as the only rotation candidate, and attempts it through the freed
    // slot; the open fails and no view is added.
    opus_probe_refresh_with_permits(&mut engine, 1);
    assert_eq!(engine.views.len(), 1, "the failed open adds no view");
    assert_eq!(
        engine.scheduler.new_view_cursor_for_test(),
        Some(rotation_pid),
        "the rotation pid was attempted through the freed slot"
    );
    assert_eq!(engine.probationary_completions, 0);
    // Pass 3 (ordinary): one view under a cap of two with no eviction,
    // so a free-slots window opens — and the failed rotation pid is not
    // in the failed-newcomer sink it settles.
    opus_probe_refresh_with_permits(&mut engine, 1);
    assert!(
        !engine
            .scheduler
            .last_newcomer_attempts_for_test()
            .contains(&rotation_pid),
        "the failed rotation attempt never entered the failed-newcomer list"
    );
}

/// P1-5: one bad pass must not abort the whole capture. Fault-inject
/// `apply_candidate` failing in the second pass: the batch still
/// returns Ok, earlier committed views survive, and a counted named
/// gap records the dropped pass.
#[test]
fn dropped_apply_keeps_earlier_data_and_names_gap() {
    let mut child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let pid = child.id();
    let (mut engine, _dir) = engine_over_cgroup_naming(&[pid]);
    let mut session = ScriptedSession::with_records([], 0);
    apply_ordinary_batch(&mut engine, &mut session, vec![]).unwrap();
    assert_eq!(engine.views.len(), 1, "first pass admits the live member");
    assert!(engine.request_refresh(pid, None));
    engine.fail_next_apply_for_test = true;
    let outcome = apply_ordinary_batch(&mut engine, &mut session, vec![])
        .expect("a dropped pass still returns Ok");
    assert!(
        !outcome.required_complete,
        "a dropped pass never confirms completeness"
    );
    assert_eq!(
        engine.views.len(),
        1,
        "earlier committed view survives the dropped pass"
    );
    assert_eq!(engine.views[0].pid(), pid);
    assert!(
        engine.counters.object_skips.iter().any(|skip| {
            skip.reason.contains("dropped") && skip.reason.contains("test-forced apply")
        }),
        "a counted named gap records the dropped pass: {:?}",
        engine.counters.object_skips
    );
    child.kill().unwrap();
    child.wait().unwrap();
}

