/// Drives rounds until one more pass with `error` has dropped (bounded):
/// an incidental healthy round under load only costs an extra round.
fn drop_one_more_pass(
    engine: &mut Engine,
    session: &mut ScriptedSession,
    pid: u32,
    error: &str,
    forced: bool,
) {
    let before = engine.dropped_pass_count_for_test(error);
    for _round in 0..12 {
        assert!(engine.request_refresh(pid, None));
        if forced {
            engine.fail_next_apply_for_test = true;
        }
        apply_ordinary_batch(engine, session, vec![]).expect("a dropped pass still returns Ok");
        if engine.dropped_pass_count_for_test(error) > before {
            return;
        }
    }
    panic!("no pass dropped with {error:?} within twelve rounds");
}

fn published_inventory_pass_gaps(engine: &Engine) -> Vec<&Skipped> {
    engine
        .plan
        .skipped
        .iter()
        .filter(|skip| skip.subject == "live inventory pass")
        .collect()
}

/// However many passes drop, the published plan (which the capture JSON
/// `evidence.skipped` maps one to one) holds exactly one dropped-pass
/// gap, and its reason stays the first drop's text: every publishing
/// layer keys gaps by subject plus reason and only adds, so a rewritten
/// reason would publish one entry per drop.
#[test]
fn repeated_drops_publish_exactly_one_fixed_gap() {
    const ERROR: &str = "test-forced apply failure";
    let mut child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let pid = child.id();
    let (mut engine, _dir) = engine_over_cgroup_naming(&[pid]);
    let mut session = ScriptedSession::with_records([], 0);
    apply_ordinary_batch(&mut engine, &mut session, vec![]).unwrap();
    assert_eq!(engine.views.len(), 1);
    engine.scheduler.set_tick_quantum_ns_for_test(u64::MAX);
    drop_one_more_pass(&mut engine, &mut session, pid, ERROR, true);
    let first: Vec<Skipped> = published_inventory_pass_gaps(&engine)
        .into_iter()
        .cloned()
        .collect();
    assert_eq!(first.len(), 1, "the first drop publishes its gap: {first:?}");
    assert!(
        first[0].reason.starts_with("pass ")
            && first[0].reason.ends_with(&format!("dropped: {ERROR}")),
        "{first:?}"
    );
    for _ in 0..3 {
        drop_one_more_pass(&mut engine, &mut session, pid, ERROR, true);
    }
    assert_eq!(engine.dropped_pass_count_for_test(ERROR), 4);
    let published = published_inventory_pass_gaps(&engine);
    assert_eq!(
        published.len(),
        1,
        "one published gap however many passes drop: {:?}",
        engine.plan.skipped
    );
    assert_eq!(
        *published[0], first[0],
        "the published reason is never rewritten"
    );
    let internal: Vec<_> = engine
        .counters
        .object_skips
        .iter()
        .filter(|skip| skip.subject == "live inventory pass")
        .collect();
    assert_eq!(internal, vec![&first[0]], "one internal gap as well");
    let projected: Vec<_> = engine
        .plan
        .skipped
        .iter()
        .map(crate::render::capture_skipped_out)
        .filter(|skip| skip.reason == "discovery unavailable")
        .collect();
    assert!(
        !projected.is_empty(),
        "the gap projects to a schema reason in the capture JSON"
    );
    child.kill().unwrap();
    child.wait().unwrap();
}

/// A healthy tick resets the consecutive-drop chain: drop, healthy,
/// drop, drop still keeps the serviced request queued for retry.
#[test]
fn healthy_tick_resets_the_consecutive_drop_chain() {
    const ERROR: &str = "test-forced apply failure";
    let mut child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let pid = child.id();
    let (mut engine, _dir) = engine_over_cgroup_naming(&[pid]);
    let mut session = ScriptedSession::with_records([], 0);
    apply_ordinary_batch(&mut engine, &mut session, vec![]).unwrap();
    engine.scheduler.set_tick_quantum_ns_for_test(u64::MAX);
    drop_one_more_pass(&mut engine, &mut session, pid, ERROR, true);
    assert_eq!(engine.consecutive_dropped_passes, 1);
    let mut healthy = false;
    for _round in 0..12 {
        assert!(engine.request_refresh(pid, None));
        apply_ordinary_batch(&mut engine, &mut session, vec![]).unwrap();
        if !engine.refresh_requested.contains_key(&pid) {
            healthy = true;
            break;
        }
    }
    assert!(healthy, "a healthy tick completes the request");
    assert_eq!(engine.dropped_pass_count_for_test(ERROR), 1);
    assert_eq!(
        engine.consecutive_dropped_passes, 0,
        "the healthy tick breaks the chain"
    );
    drop_one_more_pass(&mut engine, &mut session, pid, ERROR, true);
    drop_one_more_pass(&mut engine, &mut session, pid, ERROR, true);
    assert_eq!(engine.consecutive_dropped_passes, 2);
    assert!(
        engine.refresh_requested.contains_key(&pid),
        "two drops after a healthy tick still retain the request for retry"
    );
    child.kill().unwrap();
    child.wait().unwrap();
}

/// Only tick drops count toward the consecutive-drop chain: a dropped
/// batch-tail publication must not shorten the tick retry window.
#[test]
fn dropped_tail_does_not_count_toward_the_tick_drop_chain() {
    let (mut engine, _raw) = retained_publication_engine(213, 1);
    engine.publish_batch_tail(false).unwrap();
    engine.manifest_ordinals.push(0); // No parallel manifest: the real merge refuses.
    engine.note_facts_mutated(); // Force the merge attempt the drop needs.
    engine
        .publish_batch_tail(false)
        .expect("a dropped tail still returns Ok");
    assert!(
        engine
            .counters
            .object_skips
            .iter()
            .any(|skip| skip.subject == "live inventory pass"),
        "the tail drop is recorded: {:?}",
        engine.counters.object_skips
    );
    assert_eq!(engine.consecutive_dropped_passes, 0);
}

/// Disclosed limit pin: a not-yet-admitted process whose inputs break
/// every tick candidate is offered again on every tick, so it is never
/// admitted; escalation completes the other serviced requests without
/// applying them, and the capture keeps going with one published gap.
#[test]
fn poisoned_newcomer_is_never_admitted_and_publishes_one_gap() {
    const ERROR: &str = "test-forced poisoned candidate failure";
    let mut kept = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let kept_pid = kept.id();
    let (mut engine, dir) = engine_over_cgroup_naming(&[kept_pid]);
    let mut session = ScriptedSession::with_records([], 0);
    apply_ordinary_batch(&mut engine, &mut session, vec![]).unwrap();
    assert_eq!(engine.views.len(), 1);
    engine.scheduler.set_tick_quantum_ns_for_test(u64::MAX);
    let mut poison = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let poison_pid = poison.id();
    std::fs::write(
        dir.path().join("cgroup.procs"),
        format!("{kept_pid}\n{poison_pid}\n"),
    )
    .unwrap();
    engine.fail_candidate_with_pid_for_test = Some(poison_pid);
    for _ in 0..4 {
        drop_one_more_pass(&mut engine, &mut session, kept_pid, ERROR, false);
    }
    let pids: Vec<_> = engine.views.iter().map(ProcessView::pid).collect();
    assert_eq!(pids, vec![kept_pid], "the poisoned newcomer stays unadmitted");
    assert!(
        !engine.refresh_requested.contains_key(&kept_pid),
        "past the retain limit the unrelated request completes unapplied"
    );
    assert_eq!(
        published_inventory_pass_gaps(&engine).len(),
        1,
        "{:?}",
        engine.plan.skipped
    );
    let _ = kept.kill();
    let _ = kept.wait();
    let _ = poison.kill();
    let _ = poison.wait();
}

/// The first two consecutive drops retain serviced requests for retry
/// (transient recovery); the third completes them so a persistently
/// poisoned tick stops blocking all later discovery. The loop keys
/// off the drop count and completion: with one error text, fewer than
/// three drops cannot have completed anything, and an incidental
/// healthy round under load only costs extra iterations.
#[test]
fn third_consecutive_drop_completes_serviced_requests() {
    let mut child = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let pid = child.id();
    let (mut engine, _dir) = engine_over_cgroup_naming(&[pid]);
    let mut session = ScriptedSession::with_records([], 0);
    apply_ordinary_batch(&mut engine, &mut session, vec![]).unwrap();
    assert_eq!(engine.views.len(), 1);
    engine.scheduler.set_tick_quantum_ns_for_test(u64::MAX);
    let mut completed = false;
    for _round in 0..12 {
        assert!(engine.request_refresh(pid, None));
        engine.fail_next_apply_for_test = true;
        apply_ordinary_batch(&mut engine, &mut session, vec![])
            .expect("a dropped pass still returns Ok");
        if engine.dropped_pass_count_for_test("test-forced apply failure") < 3 {
            assert!(
                engine.refresh_requested.contains_key(&pid),
                "fewer than three drops retain the serviced request for retry"
            );
        }
        if !engine.refresh_requested.contains_key(&pid) {
            completed = true;
            break;
        }
    }
    assert!(
        completed,
        "three consecutive drops complete the serviced request within twelve rounds"
    );
    assert!(
        engine.dropped_pass_count_for_test("test-forced apply failure") >= 3,
        "completion needs at least three drops"
    );
    apply_ordinary_batch(&mut engine, &mut session, vec![])
        .expect("the capture continues after the escalation drop");
    assert_eq!(engine.views.len(), 1);
    child.kill().unwrap();
    child.wait().unwrap();
}

/// A process whose data persistently breaks the tick candidate stops
/// blocking other discovery: after the escalation drop completes its
/// request, a later tick builds a candidate without its poisoned
/// inputs and admits a newcomer. The loop keys off completion: the
/// poisoned request can only complete through escalation, and an
/// incidental healthy round under load only costs extra iterations.
#[test]
fn persistently_poisoned_tick_stops_blocking_newcomers() {
    let mut poison = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let poison_pid = poison.id();
    let (mut engine, dir) = engine_over_cgroup_naming(&[poison_pid]);
    let mut session = ScriptedSession::with_records([], 0);
    apply_ordinary_batch(&mut engine, &mut session, vec![]).unwrap();
    assert_eq!(engine.views.len(), 1);
    engine.scheduler.set_tick_quantum_ns_for_test(u64::MAX);
    let mut newcomer = std::process::Command::new("sleep")
        .arg("30")
        .die_with_parent()
        .spawn()
        .unwrap();
    let newcomer_pid = newcomer.id();
    std::fs::write(
        dir.path().join("cgroup.procs"),
        format!("{poison_pid}\n{newcomer_pid}\n"),
    )
    .unwrap();
    engine.fail_candidate_with_pid_for_test = Some(poison_pid);
    let mut completed = false;
    for _round in 0..12 {
        assert!(engine.request_refresh(poison_pid, None));
        apply_ordinary_batch(&mut engine, &mut session, vec![])
            .expect("poisoned passes drop, never abort");
        if !engine.refresh_requested.contains_key(&poison_pid) {
            completed = true;
            break;
        }
    }
    assert!(
        completed,
        "escalation completes the poisoned request within twelve rounds"
    );
    assert!(
        engine.dropped_pass_count_for_test("test-forced poisoned candidate failure") >= 3,
        "completion needs at least three drops"
    );
    apply_ordinary_batch(&mut engine, &mut session, vec![]).expect("the capture continues");
    let pids: Vec<_> = engine.views.iter().map(ProcessView::pid).collect();
    assert_eq!(
        engine.views.len(),
        2,
        "a later tick admits the newcomer without poisoned inputs: {pids:?}"
    );
    assert!(
        pids.contains(&poison_pid),
        "the poisoned view stays retained: {pids:?}"
    );
    assert!(
        pids.contains(&newcomer_pid),
        "the newcomer is admitted: {pids:?}"
    );
    let _ = poison.kill();
    let _ = poison.wait();
    let _ = newcomer.kill();
    let _ = newcomer.wait();
}

/// A dropped batch tail keeps committed provider modules, plan
/// slots and discovery modules (with their counts): the earlier-data
/// proof for modules, plan and counts, over the publication fixture.
#[test]
fn dropped_tail_keeps_committed_provider_modules_plan_and_counts() {
    let (mut engine, _raw) = retained_publication_engine(213, 1);
    engine.publish_batch_tail(false).unwrap();
    assert!(
        !engine.modules.is_empty(),
        "the fixture must commit a provider module"
    );
    let modules = engine.modules.clone();
    let slots = engine.plan.active_slot_count();
    let entries_seen = engine.plan.entries_seen;
    let discovery_modules = serde_json::to_value(&engine.discovery.modules).unwrap();
    let public_revision = engine.published_facts_revision;
    engine.manifest_ordinals.push(0); // No parallel manifest: the real merge refuses.
    engine.note_facts_mutated(); // Force the merge attempt the drop needs.
    engine
        .publish_batch_tail(false)
        .expect("a dropped tail still returns Ok");
    assert_eq!(
        engine.modules, modules,
        "committed modules survive the dropped tail"
    );
    assert_eq!(
        engine.plan.active_slot_count(),
        slots,
        "committed plan slots survive the dropped tail"
    );
    assert_eq!(
        engine.plan.entries_seen, entries_seen,
        "committed plan entries survive the dropped tail"
    );
    assert_eq!(
        serde_json::to_value(&engine.discovery.modules).unwrap(),
        discovery_modules,
        "discovery modules and their counts survive the dropped tail"
    );
    assert_eq!(
        engine.published_facts_revision, public_revision,
        "the dropped tail publishes nothing partial"
    );
    assert!(
        engine.counters.object_skips.iter().any(|skip| {
            skip.subject == "live inventory pass" && skip.reason.contains("dropped")
        }),
        "a counted named gap records the dropped tail: {:?}",
        engine.counters.object_skips
    );
}

/// End to end at the publication seam: after a dropped tail the next
/// tail still publishes, and the serialized report carries the earlier
/// provider data plus the dropped-pass gap.
#[test]
fn report_after_dropped_tail_carries_earlier_data_and_gap() {
    let (mut engine, _raw) = retained_publication_engine(213, 1);
    engine.publish_batch_tail(false).unwrap();
    assert!(
        !engine.modules.is_empty(),
        "the fixture must commit a provider module"
    );
    engine.manifest_ordinals.push(0); // No parallel manifest: the real merge refuses.
    engine.note_facts_mutated(); // Force the merge attempt the drop needs.
    engine
        .publish_batch_tail(false)
        .expect("a dropped tail still returns Ok");
    engine.manifest_ordinals.clear();
    engine.note_facts_mutated();
    engine
        .publish_batch_tail(false)
        .expect("the tail still publishes after a dropped tail");
    assert!(
        !engine.discovery.modules.is_empty(),
        "the published report keeps the earlier provider"
    );
    serde_json::to_string(&engine.discovery).expect("the report still serializes");
    assert!(
        engine.plan.skipped.iter().any(|skip| {
            skip.subject == "live inventory pass" && skip.reason.contains("dropped")
        }),
        "the published plan carries the dropped-pass gap: {:?}",
        engine.plan.skipped
    );
}
